fn feature_default(key: &str) -> bool {
    match key {
        // Games + LP rewards ship dark (default OFF) and are turned on
        // deliberately by an admin, never on a fresh install.
        FLAG_ARCADE_MINIGOLF => false,
        FLAG_ARCADE_LUCKPROOF => false,
        FLAG_ARCADE_SKYDIVE => false,
        FLAG_ARCADE_BULLRUN => false,
        FLAG_SOLANA_LP => false,
        FLAG_ICPSWAP_LP => false,
        FLAG_NAV_GOVERNANCE => false,
        FLAG_STAKE_VOUCHERS => false,
        FLAG_NAV_COMMUNITY => false,
        FLAG_X_FARM => false,
        // Every other SHIPPED feature (Lossless Voting/Lottery, Explorer,
        // Early Adopters) defaults ON; unknown keys stay OFF.
        k => KNOWN_FEATURE_FLAGS.contains(&k),
    }
}

/// Stored value → state. Legacy values 0/1 map to Off/On; 2 = AdminOn. Unset
/// falls back to the per-flag default.
fn feature_state(key: &str) -> FlagState {
    match FEATURE_FLAGS.with(|m| m.borrow().get(&key.to_string())) {
        Some(0) => FlagState::Off,
        Some(2) => FlagState::AdminOn,
        Some(_) => FlagState::On, // 1 (and any legacy non-zero)
        None => {
            if feature_default(key) {
                FlagState::On
            } else {
                FlagState::Off
            }
        }
    }
}

fn flag_state_code(s: FlagState) -> u8 {
    match s {
        FlagState::Off => 0,
        FlagState::On => 1,
        FlagState::AdminOn => 2,
    }
}

/// "On for everyone." Caller-agnostic — SAFE to call from timers (no `caller`).
/// Treats `AdminOn` as off so global background processes don't run for an
/// admin-only feature.
fn feature_enabled(key: &str) -> bool {
    matches!(feature_state(key), FlagState::On)
}

/// "Not off" — the feature is live in some capacity (On or AdminOn). Used by
/// background loops (e.g. the crash round loop) that must run so admins can use
/// the feature under `AdminOn`. Caller-agnostic.
fn feature_active(key: &str) -> bool {
    !matches!(feature_state(key), FlagState::Off)
}

/// Effective for a specific caller: On for anyone, AdminOn only for admins.
/// Only call from a message context (it needs the caller).
fn feature_visible(key: &str, caller: Principal) -> bool {
    match feature_state(key) {
        FlagState::On => true,
        FlagState::AdminOn => is_admin_principal(caller),
        FlagState::Off => false,
    }
}

fn valid_flag_key(key: &str) -> bool {
    !key.is_empty()
        && key.len() <= MAX_FLAG_KEY_LEN
        && key.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
}

/// All flags the canister knows about (known defaults merged with any extra
/// admin-created keys). Public so anonymous viewers can hide gated UI.
#[ic_cdk::query]
fn list_feature_flags() -> Vec<FeatureFlag> {
    let caller = get_caller();
    let mk = |key: String| {
        let state = feature_state(&key);
        FeatureFlag { enabled: feature_visible(&key, caller), state, key }
    };
    let mut flags: Vec<FeatureFlag> = KNOWN_FEATURE_FLAGS.iter().map(|k| mk(k.to_string())).collect();
    FEATURE_FLAGS.with(|m| {
        for entry in m.borrow().iter() {
            let key = entry.key().clone();
            if !KNOWN_FEATURE_FLAGS.contains(&key.as_str()) {
                flags.push(mk(key));
            }
        }
    });
    flags
}

/// Admin: enable/disable a feature completely. Unknown keys are allowed (a
/// kill-switch can be staged before the feature ships) but validated and
/// capped so the map can't be spammed.
#[ic_cdk::update(guard = "require_admin")]
fn admin_set_feature_flag(key: String, enabled: bool) -> Result<(), String> {
    let key = key.trim().to_string();
    if !valid_flag_key(&key) {
        return Err("INVALID_FLAG_KEY".to_string());
    }
    FEATURE_FLAGS.with(|m| {
        let mut m = m.borrow_mut();
        if m.get(&key).is_none() && m.len() >= MAX_FEATURE_FLAGS {
            return Err("TOO_MANY_FLAGS".to_string());
        }
        m.insert(key, if enabled { 1 } else { 0 });
        Ok(())
    })
}

/// Admin: set a feature's three-state flag — Off (nobody), On (everybody), or
/// AdminOn (admins only, for a live preview/playtest).
#[ic_cdk::update(guard = "require_admin")]
fn admin_set_feature_flag_state(key: String, state: FlagState) -> Result<(), String> {
    let key = key.trim().to_string();
    if !valid_flag_key(&key) {
        return Err("INVALID_FLAG_KEY".to_string());
    }
    FEATURE_FLAGS.with(|m| {
        let mut m = m.borrow_mut();
        if m.get(&key).is_none() && m.len() >= MAX_FEATURE_FLAGS {
            return Err("TOO_MANY_FLAGS".to_string());
        }
        m.insert(key, flag_state_code(state));
        Ok(())
    })
}

/// Per-token ledger. Mainnet is hard-pinned to the canonical ckBTC/ckETH
/// ledgers (overrides ignored — F-101 posture). Locally, ckBTC/ckETH resolve
/// to the admin-configured local test ledgers, falling back to the ICP test
/// ledger when none is configured yet.
fn token_ledger(token: IdeaToken, config: &Config) -> Principal {
    match token {
        IdeaToken::ICP => config.ledger_canister_id,
        IdeaToken::CkUSDC => explorer_token_ledger(ExplorerToken::CkUSDC, config),
        IdeaToken::CkUSDT => explorer_token_ledger(ExplorerToken::CkUSDT, config),
        IdeaToken::CkBTC => {
            if config.is_local {
                config.ckbtc_ledger_canister_id.unwrap_or(config.ledger_canister_id)
            } else {
                Principal::from_text(MAINNET_CKBTC_LEDGER).unwrap()
            }
        }
        IdeaToken::CkETH => {
            if config.is_local {
                config.cketh_ledger_canister_id.unwrap_or(config.ledger_canister_id)
            } else {
                Principal::from_text(MAINNET_CKETH_LEDGER).unwrap()
            }
        }
    }
}

/// Ledger transfer fee in the token's smallest unit. The fee follows the
/// resolved ledger: a local ckBTC/ckETH that falls back to the ICP test
/// ledger pays that ledger's 10_000 fee; a dedicated local token ledger is
/// deployed with the canonical fee, so the canonical value applies there too.
fn token_fee(token: IdeaToken, config: &Config) -> u64 {
    match token {
        IdeaToken::ICP => 10_000, // 0.0001 ICP
        IdeaToken::CkUSDC => explorer_token_fee(ExplorerToken::CkUSDC, config),
        IdeaToken::CkUSDT => explorer_token_fee(ExplorerToken::CkUSDT, config),
        IdeaToken::CkBTC => {
            if config.is_local && config.ckbtc_ledger_canister_id.is_none() {
                10_000
            } else {
                10 // 10 satoshi
            }
        }
        IdeaToken::CkETH => {
            if config.is_local && config.cketh_ledger_canister_id.is_none() {
                10_000
            } else {
                2_000_000_000_000 // 0.000002 ckETH
            }
        }
    }
}

/// Admin: point ckBTC/ckETH at locally deployed test ledgers. Local-only —
/// mainnet token ledgers are hard-pinned to the canonical canisters.
#[ic_cdk::update(guard = "require_admin")]
fn admin_set_token_ledger(token: IdeaToken, ledger: Principal) -> Result<(), String> {
    if ledger == Principal::anonymous() {
        return Err("INVALID_LEDGER".to_string());
    }
    CONFIG.with(|cell| {
        let mut cfg = cell.borrow().get().clone();
        if !cfg.is_local {
            return Err("MAINNET_LEDGERS_PINNED".to_string());
        }
        match token {
            IdeaToken::ICP => return Err("ICP_LEDGER_FIXED".to_string()),
            IdeaToken::CkUSDC | IdeaToken::CkUSDT => return Err("USE_EXPLORER_LEDGER_SETTER".to_string()),
            IdeaToken::CkBTC => cfg.ckbtc_ledger_canister_id = Some(ledger),
            IdeaToken::CkETH => cfg.cketh_ledger_canister_id = Some(ledger),
        }
        cell.borrow_mut().set(cfg);
        Ok(())
    })
}

