/// Enter today's run. One attempt per UTC day off-local (starting consumes
/// it); stakers only, like the other Play-to-Earn dailies.
#[ic_cdk::update]
fn start_bullrun_daily() -> Result<BullRunStart, String> {
    require_authenticated()?;
    require_arcade_game_enabled(ARCADE_GAME_BULLRUN)?;
    let caller = get_caller();
    if !author_is_staked(caller) {
        return Err("NOT_STAKED".to_string());
    }
    let now = current_time();
    let day = epoch_day(now);
    let is_local = CONFIG.with(|c| c.borrow().get().is_local);
    if !is_local {
        if BULLRUN_DAILY.with(|m| m.borrow().contains_key(&BullRunDayKey { day, player: caller })) {
            return Err("ALREADY_PLAYED_TODAY".to_string());
        }
        let in_flight = BULLRUN_RUNS.with(|m| {
            m.borrow().iter().any(|e| {
                let r = e.value();
                r.player == caller && r.day == day
            })
        });
        if in_flight {
            return Err("ALREADY_PLAYED_TODAY".to_string());
        }
    }
    let id = NEXT_BULLRUN_ID.with(|c| {
        let v = *c.borrow().get();
        let _ = c.borrow_mut().set(v + 1);
        v
    });
    BULLRUN_RUNS.with(|m| {
        m.borrow_mut().insert(id, BullRunRun { id, player: caller, day, issued_at: now, completed: false });
    });
    Ok(BullRunStart { run_id: id, day, course_seed: bullrun_day_seed(day), hits_limit: BULLRUN_MAX_HITS, issued_at: now })
}

/// Submit the finish: coins picked up + start→arena time. Bounds-validated
/// (coins can never exceed the course's fixed total).
#[ic_cdk::update]
fn complete_bullrun_daily(run_id: u64, coins: u32, millis: u64) -> Result<u32, String> {
    require_authenticated()?;
    require_arcade_game_enabled(ARCADE_GAME_BULLRUN)?;
    let caller = get_caller();
    let now = current_time();
    let mut run = BULLRUN_RUNS.with(|m| m.borrow().get(&run_id)).ok_or("RUN_NOT_FOUND")?;
    if run.player != caller {
        return Err("NOT_YOUR_RUN".to_string());
    }
    if run.completed {
        return Err("ALREADY_COMPLETED".to_string());
    }
    if now.saturating_sub(run.issued_at) > BULLRUN_RUN_TTL_NS {
        return Err("RUN_EXPIRED".to_string());
    }
    if !(BULLRUN_MIN_MILLIS..=BULLRUN_MAX_MILLIS).contains(&millis) {
        return Err("INVALID_TIME".to_string());
    }
    // The coin cap keys off the validated run length.
    if (coins as u64) > (millis / 1_000) * BULLRUN_COIN_RATE_CAP + 20 {
        return Err("INVALID_COINS".to_string());
    }
    // Completion CONSUMES the run journal (owner 2026-07-06).
    BULLRUN_RUNS.with(|m| { m.borrow_mut().remove(&run_id); });
    BULLRUN_DAILY.with(|m| {
        m.borrow_mut().insert(
            BullRunDayKey { day: run.day, player: caller },
            BullRunDailyEntry { day: run.day, player: caller, coins, millis, submitted_at: now },
        );
    });
    let rank = get_bullrun_daily_board(Some(run.day))
        .into_iter()
        .find(|r| r.player == caller)
        .map(|r| r.rank)
        .unwrap_or(0);
    Ok(rank)
}

// ── ANSEM LP Rewards (Solana chain fusion) ───────────────────────────────────
// Rewards $ANSEM liquidity providers on Solana with 10 lottery tickets per
// drawing. The user proves wallet ownership ONCE by signing a challenge in
// their Solana wallet (plain Ed25519 over bytes — verified right here, no
// chain call); then, once per lottery round, `claim_lp_reward` derives the
// wallet's associated token account for each admin-configured LP mint and
// reads the LIVE balance through the NNS SOL RPC canister
// (tghme-zyaaa-aaaar-qarca-cai, 3-provider Equality consensus, paid in
// attached cycles). Any balance ≥ the pool's floor → tickets. Claims key on
// the lottery round, so every drawing re-arms the claim — that IS the
// owner-required re-confirmation. Staking stays REQUIRED (owner decision
// 2026-07-04): the grant path's stakers-only gate is enforced up front.
//
// MVP scope: fungible LP mints only (PumpSwap = Token-2022 LP; classic SPL
// also supported via config). Meteora DLMM/DAMM-v2 positions are NOT LP
// tokens and are out of scope (see okf/ideas/ansem-lp-reward).

const SOL_RPC_CANISTER: &str = "tghme-zyaaa-aaaar-qarca-cai";
/// Cycles attached per SOL RPC read (excess is refunded by the SOL RPC canister).
const SOL_RPC_CYCLES: u128 = 10_000_000_000;
const LP_TICKETS_PER_ROUND: u64 = 10;
/// Challenge freshness window.
const LP_CHALLENGE_MAX_TTL_NS: u64 = 15 * 60 * 1_000_000_000;
const ATA_PROGRAM_B58: &str = "ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL";
const TOKEN_PROGRAM_B58: &str = "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA";
const TOKEN_2022_PROGRAM_B58: &str = "TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb";

