thread_local! {
    /// MemoryId 122: (pool, position id) → staker record. THE custody registry.
    static STAKED_LP: RefCell<StableBTreeMap<IcpLpKey, StakedLpPosition, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableBTreeMap::init(mm.borrow().get(MemoryId::new(122)))));
    /// MemoryId 123: (lottery round, user) → ticket grant guard.
    static ICP_LP_ROUND_GRANTS: RefCell<StableBTreeMap<IcpLpRoundKey, u8, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableBTreeMap::init(mm.borrow().get(MemoryId::new(123)))));
    /// MemoryId 124: qualifying pools (admin-configured).
    static ICPSWAP_POOLS: RefCell<StableCell<IcpLpPoolsCfg, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableCell::init(mm.borrow().get(MemoryId::new(124)), IcpLpPoolsCfg::default())));
    /// MemoryId 125: lifetime totals + notify retry queue + harvest throttle.
    static ICP_LP_STATS: RefCell<StableCell<IcpLpStats, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableCell::init(mm.borrow().get(MemoryId::new(125)), IcpLpStats::default())));
    /// MemoryId 126: (pool, position id) → reservation. RESERVE-FIRST is the
    /// anti-sniping rule: a position id is only registrable by whoever
    /// reserved it BEFORE transferring — so nobody ever sends a position we
    /// haven't already bound to them, and an attacker who sees a position
    /// arrive can't race the register call to steal it.
    static LP_RESERVATIONS: RefCell<StableBTreeMap<IcpLpKey, LpReservation, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableBTreeMap::init(mm.borrow().get(MemoryId::new(126)))));
    /// Native/local mocks for the ICPSwap pool calls.
    static MOCK_ICPSWAP_OUR_POSITIONS: RefCell<std::collections::HashMap<Principal, Vec<u128>>> =
        RefCell::new(std::collections::HashMap::new());
    static MOCK_ICPSWAP_CLAIMS: RefCell<std::collections::HashMap<(Principal, u128), (u64, u64)>> =
        RefCell::new(std::collections::HashMap::new());
    static MOCK_ICPSWAP_TRANSFERS: RefCell<Vec<(Principal, Principal, u128)>> =
        RefCell::new(Vec::new());
    /// (pool, position id) → (token0Amount, token1Amount) for valuation mocks.
    static MOCK_ICPSWAP_AMOUNTS: RefCell<std::collections::HashMap<(Principal, u128), (u128, u128)>> =
        RefCell::new(std::collections::HashMap::new());
    /// Heap backoff: after a valuation failure, don't hammer the pool every
    /// 300s sweep — retry hourly. Reset on upgrade (first sweep re-tries).
    static ICP_LP_VALUATION_BACKOFF_UNTIL: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
}

// ── Uniswap-v3 tick math (positions valued canister-side) ──────────────────
//
// Why: the pool's own getUserPositionWithTokenAmount page-scan exceeds the
// 5B-instruction limit inside big mainnet pools (IC0522, seen live on
// ICP/ckUSDC). Instead we fetch OUR positions via the principal-indexed
// getUserPositionsByPrincipal (cheap) + the pool's metadata() (sqrtPriceX96),
// and do the constant-product math ourselves. Implementation mirrors
// Uniswap v3-core TickMath.getSqrtRatioAtTick / LiquidityAmounts.

use primitive_types::{U256, U512};

const TICK_MATH_MAX_TICK: i32 = 887_272;
/// Q64.96 fixed-point one (2^96).
fn q96() -> U256 { U256::one() << 96 }

/// Uniswap v3 TickMath.getSqrtRatioAtTick: sqrt(1.0001^tick) as Q64.96.
fn sqrt_ratio_at_tick(tick: i32) -> Result<U256, String> {
    if tick.abs() > TICK_MATH_MAX_TICK {
        return Err(format!("TICK_OUT_OF_RANGE: {}", tick));
    }
    let abs_tick = tick.unsigned_abs();
    const C: [&str; 19] = [
        "fff97272373d413259a46990580e213a",
        "fff2e50f5f656932ef12357cf3c7fdcc",
        "ffe5caca7e10e4e61c3624eaa0941cd0",
        "ffcb9843d60f6159c9db58835c926644",
        "ff973b41fa98c081472e6896dfb254c0",
        "ff2ea16466c96a3843ec78b326b52861",
        "fe5dee046a99a2a811c461f1969c3053",
        "fcbe86c7900a88aedcffc83b479aa3a4",
        "f987a7253ac413176f2b074cf7815e54",
        "f3392b0822b70005940c7a398e4b70f3",
        "e7159475a2c29b7443b29c7fa6e889d9",
        "d097f3bdfd2022b8845ad8f792aa5825",
        "a9f746462d870fdf8a65dc1f90e061e5",
        "70d869a156d2a1b890bb3df62baf32f7",
        "31be135f97d08fd981231505542fcfa6",
        "9aa508b5b7a84e1c677de54f3e99bc9",
        "5d6af8dedb81196699c329225ee604",
        "2216e584f5fa1ea926041bedfe98",
        "48a170391f7dc42444e8fa2",
    ];
    let mut ratio: U256 = if abs_tick & 1 != 0 {
        U256::from_str_radix("fffcb933bd6fad37aa2d162d1a594001", 16).unwrap()
    } else {
        U256::one() << 128
    };
    for (i, c) in C.iter().enumerate() {
        if abs_tick & (1u32 << (i + 1)) != 0 {
            let m = U256::from_str_radix(c, 16).unwrap();
            // Q128.128 product then renormalize (full 512-bit intermediate).
            ratio = u512_to_u256(ratio.full_mul(m) >> 128)?;
        }
    }
    if tick > 0 {
        ratio = U256::MAX / ratio;
    }
    // Q128.128 → Q64.96, rounding up (Uniswap's exact behavior).
    let shifted = ratio >> 32;
    let round_up = !(ratio & ((U256::one() << 32) - U256::one())).is_zero();
    Ok(shifted + if round_up { U256::one() } else { U256::zero() })
}

fn u512_to_u256(v: U512) -> Result<U256, String> {
    U256::try_from(v).map_err(|_| "U256_OVERFLOW".to_string())
}

/// floor(a * b / denom) with a 512-bit intermediate.
fn mul_div(a: U256, b: U256, denom: U256) -> Result<U256, String> {
    if denom.is_zero() {
        return Err("DIV_BY_ZERO".to_string());
    }
    u512_to_u256(a.full_mul(b) / U512::from(denom))
}

/// Uniswap v3 LiquidityAmounts.getAmountsForLiquidity: the token amounts a
/// position of `liquidity` holds at the pool's current sqrt price.
fn amounts_for_liquidity(
    sqrt_p: U256,
    sqrt_a_in: U256,
    sqrt_b_in: U256,
    liquidity: u128,
) -> Result<(u128, u128), String> {
    let (sqrt_a, sqrt_b) = if sqrt_a_in <= sqrt_b_in { (sqrt_a_in, sqrt_b_in) } else { (sqrt_b_in, sqrt_a_in) };
    if sqrt_a.is_zero() {
        return Err("SQRT_RATIO_ZERO".to_string());
    }
    let l = U256::from(liquidity);
    let amount0 = |lo: U256, hi: U256| -> Result<U256, String> {
        Ok(mul_div(l << 96, hi - lo, hi)? / lo)
    };
    let amount1 = |lo: U256, hi: U256| -> Result<U256, String> {
        mul_div(l, hi - lo, q96())
    };
    let (a0, a1) = if sqrt_p <= sqrt_a {
        (amount0(sqrt_a, sqrt_b)?, U256::zero())
    } else if sqrt_p >= sqrt_b {
        (U256::zero(), amount1(sqrt_a, sqrt_b)?)
    } else {
        (amount0(sqrt_p, sqrt_b)?, amount1(sqrt_a, sqrt_p)?)
    };
    let to_u128 = |v: U256| -> u128 { u128::try_from(v).unwrap_or(u128::MAX) };
    Ok((to_u128(a0), to_u128(a1)))
}

// ── ICPSwap mirrors for the principal-indexed read (candid width-subtyping
//    lets us declare only the fields we use) ──
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
struct IcpSwapUserPosition {
    id: candid::Nat,
    #[serde(rename = "tickLower")]
    tick_lower: candid::Int,
    #[serde(rename = "tickUpper")]
    tick_upper: candid::Int,
    liquidity: candid::Nat,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
enum IcpSwapUserPositionsResult {
    #[serde(rename = "ok")]
    Ok(Vec<IcpSwapUserPosition>),
    #[serde(rename = "err")]
    Err(IcpSwapError),
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
struct IcpSwapPoolMeta {
    #[serde(rename = "sqrtPriceX96")]
    sqrt_price_x96: candid::Nat,
    tick: candid::Int,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
enum IcpSwapPoolMetaResult {
    #[serde(rename = "ok")]
    Ok(IcpSwapPoolMeta),
    #[serde(rename = "err")]
    Err(IcpSwapError),
}

fn nat_to_u256(n: &candid::Nat) -> Result<U256, String> {
    let bytes = n.0.to_bytes_be();
    if bytes.len() > 32 {
        return Err("NAT_TOO_BIG".to_string());
    }
    Ok(U256::from_big_endian(&bytes))
}

fn int_to_i32(i: &candid::Int) -> Result<i32, String> {
    i32::try_from(i.0.clone()).map_err(|_| "TICK_OVERFLOW".to_string())
}

/// Live token amounts for the given position ids on `pool`. Reads only OUR
/// positions (principal-indexed) + the pool's sqrtPriceX96, then does the
/// tick math canister-side — never the pool's page-scan (which exceeds the
/// pool's 5B instruction limit on big mainnet pools; IC0522).
async fn icpswap_position_amounts(
    pool: Principal,
    want: &[u128],
) -> Result<std::collections::HashMap<u128, (u128, u128)>, String> {
    if icp_lp_use_mock() {
        return Ok(MOCK_ICPSWAP_AMOUNTS.with(|m| {
            m.borrow()
                .iter()
                .filter(|((p2, id), _)| *p2 == pool && want.contains(id))
                .map(|((_, id), v)| (*id, *v))
                .collect()
        }));
    }
    let (pos_res,): (IcpSwapUserPositionsResult,) =
        ic_cdk::call(pool, "getUserPositionsByPrincipal", (get_canister_id(),))
            .await
            .map_err(|(c, m)| format!("ICPSWAP_CALL_FAILED: {:?} {}", c, m))?;
    let positions = match pos_res {
        IcpSwapUserPositionsResult::Ok(p2) => p2,
        IcpSwapUserPositionsResult::Err(e) => return Err(format!("ICPSWAP_ERROR: {:?}", e)),
    };
    let (meta_res,): (IcpSwapPoolMetaResult,) = ic_cdk::call(pool, "metadata", ())
        .await
        .map_err(|(c, m)| format!("ICPSWAP_CALL_FAILED: {:?} {}", c, m))?;
    let meta = match meta_res {
        IcpSwapPoolMetaResult::Ok(m) => m,
        IcpSwapPoolMetaResult::Err(e) => return Err(format!("ICPSWAP_ERROR: {:?}", e)),
    };
    let sqrt_p = nat_to_u256(&meta.sqrt_price_x96)?;

    let mut found = std::collections::HashMap::new();
    for pos in positions {
        let id = u128::try_from(pos.id.0.clone()).map_err(|_| "POSITION_ID_OVERFLOW".to_string())?;
        if !want.contains(&id) {
            continue;
        }
        let liquidity = u128::try_from(pos.liquidity.0.clone()).map_err(|_| "LIQUIDITY_OVERFLOW".to_string())?;
        let sqrt_a = sqrt_ratio_at_tick(int_to_i32(&pos.tick_lower)?)?;
        let sqrt_b = sqrt_ratio_at_tick(int_to_i32(&pos.tick_upper)?)?;
        let (a0, a1) = amounts_for_liquidity(sqrt_p, sqrt_a, sqrt_b, liquidity)?;
        found.insert(id, (a0, a1));
    }
    Ok(found)
}

/// Ledger principal → the explorer token whose cached USD rate applies.
fn icp_lp_ledger_token(ledger: Principal) -> Option<ExplorerToken> {
    let config = CONFIG.with(|c| c.borrow().get().clone());
    for t in [IdeaToken::ICP, IdeaToken::CkBTC, IdeaToken::CkETH, IdeaToken::CkUSDC, IdeaToken::CkUSDT] {
        if token_ledger(t, &config) == ledger {
            return Some(match t {
                IdeaToken::ICP => ExplorerToken::ICP,
                IdeaToken::CkBTC => ExplorerToken::CkBTC,
                IdeaToken::CkETH => ExplorerToken::CkETH,
                IdeaToken::CkUSDC => ExplorerToken::CkUSDC,
                IdeaToken::CkUSDT => ExplorerToken::CkUSDT,
            });
        }
    }
    None
}

/// USD e8s value of `amount` base units of the token on `ledger` (u128-safe
/// for 18-decimal ckETH amounts).
fn icp_lp_amount_usd_e8s(ledger: Principal, amount: u128) -> u64 {
    let Some(token) = icp_lp_ledger_token(ledger) else { return 0 };
    let rate = cached_usd_rate_e8s(token) as u128;
    let scale = 10u128.pow(explorer_token_decimals(token));
    u64::try_from(amount.saturating_mul(rate) / scale).unwrap_or(u64::MAX)
}

fn icp_lp_pool_cfg(pool: &Principal) -> Option<IcpLpPoolCfg> {
    ICPSWAP_POOLS.with(|c| c.borrow().get().clone()).pools.into_iter().find(|p| p.pool == *pool)
}

fn icp_lp_use_mock() -> bool {
    cfg!(not(target_arch = "wasm32")) || CONFIG.with(|c| c.borrow().get().is_local)
}

/// Position ids the BACKEND canister owns on `pool` (the stake proof read).
async fn icpswap_positions_of_backend(pool: Principal) -> Result<Vec<u128>, String> {
    if icp_lp_use_mock() {
        return Ok(MOCK_ICPSWAP_OUR_POSITIONS.with(|m| m.borrow().get(&pool).cloned().unwrap_or_default()));
    }
    let (res,): (IcpSwapNatVecResult,) =
        ic_cdk::call(pool, "getUserPositionIdsByPrincipal", (get_canister_id(),))
            .await
            .map_err(|(c, m)| format!("ICPSWAP_CALL_FAILED: {:?} {}", c, m))?;
    match res {
        IcpSwapNatVecResult::Ok(ids) => Ok(ids
            .into_iter()
            .map(|n| u128::try_from(n.0.clone()).map_err(|_| "POSITION_ID_OVERFLOW".to_string()))
            .collect::<Result<Vec<_>, _>>()?),
        IcpSwapNatVecResult::Err(e) => Err(format!("ICPSWAP_ERROR: {:?}", e)),
    }
}

/// Transfer a custodied position from the backend to `to` (unstake).
async fn icpswap_transfer_position_out(pool: Principal, to: Principal, position_id: u128) -> Result<(), String> {
    if icp_lp_use_mock() {
        let owned = MOCK_ICPSWAP_OUR_POSITIONS.with(|m| {
            m.borrow().get(&pool).map(|v| v.contains(&position_id)).unwrap_or(false)
        });
        if !owned {
            return Err("ICPSWAP_ERROR: position not owned".to_string());
        }
        MOCK_ICPSWAP_OUR_POSITIONS.with(|m| {
            if let Some(v) = m.borrow_mut().get_mut(&pool) {
                v.retain(|id| *id != position_id);
            }
        });
        MOCK_ICPSWAP_TRANSFERS.with(|m| m.borrow_mut().push((pool, to, position_id)));
        return Ok(());
    }
    let (res,): (IcpSwapBoolResult,) = ic_cdk::call(
        pool,
        "transferPosition",
        (get_canister_id(), to, candid::Nat::from(position_id)),
    )
    .await
    .map_err(|(c, m)| format!("ICPSWAP_CALL_FAILED: {:?} {}", c, m))?;
    match res {
        IcpSwapBoolResult::Ok(true) => Ok(()),
        IcpSwapBoolResult::Ok(false) => Err("ICPSWAP_TRANSFER_REFUSED".to_string()),
        IcpSwapBoolResult::Err(e) => Err(format!("ICPSWAP_ERROR: {:?}", e)),
    }
}

/// Claim a position's accrued fees INTO THE DEDICATED YIELD SUBACCOUNT
/// (ICPSwap pays the claimed tokens to {backend, sub} on each token's
/// ledger). The native mock credits the TEST_ACCT sim instead.
async fn icpswap_claim_yield(pool: &IcpLpPoolCfg, position_id: u128) -> Result<(u64, u64), String> {
    if icp_lp_use_mock() {
        let amounts = MOCK_ICPSWAP_CLAIMS.with(|m| m.borrow_mut().remove(&(pool.pool, position_id)));
        let (a0, a1) = amounts.unwrap_or((0, 0));
        #[cfg(not(target_arch = "wasm32"))]
        {
            // Credit the single-ledger test sim at the yield subaccount.
            let me = get_canister_id();
            let cur = acct_get(me, Some(ICPSWAP_LP_YIELD_SUBACCOUNT));
            acct_set(me, Some(ICPSWAP_LP_YIELD_SUBACCOUNT), cur + a0 + a1);
        }
        return Ok((a0, a1));
    }
    let args = IcpSwapClaimToSubaccountArgs {
        position_id: candid::Nat::from(position_id),
        subaccount: ICPSWAP_LP_YIELD_SUBACCOUNT.to_vec(),
    };
    let (res,): (IcpSwapClaimResult,) = ic_cdk::call(pool.pool, "claimToSubaccount", (args,))
        .await
        .map_err(|(c, m)| format!("ICPSWAP_CALL_FAILED: {:?} {}", c, m))?;
    match res {
        IcpSwapClaimResult::Ok(a) => Ok((
            u64::try_from(a.amount0.0.clone()).unwrap_or(u64::MAX),
            u64::try_from(a.amount1.0.clone()).unwrap_or(u64::MAX),
        )),
        IcpSwapClaimResult::Err(e) => Err(format!("ICPSWAP_ERROR: {:?}", e)),
    }
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct IcpLpPositionView {
    pub pool: Principal,
    pub pool_name: String,
    pub position_id: u128,
    pub staked_at: u64,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct IcpLpInfo {
    pub enabled: bool,
    pub round: u64,
    /// Tickets per day per $1 of staked LP value (proportional).
    pub tickets_per_usd_day: u64,
    /// Caller holds an active ICP stake (tickets are stakers-only).
    pub staked: bool,
    /// Where to send the position on ICPSwap (the custody principal).
    pub backend_principal: Principal,
    pub my_positions: Vec<IcpLpPositionView>,
    /// Reserve-first flow: ids the caller has reserved but not yet registered.
    pub my_reservations: Vec<IcpLpReservationView>,
    pub pools: Vec<IcpLpPoolCfg>,
    pub total_harvested_icp_e8s: u64,
    /// Today's grant already landed for the caller.
    pub granted_today: bool,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct IcpLpReservationView {
    pub pool: Principal,
    pub pool_name: String,
    pub position_id: u128,
    pub expires_at: u64,
}

#[ic_cdk::query]
fn get_icp_lp_info() -> IcpLpInfo {
    let caller = get_caller();
    let round = lottery_state().round;
    let stats = ICP_LP_STATS.with(|c| c.borrow().get().clone());
    IcpLpInfo {
        enabled: feature_visible(FLAG_ICPSWAP_LP, caller),
        round,
        tickets_per_usd_day: ICP_LP_TICKETS_PER_USD_DAY,
        staked: caller != Principal::anonymous() && author_is_staked(caller),
        backend_principal: get_canister_id(),
        my_positions: STAKED_LP.with(|m| {
            m.borrow()
                .iter()
                .filter(|e| e.value().user == caller)
                .map(|e| IcpLpPositionView {
                    pool: e.key().pool,
                    pool_name: e.value().pool_name.clone(),
                    position_id: e.key().position_id,
                    staked_at: e.value().staked_at,
                })
                .collect()
        }),
        my_reservations: {
            let now = current_time();
            LP_RESERVATIONS.with(|m| {
                m.borrow()
                    .iter()
                    .filter(|e| e.value().user == caller && e.value().expires_at > now)
                    .map(|e| IcpLpReservationView {
                        pool: e.key().pool,
                        pool_name: icp_lp_pool_cfg(&e.key().pool).map(|c2| c2.name).unwrap_or_default(),
                        position_id: e.key().position_id,
                        expires_at: e.value().expires_at,
                    })
                    .collect()
            })
        },
        pools: ICPSWAP_POOLS.with(|c| c.borrow().get().clone()).pools,
        total_harvested_icp_e8s: stats.total_harvested_icp_e8s,
        granted_today: ICP_LP_ROUND_GRANTS.with(|m| {
            m.borrow().contains_key(&IcpLpRoundKey { round: epoch_day(current_time()) as u64, user: caller })
        }),
    }
}

/// RESERVE a position id BEFORE transferring it on ICPSwap. The reservation
/// binds (pool, id) to the caller for ICP_LP_RESERVATION_TTL_NS, and
/// stake_lp_position only registers the reservation holder — so a position
/// arriving at our canister can never be claimed by anyone but the user who
/// announced it first. Nobody should ever transfer without reserving.
/// Returns the reservation's expiry (ns).
#[ic_cdk::update]
fn reserve_lp_position(pool: Principal, position_id: u128) -> Result<u64, String> {
    require_authenticated()?;
    let caller = get_caller();
    if !feature_visible(FLAG_ICPSWAP_LP, caller) {
        return Err("FEATURE_DISABLED".to_string());
    }
    icp_lp_pool_cfg(&pool).ok_or("POOL_NOT_SUPPORTED")?;
    let key = IcpLpKey { pool, position_id };
    if STAKED_LP.with(|m| m.borrow().contains_key(&key)) {
        return Err("POSITION_ALREADY_STAKED".to_string());
    }
    let now = current_time();
    // Lazily prune expired reservations while enforcing the per-user cap.
    let expired: Vec<IcpLpKey> = LP_RESERVATIONS.with(|m| {
        m.borrow().iter().filter(|e| e.value().expires_at <= now).map(|e| e.key().clone()).collect()
    });
    LP_RESERVATIONS.with(|m| {
        let mut m = m.borrow_mut();
        for k in expired { m.remove(&k); }
    });
    if let Some(existing) = LP_RESERVATIONS.with(|m| m.borrow().get(&key)) {
        if existing.user != caller {
            return Err("RESERVED_BY_OTHER".to_string());
        }
        // Re-reserving your own refreshes the TTL (fall through to insert).
    } else {
        let mine = LP_RESERVATIONS.with(|m| {
            m.borrow().iter().filter(|e| e.value().user == caller).count()
        });
        if mine >= ICP_LP_MAX_RESERVATIONS {
            return Err("RESERVATION_LIMIT".to_string());
        }
    }
    let expires_at = now + ICP_LP_RESERVATION_TTL_NS;
    LP_RESERVATIONS.with(|m| { m.borrow_mut().insert(key, LpReservation { user: caller, expires_at }); });
    Ok(expires_at)
}

/// Register a position the caller RESERVED and then transferred to this
/// canister on ICPSwap. Only the reservation holder can register — the
/// reserve-first ordering is the anti-sniping guarantee.
#[ic_cdk::update]
async fn stake_lp_position(pool: Principal, position_id: u128) -> Result<IcpLpPositionView, String> {
    require_authenticated()?;
    let caller = get_caller();
    if !feature_visible(FLAG_ICPSWAP_LP, caller) {
        return Err("FEATURE_DISABLED".to_string());
    }
    let cfg = icp_lp_pool_cfg(&pool).ok_or("POOL_NOT_SUPPORTED")?;
    let key = IcpLpKey { pool, position_id };
    if STAKED_LP.with(|m| m.borrow().contains_key(&key)) {
        return Err("POSITION_ALREADY_STAKED".to_string());
    }
    // Reserve-first: the caller must hold the live reservation for this id.
    let check_reservation = || -> Result<(), String> {
        match LP_RESERVATIONS.with(|m| m.borrow().get(&key)) {
            None => Err("NO_RESERVATION".to_string()),
            Some(r) if r.user != caller => Err("RESERVED_BY_OTHER".to_string()),
            Some(r) if r.expires_at <= current_time() => Err("RESERVATION_EXPIRED".to_string()),
            Some(_) => Ok(()),
        }
    };
    check_reservation()?;
    let ours = icpswap_positions_of_backend(pool).await?;
    if !ours.contains(&position_id) {
        return Err("POSITION_NOT_TRANSFERRED".to_string());
    }
    // Re-check after the await (reservation could have expired mid-flight).
    check_reservation()?;
    if STAKED_LP.with(|m| m.borrow().contains_key(&key)) {
        return Err("POSITION_ALREADY_STAKED".to_string());
    }
    let now = current_time();
    // Mint the NON-SELLABLE LpBacked voucher (best-effort — custody first;
    // amount_e8s 0 so it can never be misread as an ICP principal claim).
    let voucher_id = mint_lp_voucher(caller).await;
    let record = StakedLpPosition { user: caller, pool_name: cfg.name.clone(), staked_at: now, voucher_id };
    STAKED_LP.with(|m| { m.borrow_mut().insert(key.clone(), record); });
    LP_RESERVATIONS.with(|m| { m.borrow_mut().remove(&key); });
    staking_audit("icpswap_lp_stake", caller, position_id as u64, 0);
    Ok(IcpLpPositionView { pool, pool_name: cfg.name, position_id, staked_at: now })
}

/// Mint the LP-custody companion voucher. Best-effort: an NFT hiccup never
/// blocks an LP stake; None is recorded and the row still confers full
/// participant status (author_is_staked reads STAKED_LP directly).
async fn mint_lp_voucher(owner: Principal) -> Option<u64> {
    if !feature_enabled(FLAG_STAKE_VOUCHERS) || voucher_nft_cid().is_err() {
        return None;
    }
    let id = NEXT_VOUCHER_ID.with(|c| {
        let id = *c.borrow().get();
        c.borrow_mut().set(id + 1);
        id
    });
    if let Err(e) = voucher_nft_mint(id, owner, VoucherClass::LpBacked, 0, 0, None).await {
        canister_print(&format!("mint_lp_voucher: {}", e));
        return None;
    }
    VOUCHERS.with(|m| {
        m.borrow_mut().insert(id, VoucherRecord {
            id,
            class: VoucherClass::LpBacked,
            tier: 0,
            amount_e8s: 0,
            owner,
            minted_at: current_time(),
            expires_at: None,
            listed_price_e8s: None,
            last_purchase_grant_day: 0,
        });
    });
    staking_audit("lp_voucher_mint", owner, 0, id);
    Some(id)
}

/// Return a custodied position to `return_to` (the staker's ICPSwap
/// principal). Only the recorded staker; NOT feature-flag-gated — the
/// custody exit must always work, dark flag or not.
#[ic_cdk::update]
async fn unstake_lp_position(pool: Principal, position_id: u128, return_to: Principal) -> Result<(), String> {
    require_authenticated()?;
    let caller = get_caller();
    if return_to == Principal::anonymous() {
        return Err("BAD_RETURN_PRINCIPAL".to_string());
    }
    let key = IcpLpKey { pool, position_id };
    let record = STAKED_LP.with(|m| m.borrow().get(&key)).ok_or("POSITION_NOT_STAKED")?;
    if record.user != caller {
        return Err("NOT_YOUR_POSITION".to_string());
    }
    icpswap_transfer_position_out(pool, return_to, position_id).await?;
    STAKED_LP.with(|m| { m.borrow_mut().remove(&key); });
    // Burn the companion LpBacked voucher (best-effort — the exit NEVER
    // blocks on the NFT canister).
    if let Some(vid) = record.voucher_id {
        VOUCHERS.with(|m| { m.borrow_mut().remove(&vid); });
        if voucher_nft_burn(vid).await.is_err() {
            canister_print(&format!("lp voucher burn failed for #{vid} (registry row removed)"));
        }
    }
    staking_audit("icpswap_lp_unstake", caller, position_id as u64, 0);
    Ok(())
}

/// Admin: configure the qualifying ICPSwap pools.
#[ic_cdk::update]
fn admin_set_icpswap_pools(pools: Vec<IcpLpPoolCfg>) -> Result<u64, String> {
    require_admin()?;
    for p in &pools {
        if p.name.trim().is_empty() {
            return Err("POOL_NAME_EMPTY".to_string());
        }
        if p.pool == Principal::anonymous() {
            return Err(format!("BAD_POOL_PRINCIPAL: {}", p.name));
        }
    }
    let n = pools.len() as u64;
    ICPSWAP_POOLS.with(|c| { let _ = c.borrow_mut().set(IcpLpPoolsCfg { pools }); });
    Ok(n)
}

/// Sweep leg 1 (sync, cheap): every distinct staker with a custodied
/// position earns ICP_LP_TICKETS_PER_ROUND tickets once per lottery round.
/// The guard row is only written when tickets actually land, so an unstaked
/// user who stakes ICP later in the round still collects.
/// Daily ticket grant: 40 tickets per $1 of staked LP value, per user, per
/// UTC day. The value is read LIVE (the pool's own tick-math amounts × the
/// cached XRC USD rates), so tickets track the position through price moves.
/// A failed valuation leaves the day's guard unwritten — retried next sweep.
/// The guard key reuses the (round, user) map with round = epoch day.
async fn icpswap_lp_grant_daily_tickets() {
    if !feature_visible(FLAG_ICPSWAP_LP, Principal::anonymous()) {
        return;
    }
    // A recent valuation failure backs the whole pass off for an hour — a
    // broken/overloaded pool must not burn 288 inter-canister calls a day.
    if current_time() < ICP_LP_VALUATION_BACKOFF_UNTIL.with(|c| c.get()) {
        return;
    }
    let day = epoch_day(current_time()) as u64;
    // Group staked positions by user.
    let mut by_user: std::collections::BTreeMap<Principal, Vec<IcpLpKey>> = Default::default();
    STAKED_LP.with(|m| {
        for e in m.borrow().iter() {
            by_user.entry(e.value().user).or_default().push(e.key().clone());
        }
    });
    for (user, positions) in by_user {
        let key = IcpLpRoundKey { round: day, user };
        if ICP_LP_ROUND_GRANTS.with(|m| m.borrow().contains_key(&key)) {
            continue;
        }
        if !author_is_staked(user) {
            // Unreachable in practice since 2026-07-11 (the STAKED_LP row
            // being enumerated IS a stake) — kept as defense in depth.
            continue;
        }
        // Value every position; ANY failure skips the user this pass so a
        // partial valuation never underpays permanently.
        let mut usd_e8s: u64 = 0;
        let mut failed = false;
        let mut by_pool: std::collections::BTreeMap<Principal, Vec<u128>> = Default::default();
        for k in &positions {
            by_pool.entry(k.pool).or_default().push(k.position_id);
        }
        for (pool, ids) in by_pool {
            let Some(cfg) = icp_lp_pool_cfg(&pool) else { continue };
            match icpswap_position_amounts(pool, &ids).await {
                Ok(amounts) => {
                    for id in &ids {
                        let (a0, a1) = amounts.get(id).copied().unwrap_or((0, 0));
                        usd_e8s = usd_e8s
                            .saturating_add(icp_lp_amount_usd_e8s(cfg.token0_ledger, a0))
                            .saturating_add(icp_lp_amount_usd_e8s(cfg.token1_ledger, a1));
                    }
                }
                Err(e) => {
                    canister_print(&format!("icpswap daily tickets: valuation failed for {}: {}", user, e));
                    ICP_LP_VALUATION_BACKOFF_UNTIL
                        .with(|c| c.set(current_time().saturating_add(ICP_LP_HARVEST_INTERVAL_NS)));
                    failed = true;
                    break;
                }
            }
        }
        if failed {
            continue;
        }
        let tickets = ((usd_e8s as u128) * (ICP_LP_TICKETS_PER_USD_DAY as u128) / 100_000_000u128) as u64;
        if tickets > 0 {
            grant_lottery_tickets(user, tickets, "icpswap_lp");
        }
        // Guard written on successful valuation (even a $0 day) — value is
        // re-read fresh tomorrow.
        ICP_LP_ROUND_GRANTS.with(|m| { m.borrow_mut().insert(key, if tickets > 0 { 1u8 } else { 0u8 }); });
        staking_audit("icpswap_lp_daily_tickets", user, tickets, day);
    }
}

/// Sweep leg 2 (async, throttled): claim every custodied position's fees
/// into the dedicated yield subaccount, then route whatever sits there.
async fn harvest_icpswap_lp() {
    if !feature_visible(FLAG_ICPSWAP_LP, Principal::anonymous()) {
        return;
    }
    let now = current_time();
    let mut stats = ICP_LP_STATS.with(|c| c.borrow().get().clone());
    if now.saturating_sub(stats.last_harvest_at) < ICP_LP_HARVEST_INTERVAL_NS {
        return;
    }
    stats.last_harvest_at = now;
    ICP_LP_STATS.with(|c| { let _ = c.borrow_mut().set(stats.clone()); });

    // 1. Claim fees (per position; one failing never blocks the others).
    let staked: Vec<IcpLpKey> = STAKED_LP.with(|m| m.borrow().iter().map(|e| e.key().clone()).collect());
    for key in staked {
        let Some(cfg) = icp_lp_pool_cfg(&key.pool) else { continue };
        if let Err(e) = icpswap_claim_yield(&cfg, key.position_id).await {
            canister_print(&format!("icpswap harvest: claim failed for {}#{}: {}", cfg.name, key.position_id, e));
        }
    }
    // 2. Retry any CMC notifies left over from previous harvests.
    let cmc = Principal::from_text("rkp4c-7iaaa-aaaaa-aaaca-cai").unwrap();
    let mut still_pending: Vec<(Principal, u64)> = Vec::new();
    for (target, block) in stats.pending_notifies.clone() {
        match notify_cmc_topup(cmc, target, block, true).await {
            Ok(_) => {}
            Err(e) if e.starts_with("CMC_REFUNDED") => {} // ICP is back in the sub; re-routes below
            Err(_) => still_pending.push((target, block)),
        }
    }
    stats.pending_notifies = still_pending;

    // 3. Route the yield subaccount, ledger by ledger.
    let config = CONFIG.with(|c| c.borrow().get().clone());
    let icp_ledger = config.ledger_canister_id;
    let me = get_canister_id();
    let yield_account = LedgerAccount { owner: me, subaccount: Some(ICPSWAP_LP_YIELD_SUBACCOUNT) };
    let mut ledgers: std::collections::BTreeSet<Principal> = std::collections::BTreeSet::new();
    for pool in ICPSWAP_POOLS.with(|c| c.borrow().get().clone()).pools {
        ledgers.insert(pool.token0_ledger);
        ledgers.insert(pool.token1_ledger);
    }
    for ledger in ledgers {
        let Ok(balance) = call_ledger_balance(ledger, yield_account.clone()).await else { continue };
        if ledger == icp_ledger {
            if balance < ICP_LP_MIN_ROUTE_E8S {
                continue;
            }
            // Three outbound transfers → reserve their fees, split the rest.
            let usable = balance.saturating_sub(3 * 10_000);
            let pot_amt = usable / 2;
            let backend_amt = usable / 4;
            let frontend_amt = usable - pot_amt - backend_amt;
            // 50% → the lottery pot.
            let pot_dest = LedgerAccount { owner: me, subaccount: Some(LOTTERY_SUBACCOUNT) };
            match call_ledger_transfer(ledger, Some(ICPSWAP_LP_YIELD_SUBACCOUNT), pot_dest, pot_amt, Some(10_000)).await {
                Ok(_) => {
                    stats.total_pot_e8s = stats.total_pot_e8s.saturating_add(pot_amt);
                    let config = CONFIG.with(|c| c.borrow().get().clone());
                    refresh_lottery_pot_cache(&config).await;
                }
                Err(e) => {
                    canister_print(&format!("icpswap harvest: pot leg failed: {}", e));
                    continue; // balance intact; retry next harvest
                }
            }
            // 25% + 25% → cycles for backend and frontend (burns the ICP).
            for (target, amt) in [(me, backend_amt), (frontend_canister_id(), frontend_amt)] {
                if amt == 0 { continue; }
                match call_cmc_topup_transfer(ledger, Some(ICPSWAP_LP_YIELD_SUBACCOUNT), target, amt, 10_000).await {
                    Ok(block) => {
                        stats.total_burn_e8s = stats.total_burn_e8s.saturating_add(amt);
                        if let Err(e) = notify_cmc_topup(cmc, target, block, true).await {
                            if !e.starts_with("CMC_REFUNDED") {
                                stats.pending_notifies.push((target, block));
                            }
                            canister_print(&format!("icpswap harvest: notify pending for {}: {}", target, e));
                        }
                    }
                    Err(e) => canister_print(&format!("icpswap harvest: burn leg failed: {}", e)),
                }
            }
            stats.total_harvested_icp_e8s = stats.total_harvested_icp_e8s.saturating_add(balance);
        } else {
            // Non-ICP yield → treasury on that token's ledger, in full.
            // 10_000 covers every ck-token's default fee comfortably.
            if balance <= 20_000 {
                continue;
            }
            let dest = LedgerAccount { owner: me, subaccount: Some(TREASURY_SUBACCOUNT) };
            match call_ledger_transfer(ledger, Some(ICPSWAP_LP_YIELD_SUBACCOUNT), dest, balance - 10_000, Some(10_000)).await {
                Ok(_) => {
                    stats.total_treasury_legs = stats.total_treasury_legs.saturating_add(1);
                }
                Err(e) => canister_print(&format!("icpswap harvest: treasury leg failed: {}", e)),
            }
        }
    }
    ICP_LP_STATS.with(|c| { let _ = c.borrow_mut().set(stats); });
}

/// Local/dev: seed the mocked ICPSwap position registry (positions "owned"
/// by this canister on a pool). Admin-gated; the mock is only consulted on
/// native tests and local replicas.
#[ic_cdk::update]
fn dev_set_icpswap_mock_positions(pool: Principal, position_ids: Vec<u128>) -> Result<(), String> {
    require_admin()?;
    MOCK_ICPSWAP_OUR_POSITIONS.with(|m| { m.borrow_mut().insert(pool, position_ids); });
    Ok(())
}

/// Local/dev: queue mocked claim amounts for a position (one-shot).
#[ic_cdk::update]
fn dev_set_icpswap_mock_claim(pool: Principal, position_id: u128, amount0: u64, amount1: u64) -> Result<(), String> {
    require_admin()?;
    MOCK_ICPSWAP_CLAIMS.with(|m| { m.borrow_mut().insert((pool, position_id), (amount0, amount1)); });
    Ok(())
}

// ==========================================
// 18. Early Adopters (permanent stake, monthly yield shares)
// ==========================================
//
// Early adopters stake ICP into a single platform-owned 2-year neuron.
// THE STAKE IS PERMANENT — there is deliberately NO unstake method anywhere
// in this section, and the UI states it in bold before anyone commits.
//
// Every ~month (30-day periods) the neuron's collected yield is settled:
//   • a month that yields under 500 ICP is restaked into the neuron in
//     full — nothing pays out, the principal compounds for everyone;
//   • otherwise the first 1,000 ICP of the month's yield goes to the
//     treasury (a 500–1,000 ICP month is entirely treasury's);
//   • the excess above 1,000 ICP joins the share pool and is split across
//     all early adopters IN PROPORTION TO THEIR STAKED ICP — but only when at
//     least 100 ICP is available to split; otherwise the pool rolls over
//     to the next month;
//   • an early adopter must claim their share before the NEXT monthly
//     settlement — unclaimed shares are forfeited to the treasury then.

/// 150 ICP — the treasury's monthly cut comes first, CAPPED here so member
/// yield scales with the neuron. Recalibrated from 1,000 (June 2026): at the
/// 70k-ICP target the old cut absorbed every realistic month entirely,
/// paying members 0% forever — see okf/operations/GROWTH_TARGETS.md §3.
const EARLY_ADOPTER_TREASURY_CUT_E8S: u64 = 15_000_000_000;
/// 600 ICP — once a settled month's yield reaches this, membership closes
/// PERMANENTLY: no new early adopters, ever. Existing early adopters can still top
/// up at any time. (Recalibrated from 2,000 — unreachable at target scale.)
const EARLY_ADOPTER_CLOSE_YIELD_E8S: u64 = 60_000_000_000;
/// 50 ICP — a month that yields less than this is restaked into the neuron
/// (compounding everyone's future yield) instead of being paid out at all.
/// (Recalibrated from 500.)
const EARLY_ADOPTER_RESTAKE_BELOW_E8S: u64 = 5_000_000_000;
/// 2 years — the early adopter neuron's dissolve delay.
const EARLY_ADOPTER_DISSOLVE_SECS: u32 = 63_115_200;
/// 100 ICP — minimum distributable pot; below this it rolls over.
const EARLY_ADOPTER_MIN_DISTRIBUTION_E8S: u64 = 10_000_000_000;
/// 1 ICP minimum buy-in.
const MIN_EARLY_ADOPTER_STAKE_E8S: u64 = 100_000_000;
/// Boosters earn a flat 40 lottery tickets/day per whole ICP staked.
const BOOSTER_TICKETS_PER_ICP_PER_DAY: u64 = 40;
/// Settlement period: 30-day months indexed from the Unix epoch.
const EARLY_ADOPTER_PERIOD_NANOS: u64 = 30 * DAY_NANOS;
const MAX_EARLY_ADOPTERS: u64 = 10_000;

/// The platform neuron's stake account (locally a plain subaccount; mainnet
/// integration will pin a real 2-year neuron — same canary path as staking).
const EARLY_ADOPTER_NEURON_SUBACCOUNT: [u8; 32] = [5u8; 32];
/// Where neuron yield lands between settlements.
const EARLY_ADOPTER_YIELD_SUBACCOUNT: [u8; 32] = [6u8; 32];
/// Allocated-but-unclaimed shares + rollover live here.
const EARLY_ADOPTER_SHARE_POOL_SUBACCOUNT: [u8; 32] = [7u8; 32];

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct EarlyAdopter {
    pub user: Principal,
    pub staked_e8s: u64,
    pub joined_at: u64,
    pub last_stake_at: u64,
    /// Current unclaimed share (e8s). Zeroed (→ treasury) at each settlement.
    pub claimable_e8s: u64,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct EarlyAdopterState {
    pub total_staked_e8s: u64,
    /// Pool e8s carried forward because a month's pot was under 100 ICP.
    pub rollover_e8s: u64,
    /// Last settled 30-day period index (epoch-based). LEGACY — settlements
    /// are draw-keyed since 2026-07-06; kept so pre-change state decodes.
    pub last_processed_month: u64,
    /// Lottery round already settled — LEGACY cursor from the draw-keyed era
    /// (2026-07-06..10); no longer gates settlements.
    #[serde(default)]
    pub last_settled_lottery_round: u64,
    /// Monotonic settlement journal counter (slot-scheduled settlements can
    /// repeat within one lottery round, so rounds can't key the journal).
    #[serde(default)]
    pub settlement_seq: u64,
    pub total_yield_e8s: u64,
    pub total_distributed_e8s: u64,
    pub total_expired_e8s: u64,
    /// Latched true the first time a month's yield reaches 2,000 ICP —
    /// membership never reopens (existing early adopters may still top up).
    #[serde(default)]
    pub membership_closed: bool,
    /// ── Neuron bootstrap (same lifecycle as the staking tiers) ──
    /// Claim nonce, fixed at the first stake.
    #[serde(default)]
    pub nonce: u64,
    #[serde(default)]
    pub neuron_id: Option<u64>,
    /// Stake (and restaked yield) not yet claimed/refreshed into the neuron.
    #[serde(default)]
    pub pending_refresh_e8s: u64,
    /// 0 NotStarted → 1 Claimed → 2 DelaySet → 3 Ready (following the
    /// primary voting neuron on all topics — it votes on NNS proposals).
    #[serde(default)]
    pub bootstrap: u8,
    /// Lifetime yield restaked into the neuron (sub-500-ICP months).
    #[serde(default)]
    pub total_restaked_e8s: u64,
    /// In-flight settlement journal (None when no settlement is mid-run).
    #[serde(default)]
    pub pending_job: Option<EarlyAdopterJob>,
}

/// Settlement journal: the month's amounts are computed ONCE from the inbox
/// snapshot and each ledger leg is flagged as it lands, so a retry resumes
/// where it failed instead of re-routing the remaining balance — re-routing
/// double-dipped the treasury's 1,000 ICP cut and could mis-restake the
/// early adopters' pot (review 2026-06-11). Unclaimed shares are also zeroed
/// synchronously at job creation, which closes the window where a claim
/// landing mid-settlement double-spent the share pool.
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct EarlyAdopterJob {
    pub month: u64,
    pub started_at: u64,
    pub yield_e8s: u64,
    pub expired_e8s: u64,
    pub restake_e8s: u64,
    pub treasury_cut_e8s: u64,
    pub excess_net_e8s: u64,
    pub expired_done: bool,
    pub restake_done: bool,
    pub cut_done: bool,
    pub pool_done: bool,
}

/// One monthly settlement — drives the yield + share-pool charts.
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct EarlyAdopterRound {
    pub month: u64,
    pub settled_at: u64,
    pub yield_e8s: u64,
    pub treasury_e8s: u64,
    /// Total allocated to early adopters this round (proportional to stake).
    pub distributed_e8s: u64,
    /// Yield restaked into the neuron (months under 500 ICP).
    #[serde(default)]
    pub restaked_e8s: u64,
    pub early_adopter_count: u64,
    /// Unclaimed shares from the PREVIOUS round forfeited to the treasury.
    pub expired_e8s: u64,
    pub rollover_after_e8s: u64,
    /// Share-pool balance after this settlement (unclaimed + rollover).
    pub share_pool_after_e8s: u64,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct EarlyAdopterInfo {
    pub enabled: bool,
    /// True once any month's yield has reached `close_threshold_e8s` —
    /// permanently; new members are rejected, existing ones may top up.
    pub membership_closed: bool,
    pub close_threshold_e8s: u64,
    /// Months yielding under this are restaked into the neuron.
    pub restake_threshold_e8s: u64,
    pub total_restaked_e8s: u64,
    /// The early adopter neuron (None until the first claim lands).
    pub neuron_id: Option<u64>,
    /// True once the neuron follows the primary voting neuron on all topics
    /// (bootstrap Ready) — it then votes on every NNS proposal the leader does.
    pub follows_primary_neuron: bool,
    pub primary_neuron_id: u64,
    pub min_stake_e8s: u64,
    pub treasury_cut_e8s: u64,
    pub min_distribution_e8s: u64,
    pub period_nanos: u64,
    pub early_adopter_count: u64,
    pub total_staked_e8s: u64,
    pub rollover_e8s: u64,
    /// Live share-pool ledger balance (unclaimed shares + rollover).
    pub share_pool_e8s: u64,
    pub total_yield_e8s: u64,
    pub total_distributed_e8s: u64,
    /// Nanosecond timestamp when the next settlement can run.
    pub next_distribution_at: u64,
    pub my_staked_e8s: u64,
    pub my_claimable_e8s: u64,
    pub fee_e8s: u64,
}

impl_storable!(EarlyAdopter);
impl_storable!(EarlyAdopterState);
impl_storable!(EarlyAdopterRound);

