/// Marketplace listing + controller-side cache of authoritative CourseNFT
/// metadata (PB-305 B1). The CourseNFT canister is authoritative for
/// ownership/metadata; this row is cache + marketplace state (price/listed).
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct CourseListing {
    pub token_id: u64,
    pub listed: bool,
    pub price_e8s: u64,
    #[serde(default)]
    pub name: String,
    #[serde(default)]
    pub owner: Option<Principal>,
    #[serde(default)]
    pub creator: Option<Principal>,
    #[serde(default)]
    pub play_count: u64,
    #[serde(default)]
    pub tickets_distributed: u64,
    #[serde(default)]
    pub par_total: u8,
    #[serde(default)]
    pub created_at: u64,
    #[serde(default)]
    pub mint_fee_e8s: u64,
    /// PB-307: separate from `listed` (which is marketplace visibility / ticket
    /// accrual). `for_sale` flips on a fixed-price sale; `price_e8s` carries it.
    /// A course can be `listed && !for_sale` (playable but not buyable).
    #[serde(default)]
    pub for_sale: bool,
    /// PB-310 running rating aggregate (upgrade-safe; cheap card reads).
    #[serde(default)]
    pub rating_sum: u64, // sum of stars
    #[serde(default)]
    pub rating_count: u32, // distinct raters
    /// PB-3xx moderation: admin-discretion soft-hide. Hidden courses are
    /// excluded from public marketplace browsing but remain resolvable
    /// directly by token id (so the owner isn't fully locked out). NEVER set
    /// automatically — only `admin_hide_course` / `admin_unhide_course` flip it;
    /// the rating threshold merely SURFACES candidates to the admin.
    #[serde(default)]
    pub hidden: bool,
}
