#[cfg(target_arch = "wasm32")]
async fn course_nft_owner_of(token_id: u64) -> Result<Option<Principal>, String> {
    let id = course_nft_canister_id()?;
    let res: Result<(Vec<Option<Icrc7Account>>,), _> =
        ic_cdk::call(id, "icrc7_owner_of", (vec![candid::Nat::from(token_id)],)).await;
    match res {
        Ok((mut v,)) => Ok(v.drain(..).next().flatten().map(|a| a.owner)),
        Err((c, m)) => Err(format!("OWNER_OF_REJECTED ({:?}): {}", c, m)),
    }
}

#[cfg(not(target_arch = "wasm32"))]
async fn course_nft_owner_of(token_id: u64) -> Result<Option<Principal>, String> {
    Ok(TEST_MOCK_OWNER.with(|m| m.borrow().get(&token_id).copied()))
}

#[cfg(target_arch = "wasm32")]
async fn course_nft_mint(args: CourseMintArgs) -> Result<u64, String> {
    let id = course_nft_canister_id()?;
    let res: Result<(Result<u64, String>,), _> = ic_cdk::call(id, "mint", (args,)).await;
    match res {
        Ok((Ok(token_id),)) => Ok(token_id),
        Ok((Err(e),)) => Err(format!("MINT_ERR: {}", e)),
        Err((c, m)) => Err(format!("MINT_REJECTED ({:?}): {}", c, m)),
    }
}

#[cfg(not(target_arch = "wasm32"))]
async fn course_nft_mint(args: CourseMintArgs) -> Result<u64, String> {
    let (next_id, fail) = TEST_MOCK_MINT.with(|c| *c.borrow());
    if fail {
        return Err("MINT_REJECTED (mock failure)".to_string());
    }
    // Reflect the new ownership into the owner mock so play tests can resolve it.
    set_mock_owner(next_id, args.to);
    set_mock_mint(next_id + 1, false);
    Ok(next_id)
}

/// PB-301/307: move a token seller→buyer via the course_nft canister's custodial
/// path. The canister asserts `from == current owner`, so a stale seller (moved
/// out-of-band) makes this reject — which the buy saga turns into a refund.
#[cfg(target_arch = "wasm32")]
async fn course_nft_custodial_transfer(
    from: Principal,
    to: Principal,
    token_id: u64,
) -> Result<(), String> {
    let id = course_nft_canister_id()?;
    let res: Result<(Result<(), String>,), _> =
        ic_cdk::call(id, "custodial_transfer", (from, to, token_id)).await;
    match res {
        Ok((Ok(()),)) => Ok(()),
        Ok((Err(e),)) => Err(format!("TRANSFER_ERR: {}", e)),
        Err((c, m)) => Err(format!("TRANSFER_REJECTED ({:?}): {}", c, m)),
    }
}

#[cfg(not(target_arch = "wasm32"))]
async fn course_nft_custodial_transfer(
    from: Principal,
    to: Principal,
    token_id: u64,
) -> Result<(), String> {
    // Forced-failure seam for C3 ordering/refund tests.
    if TEST_MOCK_TRANSFER_FAIL.with(|c| *c.borrow()) {
        return Err("TRANSFER_REJECTED (mock failure)".to_string());
    }
    // Assert from == live owner, mirroring the real canister, then move it.
    let live = TEST_MOCK_OWNER.with(|m| m.borrow().get(&token_id).copied());
    if live != Some(from) {
        return Err("TRANSFER_ERR: from != owner".to_string());
    }
    set_mock_owner(token_id, to);
    Ok(())
}

#[cfg(target_arch = "wasm32")]
async fn course_nft_increment_play(token_id: u64) {
    if let Ok(id) = course_nft_canister_id() {
        let _: Result<(Result<(), String>,), _> =
            ic_cdk::call(id, "increment_play", (token_id,)).await;
        // Best-effort cosmetic provenance — never fail the play call (PB-306 A6).
    }
}

#[cfg(not(target_arch = "wasm32"))]
async fn course_nft_increment_play(token_id: u64) {
    TEST_MOCK_INCREMENT_PLAY.with(|v| v.borrow_mut().push(token_id));
}

/// PB-3xx: burn a token via the course_nft canister's `burn(nat) -> Result`.
/// The canister gates burn to owner-or-minter; the backend is the minter, so it
/// can burn on the verified owner's behalf (caller-is-live-owner is checked in
/// `burn_course_nft` BEFORE this is called). The token id is passed as a candid
/// `nat`. A "token already gone" reject is mapped to Ok so the destructive path
/// is idempotent (caller has already authorized removal of this token id).
#[cfg(target_arch = "wasm32")]
async fn course_nft_burn(token_id: u64) -> Result<(), String> {
    let id = course_nft_canister_id()?;
    let res: Result<(Result<(), String>,), _> =
        ic_cdk::call(id, "burn", (candid::Nat::from(token_id),)).await;
    match res {
        Ok((Ok(()),)) => Ok(()),
        Ok((Err(e),)) => Err(format!("BURN_ERR: {}", e)),
        Err((c, m)) => Err(format!("BURN_REJECTED ({:?}): {}", c, m)),
    }
}

#[cfg(not(target_arch = "wasm32"))]
async fn course_nft_burn(token_id: u64) -> Result<(), String> {
    // Forced-failure seam for burn-failure tests.
    if TEST_MOCK_BURN_FAIL.with(|c| *c.borrow()) {
        return Err("BURN_REJECTED (mock failure)".to_string());
    }
    // Mirror the real canister: clearing the live owner makes the token "gone".
    clear_mock_owner(token_id);
    Ok(())
}

// ── Difficulty bucket (PB-305) ───────────────────────────────────────────────

#[derive(CandidType, Serialize, Deserialize, Clone, Debug, PartialEq, Eq)]
pub enum Difficulty {
    Easy,
    Medium,
    Hard,
}

fn difficulty_bucket(par_total: u8) -> Difficulty {
    if par_total <= 27 {
        Difficulty::Easy
    } else if par_total >= 45 {
        Difficulty::Hard
    } else {
        Difficulty::Medium
    }
}

// ── Mint (PB-304) ─────────────────────────────────────────────────────────────

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub enum MintError {
    NotAuthenticated,
    InvalidCourse(String),
    InsufficientDeposit { needed: u64, found: u64 },
    FeeSettlementFailed(String),
    MintCallFailed(String),
    AlreadyMinting,
}

/// Minimal MVP server-side validation (PB-304 B2). Full validation of the
/// build-instructions JSON is owned by the frontend compiler; here we enforce
/// the trust-boundary essentials: blob size, non-empty, name bounds. Returns
/// `par_total` parsed best-effort.
fn validate_course_for_mint(bytes: &[u8], name: &str) -> Result<u8, MintError> {
    if bytes.is_empty() {
        return Err(MintError::InvalidCourse("EMPTY_COURSE_DATA".into()));
    }
    if bytes.len() > MAX_COURSE_DATA_BYTES {
        return Err(MintError::InvalidCourse("DATA_TOO_LARGE".into()));
    }
    let chars = name.chars().count();
    if chars == 0 {
        return Err(MintError::InvalidCourse("NAME_EMPTY".into()));
    }
    if chars > MAX_COURSE_NAME_CHARS {
        return Err(MintError::InvalidCourse("NAME_TOO_LONG".into()));
    }
    // Originality gate: reject clones of already-minted courses (canonical
    // hole-layout fingerprints — mirroring/rotating/shifting doesn't evade).
    let dups = find_duplicate_holes(bytes);
    if dups.len() >= CLONE_HOLE_LIMIT {
        return Err(MintError::InvalidCourse(format!(
            "DUPLICATE_HOLES:{}",
            dups.len()
        )));
    }
    Ok(decode_course_meta(bytes))
}

/// Best-effort extraction of `par_total` from a course blob for the
/// marketplace cache. Current format: build-instructions JSON — par_total is
/// the sum of `holes[].par`. Legacy format: CBOR map with a `par_total`
/// convenience field. Tolerant: returns 0 if neither parses.
fn decode_course_meta(bytes: &[u8]) -> u8 {
    // JSON build instructions (current format).
    if bytes.first() == Some(&b'{') {
        if let Ok(v) = serde_json::from_slice::<serde_json::Value>(bytes) {
            if let Some(holes) = v.get("holes").and_then(|h| h.as_array()) {
                let sum: u64 = holes
                    .iter()
                    .filter_map(|h| h.get("par").and_then(|p| p.as_u64()))
                    .sum();
                return u8::try_from(sum).unwrap_or(0);
            }
        }
    }
    // Legacy CBOR blob.
    use ciborium::value::Value as Cv;
    let parsed: Result<Cv, _> = ciborium::from_reader(bytes);
    if let Ok(Cv::Map(entries)) = parsed {
        for (k, v) in entries {
            if let (Cv::Text(key), Cv::Integer(i)) = (k, v) {
                if key == "par_total" {
                    return u8::try_from(i128::from(i)).unwrap_or(0);
                }
            }
        }
    }
    0
}

// ── Course originality (clone detection) ─────────────────────────────────────
// A cloned course is rarely byte-identical: the JSON reformats, names change,
// layouts get mirrored or shifted. So uniqueness is enforced per HOLE on a
// canonical form of the ASCII layout: pad ragged rows with void, trim the
// all-void border (translation invariance), then hash the lexicographically
// smallest of the 8 dihedral transforms (rotation + mirror invariance).
// Par, hole names and windmills deliberately do NOT contribute — tweaking the
// par on a stolen layout is still a clone. Legacy CBOR blobs yield no
// fingerprints and are exempt (only the pre-pivot system course).

/// Layout rows → rectangular char grid (ragged rows padded with '.').
fn layout_grid(rows: &[String]) -> Vec<Vec<char>> {
    let width = rows.iter().map(|r| r.chars().count()).max().unwrap_or(0);
    rows.iter()
        .map(|r| {
            let mut row: Vec<char> = r.chars().collect();
            row.resize(width, '.');
            row
        })
        .collect()
}

/// Drop all-void ('.') rows/columns from every border, so shifting a layout
/// inside a larger grid doesn't change its fingerprint.
fn trim_void_border(grid: Vec<Vec<char>>) -> Vec<Vec<char>> {
    let is_void_row = |row: &Vec<char>| row.iter().all(|&c| c == '.');
    let mut rows: Vec<Vec<char>> = grid;
    while rows.first().is_some_and(is_void_row) {
        rows.remove(0);
    }
    while rows.last().is_some_and(is_void_row) {
        rows.pop();
    }
    if rows.is_empty() {
        return rows;
    }
    let width = rows[0].len();
    let col_void = |c: usize| rows.iter().all(|r| r[c] == '.');
    let mut left = 0;
    while left < width && col_void(left) {
        left += 1;
    }
    let mut right = width;
    while right > left && col_void(right - 1) {
        right -= 1;
    }
    rows.into_iter().map(|r| r[left..right].to_vec()).collect()
}

/// Rotate a rectangular grid 90° clockwise.
fn rotate_cw(grid: &[Vec<char>]) -> Vec<Vec<char>> {
    if grid.is_empty() {
        return Vec::new();
    }
    let (h, w) = (grid.len(), grid[0].len());
    (0..w)
        .map(|x| (0..h).map(|y| grid[h - 1 - y][x]).collect())
        .collect()
}

/// Mirror a grid horizontally.
fn mirror_h(grid: &[Vec<char>]) -> Vec<Vec<char>> {
    grid.iter()
        .map(|r| r.iter().rev().copied().collect())
        .collect()
}

/// Canonical fingerprint of one hole layout: SHA-256 hex of the smallest of
/// the 8 dihedral transforms of the trimmed grid. Rotating, mirroring, or
/// translating a layout yields the SAME fingerprint.
fn canonical_hole_fp(rows: &[String]) -> String {
    let base = trim_void_border(layout_grid(rows));
    let mut best: Option<String> = None;
    let mut g = base;
    for _ in 0..2 {
        for _ in 0..4 {
            let s = g
                .iter()
                .map(|r| r.iter().collect::<String>())
                .collect::<Vec<_>>()
                .join("\n");
            if best.as_ref().is_none_or(|b| s < *b) {
                best = Some(s);
            }
            g = rotate_cw(&g);
        }
        g = mirror_h(&g);
    }
    use sha2::Digest;
    let mut hasher = sha2::Sha256::new();
    hasher.update(best.unwrap_or_default().as_bytes());
    hasher
        .finalize()
        .iter()
        .map(|b| format!("{:02x}", b))
        .collect()
}

/// All hole fingerprints of a build-instructions JSON blob, in hole order.
/// Non-JSON (legacy CBOR) or malformed docs yield an empty vec — exempt.
fn course_hole_fps(bytes: &[u8]) -> Vec<String> {
    if bytes.first() != Some(&b'{') {
        return Vec::new();
    }
    let Ok(v) = serde_json::from_slice::<serde_json::Value>(bytes) else {
        return Vec::new();
    };
    let Some(holes) = v.get("holes").and_then(|h| h.as_array()) else {
        return Vec::new();
    };
    holes
        .iter()
        .filter_map(|h| h.get("layout").and_then(|l| l.as_array()))
        .map(|layout| {
            let rows: Vec<String> = layout
                .iter()
                .filter_map(|r| r.as_str().map(|s| s.to_string()))
                .collect();
            canonical_hole_fp(&rows)
        })
        .collect()
}

/// (hole_index, existing token_id) for every hole of `bytes` whose canonical
/// layout is already minted in some course.
fn find_duplicate_holes(bytes: &[u8]) -> Vec<(u8, u64)> {
    let fps = course_hole_fps(bytes);
    COURSE_HOLE_FPS.with(|m| {
        let map = m.borrow();
        fps.iter()
            .enumerate()
            .filter_map(|(i, fp)| map.get(fp).map(|tid| (i as u8, tid)))
            .collect()
    })
}

/// Register a freshly minted/seeded course's hole layouts. First minter wins:
/// existing fingerprints are never overwritten. Idempotent.
fn register_course_fps(bytes: &[u8], token_id: u64) {
    let fps = course_hole_fps(bytes);
    COURSE_HOLE_FPS.with(|m| {
        let mut map = m.borrow_mut();
        for fp in fps {
            if map.get(&fp).is_none() {
                map.insert(fp, token_id);
            }
        }
    });
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct DuplicateHole {
    pub hole_index: u8,
    pub token_id: u64,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct CourseUniquenessReport {
    pub duplicates: Vec<DuplicateHole>,
    pub would_block: bool,
    pub limit: u8,
}

/// Pre-mint originality check (free, anonymous-callable) so the create flow
/// can warn BEFORE the user pays the mint fee. The same rule is enforced
/// server-side in `validate_course_for_mint` — this query is advisory UX.
#[ic_cdk::query]
fn check_course_uniqueness(course_data: Vec<u8>) -> CourseUniquenessReport {
    let duplicates: Vec<DuplicateHole> = find_duplicate_holes(&course_data)
        .into_iter()
        .map(|(hole_index, token_id)| DuplicateHole {
            hole_index,
            token_id,
        })
        .collect();
    CourseUniquenessReport {
        would_block: duplicates.len() >= CLONE_HOLE_LIMIT,
        limit: CLONE_HOLE_LIMIT as u8,
        duplicates,
    }
}

/// Backfill the originality index for courses minted before this feature
/// (their blobs live in the course_nft canister). Safe to re-run; returns how
/// many courses were fingerprinted.
#[ic_cdk::update(guard = "require_admin")]
async fn admin_backfill_course_fingerprints() -> u32 {
    let ids: Vec<u64> =
        COURSE_LISTINGS.with(|m| m.borrow().iter().map(|e| *e.key()).collect());
    let mut done = 0u32;
    for token_id in ids {
        if let Some(blob) = get_course_data(token_id).await {
            register_course_fps(&blob, token_id);
            done += 1;
        }
    }
    done
}

#[ic_cdk::query(guard = "require_authenticated")]
fn get_mint_deposit_address() -> LedgerAccount {
    LedgerAccount {
        owner: get_canister_id(),
        subaccount: Some(derive_subaccount(&get_caller(), MINT_ESCROW_TAG)),
    }
}

#[ic_cdk::update(guard = "require_authenticated")]
async fn mint_course_nft(course_data: Vec<u8>, name: String) -> Result<u64, MintError> {
    let caller = get_caller();
    if caller == Principal::anonymous() {
        return Err(MintError::NotAuthenticated);
    }
    // No tier gate (owner decision 2026-07-01): any signed-in user with the
    // ICP fee can mint. Playing for TICKETS stays tier-gated elsewhere.

    // Concurrency guard (B5).
    let acquired = MINTING_IN_FLIGHT.with(|s| s.borrow_mut().insert(caller));
    if !acquired {
        return Err(MintError::AlreadyMinting);
    }
    let result = mint_course_nft_inner(caller, course_data, name).await;
    MINTING_IN_FLIGHT.with(|s| {
        s.borrow_mut().remove(&caller);
    });
    result
}

async fn mint_course_nft_inner(
    caller: Principal,
    course_data: Vec<u8>,
    name: String,
) -> Result<u64, MintError> {
    let ledger_id = CONFIG.with(|c| c.borrow().get().ledger_canister_id);
    let now = current_time();

    // Step 1 — resume an incomplete saga, else validate + persist a fresh one.
    let mut saga = match MINT_SAGAS.with(|m| m.borrow().get(&caller)) {
        Some(existing) => existing, // retry of the same course (idempotent resume)
        None => {
            let par_total = validate_course_for_mint(&course_data, &name)?;
            let s = MintSaga {
                caller,
                course_data: course_data.clone(),
                name: name.clone(),
                par_total,
                fee_e8s: MINT_FEE_E8S,
                treasury_block: None,
                cmc_block_index: None,
                frontend_cmc_block: None,
                minted_token_id: None,
                listed: false,
                started_at: now,
            };
            MINT_SAGAS.with(|m| {
                m.borrow_mut().insert(caller, s.clone());
            });
            s
        }
    };

    let mint_sub = derive_subaccount(&caller, MINT_ESCROW_TAG);

    // Step 2 — verify deposit (only if the fee hasn't already been charged).
    let fee_settled = saga.treasury_block.is_some()
        && saga.cmc_block_index.is_some()
        && saga.frontend_cmc_block.is_some();
    // Full-fee balance check only while NO leg has settled: once any split leg
    // is journaled the escrow legitimately holds less than the fee, and
    // settle_burn_split's own required/shortfall math (treasury fee-cover)
    // takes over for the remaining legs — demanding the full fee again on a
    // resume would wrongly report InsufficientDeposit mid-saga.
    let no_leg_settled = saga.treasury_block.is_none()
        && saga.cmc_block_index.is_none()
        && saga.frontend_cmc_block.is_none();
    if !fee_settled {
        if no_leg_settled {
            let escrow = LedgerAccount {
                owner: get_canister_id(),
                subaccount: Some(mint_sub),
            };
            let balance = call_ledger_balance(ledger_id, escrow)
                .await
                .map_err(|e| MintError::FeeSettlementFailed(format!("ESCROW_BALANCE: {}", e)))?;
            if balance < MINT_FEE_E8S {
                return Err(MintError::InsufficientDeposit {
                    needed: MINT_FEE_E8S,
                    found: balance,
                });
            }
        }

        // Step 3 — charge: 50/25/25 split, idempotent per leg (reuse
        // settle_burn_split via a Commitment with proposal_id = MINT_ESCROW_TAG).
        let mut commitment = Commitment {
            proposal_id: MINT_ESCROW_TAG,
            principal: caller,
            amount_e8s: MINT_FEE_E8S,
            status: CommitmentStatus::Pending,
            created_at: saga.started_at,
            stance: Stance::Adopt,
            subaccount: mint_sub,
            settled_at: None,
            cmc_block_index: saga.cmc_block_index,
            treasury_block: saga.treasury_block,
            frontend_cmc_block: saga.frontend_cmc_block,
            token: None,
            token_amount: None,
            swapped_icp_e8s: None,        };
        // Third leg → the course_nft canister's cycles (owner decision
        // 2026-07-04): minting a course funds the canister that stores it.
        let nft_target = course_nft_canister_id()
            .map_err(|_| MintError::FeeSettlementFailed("COURSE_NFT_NOT_CONFIGURED".into()))?;
        let settle =
            settle_burn_split_with_target(ledger_id, mint_sub, MINT_FEE_E8S, &mut commitment, nft_target).await;
        // Mirror block indices back regardless of outcome (partial progress).
        saga.treasury_block = commitment.treasury_block;
        saga.cmc_block_index = commitment.cmc_block_index;
        saga.frontend_cmc_block = commitment.frontend_cmc_block;
        MINT_SAGAS.with(|m| {
            m.borrow_mut().insert(caller, saga.clone());
        });
        settle.map_err(MintError::FeeSettlementFailed)?;
    }

    // Step 4 — mint the token (skipped if already minted).
    if saga.minted_token_id.is_none() {
        let token_id = course_nft_mint(CourseMintArgs {
            to: caller,
            name: saga.name.clone(),
            creator: caller,
            course_data: saga.course_data.clone(),
            par_total: saga.par_total as u16,
            mint_fee_e8s: MINT_FEE_E8S,
        })
        .await
        .map_err(MintError::MintCallFailed)?;
        saga.minted_token_id = Some(token_id);
        MINT_SAGAS.with(|m| {
            m.borrow_mut().insert(caller, saga.clone());
        });
        // Originality index: claim these hole layouts for this token so later
        // mints of the same (or mirrored/shifted) holes are detected.
        register_course_fps(&saga.course_data, token_id);
    }
    let token_id = saga.minted_token_id.unwrap();

    // Step 5 — auto-list (idempotent).
    if !saga.listed {
        COURSE_LISTINGS.with(|m| {
            m.borrow_mut().insert(
                token_id,
                CourseListing {
                    token_id,
                    listed: true,
                    price_e8s: 0,
                    name: saga.name.clone(),
                    owner: Some(caller),
                    creator: Some(caller),
                    play_count: 0,
                    tickets_distributed: 0,
                    par_total: saga.par_total,
                    created_at: saga.started_at,
                    mint_fee_e8s: MINT_FEE_E8S,
                    for_sale: false,
                    rating_sum: 0,
                    rating_count: 0,
                    hidden: false,
                },
            );
        });
        saga.listed = true;
        MINT_SAGAS.with(|m| {
            m.borrow_mut().insert(caller, saga.clone());
        });
    }

    // Step 6 — finalize: clear saga, log.
    MINT_SAGAS.with(|m| {
        m.borrow_mut().remove(&caller);
    });
    log_dapp_event("course_mint", token_id, caller, MINT_FEE_E8S);
    Ok(token_id)
}

/// Tier derivation (mirrors `get_eligibility`): 0 anon, 1 authed-not-following,
/// 2+ following. Used for the mint gate and the player-ticket gate.
fn course_caller_tier(caller: Principal) -> u8 {
    if caller == Principal::anonymous() {
        return 0;
    }
    let following = USER_NEURONS
        .with(|m| m.borrow().get(&caller).map(|s| s.is_following).unwrap_or(false));
    if following {
        2
    } else {
        1
    }
}

// ── Marketplace (PB-305) ─────────────────────────────────────────────────────

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub enum DifficultyFilter {
    Any,
    Easy,
    Medium,
    Hard,
}
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub enum ListedFilter {
    Any,
    Yes,
    No,
}
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct MarketplaceFilter {
    pub difficulty: DifficultyFilter,
    pub listed: ListedFilter,
    pub mine_only: bool,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct CourseCard {
    pub token_id: u64,
    pub name: String,
    pub creator: Option<Principal>,
    pub owner: Option<Principal>,
    pub par_total: u8,
    pub play_count: u64,
    pub tickets_distributed: u64,
    pub listed: bool,
    pub price_e8s: u64,
    pub created_at: u64,
    pub is_caller_owner: bool,
    pub for_sale: bool,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct MarketplacePage {
    pub courses: Vec<CourseCard>,
    pub seed: u64,
    pub total: u64,
}

fn listing_to_card(l: &CourseListing, caller: Principal) -> CourseCard {
    CourseCard {
        token_id: l.token_id,
        name: l.name.clone(),
        creator: l.creator,
        owner: l.owner,
        par_total: l.par_total,
        play_count: l.play_count,
        tickets_distributed: l.tickets_distributed,
        listed: l.listed,
        price_e8s: l.price_e8s,
        created_at: l.created_at,
        is_caller_owner: l.owner == Some(caller),
        for_sale: l.for_sale,
    }
}

fn listing_matches(l: &CourseListing, f: &MarketplaceFilter, caller: Principal) -> bool {
    match f.difficulty {
        DifficultyFilter::Any => {}
        DifficultyFilter::Easy => {
            if difficulty_bucket(l.par_total) != Difficulty::Easy {
                return false;
            }
        }
        DifficultyFilter::Medium => {
            if difficulty_bucket(l.par_total) != Difficulty::Medium {
                return false;
            }
        }
        DifficultyFilter::Hard => {
            if difficulty_bucket(l.par_total) != Difficulty::Hard {
                return false;
            }
        }
    }
    match f.listed {
        ListedFilter::Any => {}
        ListedFilter::Yes => {
            if !l.listed {
                return false;
            }
        }
        ListedFilter::No => {
            if l.listed {
                return false;
            }
        }
    }
    if f.mine_only && l.owner != Some(caller) {
        return false;
    }
    true
}

#[ic_cdk::query]
fn list_marketplace_courses(filter: MarketplaceFilter) -> MarketplacePage {
    let caller = get_caller();
    // Degrade to an empty page when the arcade mini-golf surface is off for the
    // caller (the nav hides it; a query must not trap — PB-305 B3).
    if require_arcade_game_enabled(ARCADE_GAME_MINIGOLF).is_err() {
        return MarketplacePage {
            courses: vec![],
            seed: 0,
            total: 0,
        };
    }
    // Moderation visibility (PB-3xx): hidden courses must vanish from public
    // browsing. Direct resolution by token id (get_course / get_course_data)
    // is intentionally left intact so the owner of a hidden course isn't fully
    // locked out.
    let mut matched: Vec<CourseCard> = COURSE_LISTINGS.with(|m| {
        m.borrow()
            .iter()
            .map(|e| e.value())
            .filter(|l| !l.hidden)
            .filter(|l| listing_matches(l, &filter, caller))
            .map(|l| listing_to_card(&l, caller))
            .collect()
    });
    matched.sort_by_key(|c| c.token_id);
    let total = matched.len() as u64;
    let seed = current_time(); // cheap shuffle hint; FE re-rolls its own seed.
    MarketplacePage {
        courses: matched,
        seed,
        total,
    }
}

#[ic_cdk::query]
fn get_course(token_id: u64) -> Option<CourseCard> {
    let caller = get_caller();
    COURSE_LISTINGS.with(|m| m.borrow().get(&token_id).map(|l| listing_to_card(&l, caller)))
}

#[ic_cdk::update]
async fn get_course_data(token_id: u64) -> Option<Vec<u8>> {
    // Passthrough for Play: read the verbatim course_data blob from the
    // authoritative CourseNFT canister (PB-305 B3). Update (awaits a query call).
    let id = match course_nft_canister_id() {
        Ok(id) => id,
        Err(_) => return None,
    };
    #[cfg(target_arch = "wasm32")]
    {
        let res: Result<(Vec<Option<Vec<u8>>>,), _> =
            ic_cdk::call(id, "course_data_of", (vec![candid::Nat::from(token_id)],)).await;
        match res {
            Ok((mut v,)) => v.drain(..).next().flatten(),
            Err(_) => None,
        }
    }
    #[cfg(not(target_arch = "wasm32"))]
    {
        let _ = id;
        let _ = token_id;
        None
    }
}

/// PB-307 A2/B3: put a (live-owned) course up for fixed-price sale. Sets
/// `for_sale=true` + `price_e8s`. Owner-gated against the LIVE owner
/// (`icrc7_owner_of`), not the cached row. Keeps the course `listed` (playable).
#[ic_cdk::update(guard = "require_authenticated")]
async fn list_course_for_sale(token_id: u64, price_e8s: u64) -> Result<(), String> {
    require_arcade_game_enabled(ARCADE_GAME_MINIGOLF)?;
    let caller = get_caller();
    if !(MIN_SALE_PRICE_E8S..=MAX_SALE_PRICE_E8S).contains(&price_e8s) {
        return Err("BAD_PRICE".to_string());
    }
    let owner = course_nft_owner_of(token_id)
        .await?
        .ok_or_else(|| "TOKEN_NOT_FOUND".to_string())?;
    if owner != caller {
        return Err("NOT_OWNER".to_string());
    }
    COURSE_LISTINGS.with(|m| {
        let mut map = m.borrow_mut();
        let mut row = map.get(&token_id).unwrap_or(CourseListing {
            token_id,
            listed: true,
            price_e8s: 0,
            name: String::new(),
            owner: Some(owner),
            creator: Some(owner),
            play_count: 0,
            tickets_distributed: 0,
            par_total: 0,
            created_at: current_time(),
            mint_fee_e8s: 0,
            for_sale: false,
            rating_sum: 0,
            rating_count: 0,
            hidden: false,
        });
        row.listed = true;
        row.for_sale = true;
        row.price_e8s = price_e8s;
        row.owner = Some(owner); // refresh stale cache (A2)
        map.insert(token_id, row);
    });
    Ok(())
}

/// PB-307 A2: take a course off sale. Flips `for_sale=false`, clears the price.
/// The listing row (and `listed` visibility / ticket accrual) is preserved.
#[ic_cdk::update(guard = "require_authenticated")]
async fn delist_course(token_id: u64) -> Result<(), String> {
    require_arcade_game_enabled(ARCADE_GAME_MINIGOLF)?;
    let caller = get_caller();
    let owner = course_nft_owner_of(token_id)
        .await?
        .ok_or_else(|| "TOKEN_NOT_FOUND".to_string())?;
    if owner != caller {
        return Err("NOT_OWNER".to_string());
    }
    COURSE_LISTINGS.with(|m| {
        let mut map = m.borrow_mut();
        if let Some(mut row) = map.get(&token_id) {
            row.for_sale = false;
            row.price_e8s = 0;
            row.owner = Some(owner);
            map.insert(token_id, row);
            Ok(())
        } else {
            Err("LISTING_NOT_FOUND".to_string())
        }
    })
}

#[ic_cdk::update]
async fn refresh_course_listing(token_id: u64) -> Result<(), String> {
    // Lazy cache reconciliation (PB-305 B6): re-read the live owner. (Metadata
    // refresh beyond owner is best-effort; PB-301 owns the metadata decode.)
    let owner = course_nft_owner_of(token_id).await?;
    COURSE_LISTINGS.with(|m| {
        let mut map = m.borrow_mut();
        if let Some(mut row) = map.get(&token_id) {
            row.owner = owner;
            map.insert(token_id, row);
            Ok(())
        } else {
            Err("LISTING_NOT_FOUND".to_string())
        }
    })
}

/// Owner-initiated burn of a course NFT, with backend marketplace cleanup
/// (PB-3xx). Destructive + a security boundary, so:
///   1. Reject anonymous.
///   2. Verify the caller is the LIVE owner via `course_nft.icrc7_owner_of`
///      (never the cached listing row — the cache can be stale / spoofable).
///      A non-owner gets `NOT_OWNER`; a missing token gets `TOKEN_NOT_FOUND`.
///   3. Burn on the verified owner's behalf via `course_nft.burn(nat)` (the
///      backend is the allowlisted minter, which the canister also accepts for
///      burn). A "token already gone" reject is treated as success by the
///      wrapper so the path is idempotent.
///   4. Clean up backend state: drop the COURSE_LISTINGS row. Favorites are
///      per-user lists that already skip missing tokens
///      (list_my_favorite_courses), so they are left to lazy cleanup rather
///      than scanned here.
#[ic_cdk::update(guard = "require_authenticated")]
async fn burn_course_nft(token_id: u64) -> Result<(), String> {
    require_arcade_game_enabled(ARCADE_GAME_MINIGOLF)?;
    let caller = get_caller();
    if caller == Principal::anonymous() {
        return Err("NOT_AUTHENTICATED".to_string());
    }

    // Auth against the LIVE owner — never the cached listing row.
    let owner = course_nft_owner_of(token_id)
        .await?
        .ok_or_else(|| "TOKEN_NOT_FOUND".to_string())?;
    if owner != caller {
        return Err("NOT_OWNER".to_string());
    }

    // Burn on the verified owner's behalf (idempotent if already gone).
    course_nft_burn(token_id).await?;

    course_burn_cleanup(token_id, caller);
    Ok(())
}

/// Shared marketplace cleanup after a token is burned (owner-initiated via
/// `burn_course_nft` or admin-forced via `admin_burn_course`). Safe if the row
/// is already absent. Favorites are left to lazy cleanup
/// (list_my_favorite_courses skips missing tokens).
fn course_burn_cleanup(token_id: u64, caller: Principal) {
    COURSE_LISTINGS.with(|m| {
        m.borrow_mut().remove(&token_id);
    });
    log_dapp_event("course_burn", token_id, caller, 0);
}

#[ic_cdk::update(guard = "require_admin")]
fn admin_set_course_nft_canister(canister: Principal) -> Result<(), String> {
    if canister == Principal::anonymous() {
        return Err("INVALID_CANISTER".to_string());
    }
    CONFIG.with(|cell| {
        let mut cfg = cell.borrow().get().clone();
        cfg.course_nft_canister = Some(canister);
        cell.borrow_mut().set(cfg);
    });
    Ok(())
}

// ── Course moderation (PB-3xx, admin discretion) ─────────────────────────────
//
// Admins can soft-hide a low-quality course (removes it from public browsing,
// reversible) or burn it outright. This is ADMIN-DISCRETION: nothing is hidden
// or burned automatically. The rating threshold below only SURFACES candidates
// to the admin via `admin_list_moderation_candidates`.

/// A course is eligible to be *surfaced* for moderation when its average rating
/// is strictly below this threshold (out of 5). Surfacing only — never auto-acts.
const MODERATION_RATING_THRESHOLD_X10: u32 = 20; // 2.0 / 5, stored ×10 (no floats)
/// ...AND it has at least this many distinct ratings, so a course with a tiny
/// sample (one or two sour reviews) is NOT flagged.
const MODERATION_MIN_RATINGS: u32 = 5;
/// Cap on rows returned by `admin_list_moderation_candidates` (mirrors other
/// admin list queries — the caller's `limit` is min'd against this).
const MODERATION_CANDIDATES_MAX: u32 = 200;

/// Surfacing-only eligibility (PB-3xx): true iff the course has enough ratings
/// AND its average is below the threshold. Does NOT consider `hidden` and never
/// triggers any action — the admin decides.
fn course_eligible_for_moderation(rating_sum: u64, rating_count: u32) -> bool {
    if rating_count < MODERATION_MIN_RATINGS {
        return false;
    }
    let avg_x10 = rating_sum * 10 / rating_count as u64;
    avg_x10 < MODERATION_RATING_THRESHOLD_X10 as u64
}

/// One surfaced moderation candidate (admin-only view).
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct ModerationCandidate {
    pub token_id: u64,
    pub owner: Option<Principal>,
    pub avg_x10: u32, // average stars ×10 (no floats on the wire)
    pub rating_count: u32,
    pub hidden: bool,
}

#[ic_cdk::query(guard = "require_admin")]
fn admin_list_moderation_candidates(limit: u32) -> Vec<ModerationCandidate> {
    let limit = limit.min(MODERATION_CANDIDATES_MAX);
    if limit == 0 {
        return vec![];
    }
    let mut rows: Vec<ModerationCandidate> = COURSE_LISTINGS.with(|m| {
        m.borrow()
            .iter()
            .map(|e| e.value())
            .filter(|l| course_eligible_for_moderation(l.rating_sum, l.rating_count))
            .map(|l| {
                let avg_x10 = if l.rating_count > 0 {
                    u32::try_from(l.rating_sum * 10 / l.rating_count as u64).unwrap_or(0)
                } else {
                    0
                };
                ModerationCandidate {
                    token_id: l.token_id,
                    owner: l.owner,
                    avg_x10,
                    rating_count: l.rating_count,
                    hidden: l.hidden,
                }
            })
            .collect()
    });
    // Worst-rated first (then lowest token id) so the admin triages the most
    // egregious courses first.
    rows.sort_by(|a, b| a.avg_x10.cmp(&b.avg_x10).then(a.token_id.cmp(&b.token_id)));
    rows.truncate(limit as usize);
    rows
}

#[ic_cdk::update(guard = "require_admin")]
fn admin_hide_course(token_id: u64) -> Result<(), String> {
    require_admin()?;
    COURSE_LISTINGS.with(|m| {
        let mut map = m.borrow_mut();
        match map.get(&token_id) {
            Some(mut row) => {
                row.hidden = true;
                map.insert(token_id, row);
                Ok(())
            }
            None => Err("NO_COURSE".to_string()),
        }
    })
}

#[ic_cdk::update(guard = "require_admin")]
fn admin_unhide_course(token_id: u64) -> Result<(), String> {
    require_admin()?;
    COURSE_LISTINGS.with(|m| {
        let mut map = m.borrow_mut();
        match map.get(&token_id) {
            Some(mut row) => {
                row.hidden = false;
                map.insert(token_id, row);
                Ok(())
            }
            None => Err("NO_COURSE".to_string()),
        }
    })
}

/// Admin-forced burn of ANY course token regardless of owner (PB-3xx). Same
/// destructive marketplace cleanup as `burn_course_nft`, but skips the
/// caller-is-live-owner check (the burn is on admin authority). The course_nft
/// canister accepts a burn from the backend (the allowlisted minter), so this
/// works for any token. Idempotent: a "token already gone" reject from the
/// wrapper is treated as success.
#[ic_cdk::update(guard = "require_admin")]
async fn admin_burn_course(token_id: u64) -> Result<(), String> {
    require_admin()?;
    course_nft_burn(token_id).await?;
    let caller = get_caller();
    course_burn_cleanup(token_id, caller);
    Ok(())
}

// ── Secondary market: buy saga (PB-307, pure escrow / C3) ────────────────────

/// Per-sale escrow subaccount: backend-controlled, unique to (buyer, token).
fn sale_escrow_subaccount(buyer: &Principal, token_id: u64) -> [u8; 32] {
    derive_subaccount(buyer, SALE_ESCROW_TAG ^ token_id)
}

/// The five split amounts for a sale of `price_e8s`. Treasury takes the integer
/// remainder so the legs always sum to exactly `price_e8s`. When `coalesce`
/// (seller == creator) the royalty is folded into the seller leg and the royalty
/// leg is 0 (its block aliases the seller block in the journal).
struct SaleSplit {
    seller_amt: u64,   // includes royalty when coalesced
    royalty_amt: u64,  // 0 when coalesced
    backend_amt: u64,
    frontend_amt: u64,
    treasury_amt: u64,
}

fn compute_sale_split(price_e8s: u64, coalesce: bool) -> SaleSplit {
    let seller = price_e8s * COURSE_SALE_SELLER_BPS / 10_000;
    let royalty = price_e8s * COURSE_SALE_ROYALTY_BPS / 10_000;
    let backend = price_e8s * COURSE_SALE_BACKEND_BPS / 10_000;
    let frontend = price_e8s * COURSE_SALE_FRONTEND_BPS / 10_000;
    // Treasury = remainder (absorbs all integer-division rounding).
    let treasury = price_e8s - seller - royalty - backend - frontend;
    if coalesce {
        SaleSplit {
            seller_amt: seller + royalty,
            royalty_amt: 0,
            backend_amt: backend,
            frontend_amt: frontend,
            treasury_amt: treasury,
        }
    } else {
        SaleSplit {
            seller_amt: seller,
            royalty_amt: royalty,
            backend_amt: backend,
            frontend_amt: frontend,
            treasury_amt: treasury,
        }
    }
}

/// Drop-guard for the per-token reentrancy lock (A5). Releasing on drop means a
/// trap mid-saga can't wedge the token (the journal makes the retry safe anyway).
struct BuyLock(u64);
impl Drop for BuyLock {
    fn drop(&mut self) {
        BUY_LOCKS.with(|s| {
            s.borrow_mut().remove(&self.0);
        });
    }
}

/// Buy a listed-for-sale course (PB-307). Pure-escrow saga (A6/C3):
/// validate → pull buyer's price into escrow → transfer NFT FIRST →
/// pay the 75/10/5/5/5 legs out of escrow. On transfer failure, refund the
/// escrow to the buyer (the treasury never fronts the price).
#[ic_cdk::update(guard = "require_authenticated")]
async fn buy_course_nft(token_id: u64) -> Result<(), String> {
    require_arcade_game_enabled(ARCADE_GAME_MINIGOLF)?;
    let buyer = get_caller();

    // Reentrancy lock (A5): second concurrent buy on this token bounces.
    let acquired = BUY_LOCKS.with(|s| s.borrow_mut().insert(token_id));
    if !acquired {
        return Err("SALE_IN_PROGRESS".to_string());
    }
    let _lock = BuyLock(token_id);

    // ── Resume an in-flight saga, else validate + create one. ────────────────
    let now = current_time();
    let mut sale = match COURSE_SALES.with(|m| m.borrow().get(&token_id)) {
        // Only resume if it's the SAME buyer mid-saga (a previously interrupted
        // run). A finished/aliased row from a different buyer is overwritten.
        Some(existing) if existing.buyer == buyer && existing.refund_block.is_none() => existing,
        _ => {
            // Guards — all reject BEFORE any money moves (B7).
            let row = COURSE_LISTINGS
                .with(|m| m.borrow().get(&token_id))
                .ok_or_else(|| "NOT_FOR_SALE".to_string())?;
            if !row.for_sale || row.price_e8s == 0 {
                return Err("NOT_FOR_SALE".to_string());
            }
            let price_e8s = row.price_e8s;
            // Live seller resolution (A5): pay can never reach a stale owner.
            let seller = course_nft_owner_of(token_id)
                .await?
                .ok_or_else(|| "TOKEN_NOT_FOUND".to_string())?;
            if seller == buyer {
                return Err("CANNOT_BUY_OWN_COURSE".to_string());
            }
            // Creator read immutably from the listing cache (mirrored from
            // metadata at mint); the seller has no input into it.
            let creator = row.creator.unwrap_or(seller);
            CourseSale {
                token_id,
                buyer,
                seller,
                creator,
                price_e8s,
                started_at: now,
                pull_block: None,
                transferred: false,
                seller_block: None,
                royalty_block: None,
                backend_cmc_block: None,
                frontend_cmc_block: None,
                treasury_block: None,
                refund_block: None,
            }
        }
    };

    // Price-change guard (A5): the live listing price must still match the price
    // bound at saga start (what the buyer approved). Re-check on every (re)entry
    // before the pull, but only while we haven't pulled yet.
    if sale.pull_block.is_none() {
        let live = COURSE_LISTINGS.with(|m| m.borrow().get(&token_id));
        match live {
            Some(row) if row.for_sale && row.price_e8s == sale.price_e8s => {}
            Some(row) if row.for_sale => {
                return Err(format!("PRICE_CHANGED: {}", row.price_e8s));
            }
            _ => return Err("NOT_FOR_SALE".to_string()),
        }
    }

    COURSE_SALES.with(|m| {
        m.borrow_mut().insert(token_id, sale.clone());
    });

    run_buy_saga(&mut sale).await?;

    // Success: update the listing (new owner, off-sale) and clear the journal.
    COURSE_LISTINGS.with(|m| {
        let mut map = m.borrow_mut();
        if let Some(mut row) = map.get(&token_id) {
            row.owner = Some(sale.buyer);
            row.for_sale = false;
            row.price_e8s = 0;
            map.insert(token_id, row);
        }
    });
    COURSE_SALES.with(|m| {
        m.borrow_mut().remove(&token_id);
    });
    log_dapp_event("course_buy", token_id, sale.buyer, sale.price_e8s);
    Ok(())
}

/// Run the pure-escrow buy saga to completion, persisting after each step so an
/// interrupted run resumes without repeating any block-indexed leg (A6/C3).
async fn run_buy_saga(sale: &mut CourseSale) -> Result<(), String> {
    let ledger = CONFIG.with(|c| c.borrow().get().ledger_canister_id);
    let fee = ICP_FEE_E8S;
    let escrow_sub = sale_escrow_subaccount(&sale.buyer, sale.token_id);
    let escrow_acct = LedgerAccount {
        owner: get_canister_id(),
        subaccount: Some(escrow_sub),
    };

    // ── Step 1: pull the full price into escrow (once). ──────────────────────
    if sale.pull_block.is_none() {
        // The buyer approved price + fee; pull `price` into escrow (fee burned).
        call_icrc2_transfer_from(ledger, sale.buyer, escrow_acct.clone(), sale.price_e8s, fee)
            .await
            .map_err(|e| format!("ESCROW_PULL: {}", e))?;
        // Block index is cosmetic here (icrc2 returns one on-chain); a sentinel
        // marks the pull done for idempotency.
        sale.pull_block = Some(1);
        COURSE_SALES.with(|m| {
            m.borrow_mut().insert(sale.token_id, sale.clone());
        });
    }

    // ── Step 2: transfer the NFT FIRST (before any payout). ──────────────────
    if !sale.transferred {
        // Resolve the live owner immediately before transfer (A5): the seller
        // leg pays exactly this resolved principal.
        let live_owner = course_nft_owner_of(sale.token_id)
            .await?
            .ok_or_else(|| "TOKEN_NOT_FOUND".to_string())?;
        if live_owner == sale.buyer {
            // Already owns it (e.g. resumed after a prior success but pre-cleanup):
            // treat as transferred so payouts proceed against the recorded seller.
            sale.transferred = true;
        } else {
            // The recorded seller must still be the live owner, else refund (C3).
            if live_owner != sale.seller {
                refund_escrow_to_buyer(sale, ledger, escrow_sub).await?;
                return Err("OWNERSHIP_CHANGED".to_string());
            }
            match course_nft_custodial_transfer(sale.seller, sale.buyer, sale.token_id).await {
                Ok(()) => {
                    sale.transferred = true;
                }
                Err(e) => {
                    // Transfer failed → refund the escrow to the buyer. The
                    // treasury fronts only the single refund fee, never the price.
                    refund_escrow_to_buyer(sale, ledger, escrow_sub).await?;
                    return Err(format!("OWNERSHIP_CHANGED: {}", e));
                }
            }
        }
        COURSE_SALES.with(|m| {
            m.borrow_mut().insert(sale.token_id, sale.clone());
        });
    }

    // ── Step 3: pay the legs out of escrow (only after transfer). ────────────
    let coalesce = sale.seller == sale.creator;
    let split = compute_sale_split(sale.price_e8s, coalesce);

    // The escrow holds exactly `price`; the treasury fronts the per-leg ledger
    // fees (bounded ≤ 5 × fee), exactly like settle_burn_split. Top up the
    // escrow with the fees still owed for the legs not yet paid.
    {
        let mut required: u64 = 0;
        if sale.seller_block.is_none() {
            required += split.seller_amt + fee;
        }
        if sale.royalty_block.is_none() && split.royalty_amt > 0 {
            required += split.royalty_amt + fee;
        }
        if sale.backend_cmc_block.is_none() {
            required += split.backend_amt + fee;
        }
        if sale.frontend_cmc_block.is_none() {
            required += split.frontend_amt + fee;
        }
        if sale.treasury_block.is_none() {
            required += split.treasury_amt + fee;
        }
        let balance = call_ledger_balance(ledger, escrow_acct.clone())
            .await
            .map_err(|e| format!("ESCROW_BALANCE: {}", e))?;
        if balance < required {
            let shortfall = required - balance;
            call_ledger_transfer(ledger, Some(TREASURY_SUBACCOUNT), escrow_acct.clone(), shortfall, Some(fee))
                .await
                .map_err(|e| format!("TREASURY_FEE_COVER: {}", e))?;
        }
    }

    // Leg 1: seller 75% (coalesced to 85% when seller == creator).
    if sale.seller_block.is_none() {
        let dest = LedgerAccount { owner: sale.seller, subaccount: None };
        let b = call_ledger_transfer(ledger, Some(escrow_sub), dest, split.seller_amt, Some(fee))
            .await
            .map_err(|e| format!("SELLER_XFER: {}", e))?;
        sale.seller_block = Some(b);
        COURSE_SALES.with(|m| m.borrow_mut().insert(sale.token_id, sale.clone()));
    }

    // Leg 2: creator royalty 10% (aliases the seller block when coalesced).
    if sale.royalty_block.is_none() {
        if coalesce {
            sale.royalty_block = sale.seller_block; // alias — uniform idempotency
        } else {
            let dest = LedgerAccount { owner: sale.creator, subaccount: None };
            let b = call_ledger_transfer(ledger, Some(escrow_sub), dest, split.royalty_amt, Some(fee))
                .await
                .map_err(|e| format!("ROYALTY_XFER: {}", e))?;
            sale.royalty_block = Some(b);
        }
        COURSE_SALES.with(|m| m.borrow_mut().insert(sale.token_id, sale.clone()));
    }

    // Leg 3: backend cycles 5% via CMC top-up out of escrow.
    let cmc = Principal::from_text("rkp4c-7iaaa-aaaaa-aaaca-cai").unwrap();
    if sale.backend_cmc_block.is_none() {
        let b = call_cmc_topup_transfer(ledger, Some(escrow_sub), get_canister_id(), split.backend_amt, fee)
            .await
            .map_err(|e| format!("BACKEND_CMC_XFER: {}", e))?;
        sale.backend_cmc_block = Some(b);
        COURSE_SALES.with(|m| m.borrow_mut().insert(sale.token_id, sale.clone()));
    }
    if let Err(e) = notify_cmc_topup(cmc, get_canister_id(), sale.backend_cmc_block.unwrap(), true).await {
        if e.starts_with("CMC_REFUNDED") {
            sale.backend_cmc_block = None;
            COURSE_SALES.with(|m| m.borrow_mut().insert(sale.token_id, sale.clone()));
        }
        return Err(format!("BACKEND_CMC_NOTIFY: {}", e));
    }

    // Leg 4: frontend cycles 5% via CMC top-up out of escrow.
    if sale.frontend_cmc_block.is_none() {
        let b = call_cmc_topup_transfer(ledger, Some(escrow_sub), frontend_canister_id(), split.frontend_amt, fee)
            .await
            .map_err(|e| format!("FRONTEND_CMC_XFER: {}", e))?;
        sale.frontend_cmc_block = Some(b);
        COURSE_SALES.with(|m| m.borrow_mut().insert(sale.token_id, sale.clone()));
    }
    if let Err(e) = notify_cmc_topup(cmc, frontend_canister_id(), sale.frontend_cmc_block.unwrap(), true).await {
        if e.starts_with("CMC_REFUNDED") {
            sale.frontend_cmc_block = None;
            COURSE_SALES.with(|m| m.borrow_mut().insert(sale.token_id, sale.clone()));
        }
        return Err(format!("FRONTEND_CMC_NOTIFY: {}", e));
    }

    // Leg 5: treasury 5% (escrow → treasury subaccount, in-canister move).
    if sale.treasury_block.is_none() {
        let dest = LedgerAccount { owner: get_canister_id(), subaccount: Some(TREASURY_SUBACCOUNT) };
        let b = call_ledger_transfer(ledger, Some(escrow_sub), dest, split.treasury_amt, Some(fee))
            .await
            .map_err(|e| format!("TREASURY_XFER: {}", e))?;
        sale.treasury_block = Some(b);
        COURSE_SALES.with(|m| m.borrow_mut().insert(sale.token_id, sale.clone()));
    }

    Ok(())
}

/// Refund the escrowed price back to the buyer (only when the NFT transfer
/// failed, A6/C3). 100% funded by the escrow; the treasury fronts ONLY the
/// single refund ledger fee — it never fronts the price. Idempotent on
/// `refund_block`.
async fn refund_escrow_to_buyer(
    sale: &mut CourseSale,
    ledger: Principal,
    escrow_sub: [u8; 32],
) -> Result<(), String> {
    if sale.refund_block.is_some() {
        return Ok(());
    }
    let fee = ICP_FEE_E8S;
    let escrow_acct = LedgerAccount {
        owner: get_canister_id(),
        subaccount: Some(escrow_sub),
    };
    // Treasury fronts only the refund fee (bounded), so the buyer nets the full
    // price back from escrow.
    let balance = call_ledger_balance(ledger, escrow_acct.clone())
        .await
        .map_err(|e| format!("REFUND_BALANCE: {}", e))?;
    if balance < sale.price_e8s + fee {
        let shortfall = (sale.price_e8s + fee) - balance;
        call_ledger_transfer(ledger, Some(TREASURY_SUBACCOUNT), escrow_acct.clone(), shortfall, Some(fee))
            .await
            .map_err(|e| format!("REFUND_FEE_COVER: {}", e))?;
    }
    let dest = LedgerAccount { owner: sale.buyer, subaccount: None };
    let b = call_ledger_transfer(ledger, Some(escrow_sub), dest, sale.price_e8s, Some(fee))
        .await
        .map_err(|e| format!("REFUND_XFER: {}", e))?;
    sale.refund_block = Some(b);
    COURSE_SALES.with(|m| {
        m.borrow_mut().insert(sale.token_id, sale.clone());
    });
    Ok(())
}

// ── Play + anti-cheat (PB-306) ───────────────────────────────────────────────

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct StartSessionOk {
    pub session_id: u64,
    pub server_time: u64,
}
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct RecordHoleOk {
    pub last_hole: u8,
    pub owner_credited: bool,
    pub owner: Option<Principal>,
}
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct CompleteRoundOk {
    pub player_credited: bool,
    pub reason: Option<String>,
}

/// Pure synchronous update — no `raw_rand`, no inter-canister await (PB-306 A2).
#[ic_cdk::update]
fn start_play_session(token_id: u64) -> Result<StartSessionOk, String> {
    // Require the course is minted + listed (delisted courses accrue nothing).
    let listed = COURSE_LISTINGS.with(|m| m.borrow().get(&token_id).map(|l| l.listed));
    match listed {
        Some(true) => {}
        Some(false) => return Err("COURSE_NOT_LISTED".to_string()),
        None => return Err("COURSE_NOT_FOUND".to_string()),
    }
    let caller = get_caller(); // anonymous allowed (play for fun)
    let now = current_time();
    let session_id = NEXT_SESSION_ID.with(|c| {
        let id = *c.borrow().get();
        c.borrow_mut().set(id + 1);
        id
    });
    // Synchronous journal nonce (never raw_rand) — id is the trust anchor.
    let nonce = now ^ session_id.wrapping_mul(0x9E37_79B9_7F4A_7C15);
    let session = PlaySession {
        id: session_id,
        player: caller,
        token_id,
        issued_at: now,
        nonce,
        last_hole: 0,
        last_hole_at: now,
        status: PlaySessionStatus::Active,
        owner_credited_holes: 0,
    };
    PLAY_SESSIONS.with(|m| {
        m.borrow_mut().insert(session_id, session);
    });
    Ok(StartSessionOk {
        session_id,
        server_time: now,
    })
}

fn load_active_session(session_id: u64, caller: Principal, now: u64) -> Result<PlaySession, String> {
    let s = PLAY_SESSIONS
        .with(|m| m.borrow().get(&session_id))
        .ok_or_else(|| "SESSION_NOT_FOUND".to_string())?;
    if s.player != caller {
        return Err("NOT_YOUR_SESSION".to_string());
    }
    if now > s.issued_at + SESSION_TTL_NS {
        return Err("SESSION_EXPIRED".to_string());
    }
    Ok(s)
}

#[ic_cdk::update]
async fn record_hole_event(session_id: u64, hole: u8) -> Result<RecordHoleOk, String> {
    let caller = get_caller();
    let now = current_time();
    let mut s = load_active_session(session_id, caller, now)?;
    if s.status == PlaySessionStatus::Completed {
        return Err("SESSION_COMPLETED".to_string());
    }
    if !(1..=9).contains(&hole) {
        return Err("BAD_HOLE".to_string());
    }
    if hole != s.last_hole + 1 {
        return Err("OUT_OF_ORDER".to_string());
    }
    // Pacing floor: for hole 1, measure from issued_at (== last_hole_at at start).
    if now < s.last_hole_at + MIN_HOLE_INTERVAL_NS {
        return Err("TOO_FAST".to_string());
    }
    s.last_hole = hole;
    s.last_hole_at = now;

    let mut owner_credited = false;
    let mut credited_owner: Option<Principal> = None;

    if hole == 2 {
        // Resolve the LIVE owner right now (V7). A failed lookup skips the
        // credit but still advances the hole (round shouldn't die).
        if let Ok(Some(owner)) = course_nft_owner_of(s.token_id).await {
            credited_owner = Some(owner);
            // Self-play suppression (V5): owner playing own course earns nothing.
            if owner != caller && try_credit_owner_ticket(owner, caller, s.token_id, now) {
                owner_credited = true;
                s.owner_credited_holes = 1;
                // Best-effort NFT counter bump (only on a successful owner credit).
                course_nft_increment_play(s.token_id).await;
                // Mirror the counters into the listing cache.
                COURSE_LISTINGS.with(|m| {
                    let mut map = m.borrow_mut();
                    if let Some(mut row) = map.get(&s.token_id) {
                        row.play_count = row.play_count.saturating_add(1);
                        row.tickets_distributed = row.tickets_distributed.saturating_add(1);
                        map.insert(s.token_id, row);
                    }
                });
            }
        }
    }

    PLAY_SESSIONS.with(|m| {
        m.borrow_mut().insert(session_id, s.clone());
    });

    Ok(RecordHoleOk {
        last_hole: s.last_hole,
        owner_credited,
        owner: credited_owner,
    })
}

#[ic_cdk::update]
fn complete_round(session_id: u64) -> Result<CompleteRoundOk, String> {
    let caller = get_caller();
    let now = current_time();
    let mut s = load_active_session(session_id, caller, now)?;
    if s.status == PlaySessionStatus::Completed {
        return Err("ALREADY_COMPLETED".to_string());
    }
    if s.last_hole != 9 {
        return Err("INCOMPLETE_ROUND".to_string());
    }
    s.status = PlaySessionStatus::Completed;
    PLAY_SESSIONS.with(|m| {
        m.borrow_mut().insert(session_id, s.clone());
    });

    // Player ticket: STAKERS only (owner decision 2026-07-04 — replaces the
    // old Tier-2/follow gate), per-player daily cap, admin-excluded.
    let (player_credited, reason) = if caller == Principal::anonymous() {
        (false, Some("ANON".to_string()))
    } else if !author_is_staked(caller) {
        (false, Some("NOT_STAKED".to_string()))
    } else if is_admin_principal(caller) {
        (false, Some("ADMIN_EXCLUDED".to_string()))
    } else if !try_increment_player_cap(caller, now) {
        (false, Some("DAILY_CAP".to_string()))
    } else {
        credit_course_ticket(caller, "course_play");
        (true, None)
    };

    Ok(CompleteRoundOk {
        player_credited,
        reason,
    })
}

fn epoch_day(now: u64) -> u32 {
    (now / 1_000_000_000 / SECS_PER_DAY) as u32
}

/// Attempt an owner-ticket credit, enforcing the per-owner and per-(player,
/// course) daily caps and admin-exclusion. Returns true iff a ticket was
/// credited. Cap/admin rejection is silent (the play still succeeds).
fn try_credit_owner_ticket(owner: Principal, player: Principal, token_id: u64, now: u64) -> bool {
    if is_admin_principal(owner) {
        return false;
    }
    // Only staked owners earn tickets from their courses (owner decision
    // 2026-07-04) — buying an NFT without an active stake earns nothing.
    if !author_is_staked(owner) {
        return false;
    }
    let day = epoch_day(now);
    // Per-(player, course, day) anti-concentration cap.
    let pair_key = PairCapKey {
        player,
        token_id,
        day,
    };
    let pair_count = COURSE_PAIR_CAPS.with(|m| m.borrow().get(&pair_key).unwrap_or(0));
    if pair_count >= MAX_PER_COURSE_PER_PLAYER_PER_DAY {
        return false;
    }
    // Per-owner owner-ticket cap.
    let owner_key = DayCapKey { who: owner, day };
    let mut owner_entry =
        COURSE_TICKET_CAPS.with(|m| m.borrow().get(&owner_key).unwrap_or_default());
    if owner_entry.owner_tickets >= MAX_OWNER_TICKETS_PER_DAY {
        return false;
    }
    // Both caps pass — credit and bump counters.
    credit_course_ticket(owner, "course_owner");
    owner_entry.owner_tickets = owner_entry.owner_tickets.saturating_add(1);
    COURSE_TICKET_CAPS.with(|m| {
        m.borrow_mut().insert(owner_key, owner_entry);
    });
    COURSE_PAIR_CAPS.with(|m| {
        m.borrow_mut().insert(pair_key, pair_count + 1);
    });
    true
}

/// Reserve one player-ticket slot in today's cap. Returns false (cap hit) if
/// already at the ceiling — the caller must NOT credit in that case.
fn try_increment_player_cap(player: Principal, now: u64) -> bool {
    let day = epoch_day(now);
    let key = DayCapKey { who: player, day };
    let mut entry = COURSE_TICKET_CAPS.with(|m| m.borrow().get(&key).unwrap_or_default());
    if entry.player_tickets >= MAX_PLAYER_TICKETS_PER_DAY {
        return false;
    }
    entry.player_tickets = entry.player_tickets.saturating_add(1);
    COURSE_TICKET_CAPS.with(|m| {
        m.borrow_mut().insert(key, entry);
    });
    true
}

/// Credit 1 ticket to `recipient` in the CURRENT lottery round (models
/// `dev_grant_lottery_tickets`). Admin-excluded and NON-STAKED recipients are
/// silently skipped (only stakers earn lottery tickets — owner decision
/// 2026-07-04; mirrors the grant_lottery_tickets gate).
fn credit_course_ticket(recipient: Principal, source: &str) {
    if is_admin_principal(recipient) {
        return;
    }
    if !author_is_staked(recipient) {
        return;
    }
    let now = current_time();
    let mut state = lottery_state();
    let mut entry = LOTTERY_TICKETS
        .with(|m| m.borrow().get(&recipient))
        .unwrap_or(TicketEntry {
            round: state.round,
            count: 0,
            last_claim_day: 0,
        });
    if entry.round != state.round {
        entry = TicketEntry {
            round: state.round,
            count: 0,
            last_claim_day: entry.last_claim_day,
        };
    }
    entry.count = entry.count.saturating_add(1);
    state.total_tickets = state.total_tickets.saturating_add(1);
    if state.next_draw_at == 0 {
        state.next_draw_at = next_draw_after(now);
    }
    LOTTERY_TICKETS.with(|m| {
        m.borrow_mut().insert(recipient, entry);
    });
    note_ticket_source(recipient, source, 1, state.round);
    set_lottery_state(state);
}

/// The 3 built-in mock courses. Each blob is a build-instructions JSON
/// document (ASCII hole layouts + par + windmills) stored verbatim in the
/// NFT's `course_data`; the app compiles it into 9 playable holes at load
/// time. Also the format an AI course builder authors for user-commissioned
/// courses. Kept in sync with the frontend compiler
/// (`src/frontend/src/arcade/courseInstructions.ts`) — its vitest suite
/// validates these exact files (grid shape, tee→cup reachability).
const MOCK_COURSE_BLOBS: [&str; 3] = [
    include_str!("courses/ember-fields.json"),
    include_str!("courses/rolling-meadows.json"),
    include_str!("courses/volcano-run.json"),
];

/// Course display name straight from the instructions JSON.
fn decode_course_name(bytes: &[u8]) -> Option<String> {
    let v: serde_json::Value = serde_json::from_slice(bytes).ok()?;
    v.get("name").and_then(|n| n.as_str()).map(|s| s.to_string())
}

/// The blob for the genesis default course (PB-309 A3/B3): the first mock
/// course, a full playable 9-hole instructions document.
fn system_course_blob() -> Result<Vec<u8>, String> {
    Ok(MOCK_COURSE_BLOBS[0].as_bytes().to_vec())
}

/// Genesis default course (PB-309 A7/B3). Minted exactly ONCE to the admin
/// principal as a NORMAL ICRC-7 course NFT, auto-listed and playable, so the
/// marketplace is never empty. Idempotent: guarded by `SYSTEM_COURSE_MINTED`, so
/// re-deploys/upgrades — and the admin SELLING it via the normal sale path —
/// never mint a second copy. No transfer restriction: it's "default" only in
/// that it always exists from genesis. Admin-gated; callable from deploy-local
/// and prod to recover a no-op seed without another upgrade (B6).
#[ic_cdk::update(guard = "require_admin")]
async fn admin_seed_system_course() -> Result<u64, String> {
    seed_system_course_inner().await
}

async fn seed_system_course_inner() -> Result<u64, String> {
    // Idempotency: the flag is the source of truth (survives selling the course,
    // unlike "does the admin own a course"). Already minted → no-op.
    if SYSTEM_COURSE_MINTED.with(|c| *c.borrow().get()) {
        return Err("ALREADY_SEEDED".to_string());
    }
    // Mint to the admin principal (the deploy owner). The lottery excludes admins
    // (overview §6), so owner tickets it earns while admin-held are not credited.
    let owner = CONFIG
        .with(|c| c.borrow().get().admins.first().copied())
        .ok_or_else(|| "NO_ADMIN".to_string())?;
    // If the course_nft canister isn't wired yet, no-op + warn (B3) — the upgrade
    // / deploy must not block; re-attempt later via admin_seed_system_course.
    if course_nft_canister_id().is_err() {
        canister_print("seed_system_course: course_nft not configured — skipping (will re-attempt)");
        return Err("COURSE_NFT_NOT_CONFIGURED".to_string());
    }
    let course_data = system_course_blob()?;
    let name = decode_course_name(&course_data).unwrap_or_else(|| "Caldera Classic".to_string());
    let par_total = decode_course_meta(&course_data);
    let token_id = course_nft_mint(CourseMintArgs {
        to: owner,
        name: name.clone(),
        creator: owner,
        course_data: course_data.clone(),
        par_total: par_total as u16,
        mint_fee_e8s: 0, // system mint: fee waived (B3)
    })
    .await?;
    register_course_fps(&course_data, token_id);
    COURSE_LISTINGS.with(|m| {
        m.borrow_mut().insert(
            token_id,
            CourseListing {
                token_id,
                listed: true, // auto-listed + playable
                price_e8s: 0,
                name,
                owner: Some(owner),
                creator: Some(owner),
                play_count: 0,
                tickets_distributed: 0,
                par_total,
                created_at: current_time(),
                mint_fee_e8s: 0,
                for_sale: false, // admin lists it for sale later via the normal path
                rating_sum: 0,
                rating_count: 0,
                hidden: false,
            },
        );
    });
    // Mark the one-time mint done only after the listing exists, so a mid-mint
    // failure resumes cleanly (re-attempt re-mints since the flag isn't set yet).
    SYSTEM_COURSE_MINTED.with(|c| {
        let _ = c.borrow_mut().set(true);
    });
    log_dapp_event("course_system_seed", token_id, owner, 0);
    Ok(token_id)
}

/// TTL/completed-session sweep, bounded per pass (PB-306 A4). Wired into the
/// existing 5-minute timer.
fn sweep_play_sessions() {
    let now = current_time();
    let mut to_remove: Vec<u64> = Vec::new();
    PLAY_SESSIONS.with(|m| {
        for entry in m.borrow().iter() {
            let s = entry.value();
            if s.status == PlaySessionStatus::Completed || now > s.issued_at + SESSION_TTL_NS {
                to_remove.push(s.id);
                if to_remove.len() >= SESSION_SWEEP_BATCH {
                    break;
                }
            }
        }
    });
    PLAY_SESSIONS.with(|m| {
        let mut map = m.borrow_mut();
        for id in to_remove {
            map.remove(&id);
        }
    });
}

// ── Completion predicate (PB-306 read helper, consumed by PB-310) ────────────

/// True if `player` has at least one COMPLETED play session for `token_id`
/// (a full 9-hole round). Reused by the ratings completion gate (PB-310 A2) so
/// the spec consumes a clean predicate rather than reaching into session
/// internals. O(sessions) scan; the session map is swept of completed/expired
/// rows by `sweep_play_sessions`, so it stays small in practice.
fn has_completed_round(player: Principal, token_id: u64) -> bool {
    PLAY_SESSIONS.with(|m| {
        m.borrow().iter().any(|e| {
            let s = e.value();
            s.player == player
                && s.token_id == token_id
                && s.status == PlaySessionStatus::Completed
        })
    })
}

// ════════════════════════════════════════════════════════════════════════════
// 20.A Favorites (PB-311) — private, per-user, point-access. MemoryId 87.
// ════════════════════════════════════════════════════════════════════════════
//
// Convenience metadata only: never touches tickets, listings, ownership, or any
// economics (11-favorite-courses.md). Point-access by the caller's Principal, so
// the default CBOR codec (`impl_storable!`) is correct — NO custom Storable.

const MAX_FAVORITE_COURSES: usize = 200; // per-user cap (overview §5 / B1).

/// Private, per-user favorites list. Point-access ONLY (get/insert/remove by the
/// caller's Principal) — never range-scanned, so the CBOR codec is sufficient.
#[derive(CandidType, Serialize, Deserialize, Clone, Debug, Default)]
pub struct FavoriteList {
    #[serde(default)]
    pub ids: Vec<u64>,
}
impl_storable!(FavoriteList);

thread_local! {
    static FAVORITE_COURSES: RefCell<StableBTreeMap<Principal, FavoriteList, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableBTreeMap::init(mm.borrow().get(MemoryId::new(87)))));
}

/// Shared add path (also reused by the local-dev `dev_grant_favorite`, PB-312):
/// de-duped + capped; returns `true` if newly added, `false` if already present.
fn favorite_add(caller: Principal, token_id: u64) -> Result<bool, String> {
    FAVORITE_COURSES.with(|m| {
        let mut map = m.borrow_mut();
        let mut list = map.get(&caller).unwrap_or_default();
        if list.ids.contains(&token_id) {
            return Ok(false); // already a favorite — no-op add
        }
        if list.ids.len() >= MAX_FAVORITE_COURSES {
            return Err("FAVORITES_FULL".to_string());
        }
        list.ids.push(token_id);
        map.insert(caller, list);
        Ok(true)
    })
}

/// Toggle a course in the caller's favorites. Returns the NEW state
/// (`Ok(true)` = now favorited, `Ok(false)` = now removed) so the frontend can
/// reconcile its optimistic flip without a follow-up read (PB-311 B2).
#[ic_cdk::update(guard = "require_authenticated")]
fn toggle_favorite_course(token_id: u64) -> Result<bool, String> {
    require_arcade_game_enabled(ARCADE_GAME_MINIGOLF)?;
    let caller = get_caller();
    // Cannot favorite a course that was never minted/listed.
    let exists = COURSE_LISTINGS.with(|m| m.borrow().contains_key(&token_id));
    if !exists {
        return Err("COURSE_NOT_FOUND".to_string());
    }
    FAVORITE_COURSES.with(|m| {
        let mut map = m.borrow_mut();
        let mut list = map.get(&caller).unwrap_or_default();
        if let Some(pos) = list.ids.iter().position(|&id| id == token_id) {
            list.ids.remove(pos);
            if list.ids.is_empty() {
                map.remove(&caller); // keep the map tidy (B1)
            } else {
                map.insert(caller, list);
            }
            Ok(false)
        } else {
            if list.ids.len() >= MAX_FAVORITE_COURSES {
                return Err("FAVORITES_FULL".to_string());
            }
            list.ids.push(token_id);
            map.insert(caller, list);
            Ok(true)
        }
    })
}

#[ic_cdk::query]
fn is_favorite(token_id: u64) -> bool {
    let caller = get_caller();
    if caller == Principal::anonymous() {
        return false;
    }
    FAVORITE_COURSES
        .with(|m| m.borrow().get(&caller).map(|l| l.ids.contains(&token_id)))
        .unwrap_or(false)
}

#[ic_cdk::query]
fn my_favorite_ids() -> Vec<u64> {
    let caller = get_caller();
    if caller == Principal::anonymous() {
        return vec![];
    }
    FAVORITE_COURSES.with(|m| m.borrow().get(&caller).map(|l| l.ids).unwrap_or_default())
}

#[ic_cdk::query]
fn list_my_favorite_courses() -> Vec<CourseCard> {
    let caller = get_caller();
    if caller == Principal::anonymous() {
        return vec![];
    }
    let ids = FAVORITE_COURSES
        .with(|m| m.borrow().get(&caller).map(|l| l.ids))
        .unwrap_or_default();
    COURSE_LISTINGS.with(|m| {
        let map = m.borrow();
        ids.iter()
            .filter_map(|id| map.get(id)) // skip burned/missing tokens (B4)
            .map(|l| listing_to_card(&l, caller))
            .collect()
    })
}

// ════════════════════════════════════════════════════════════════════════════
// 20.B Ratings & reviews (PB-310, Phase 3). MemoryId 81.
// ════════════════════════════════════════════════════════════════════════════
//
// One rating per (user, course): 1–5 stars + optional ≤280-char text. Gated on a
// completed 9-hole round (PB-306) + Tier 2+; no self-rating by creator/owner.
// Running aggregate (rating_sum/rating_count) cached on the listing for cheap
// card reads. C2: RatingKey uses a hand-rolled fixed-width big-endian Storable
// (token_id first, then principal) so `range(token_id..)` lists exactly one
// course's reviews — a CBOR key would sort by principal first and bleed.

const MAX_RATING_TEXT_CHARS: usize = MAX_DAPP_DESC_LEN; // 280
const MAX_REVIEW_PAGE: u64 = 50;

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct RatingKey {
    pub token_id: u64,
    pub rater: Principal,
}

impl Storable for RatingKey {
    fn to_bytes(&self) -> Cow<'_, [u8]> {
        let p = self.rater.as_slice(); // <= 29 bytes
        let mut b = Vec::with_capacity(38);
        b.extend_from_slice(&self.token_id.to_be_bytes()); // [0..8] token_id sorts first
        b.push(p.len() as u8); // [8] principal length
        b.extend_from_slice(p); // [9..] principal bytes
        b.resize(38, 0);
        Cow::Owned(b)
    }
    fn into_bytes(self) -> Vec<u8> {
        self.to_bytes().into_owned()
    }
    fn from_bytes(bytes: Cow<[u8]>) -> Self {
        let token_id = u64::from_be_bytes(bytes[0..8].try_into().unwrap());
        let len = bytes[8] as usize;
        let rater = Principal::from_slice(&bytes[9..9 + len]);
        Self { token_id, rater }
    }
    const BOUND: Bound = Bound::Bounded { max_size: 38, is_fixed_size: true };
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct Rating {
    pub token_id: u64,
    pub rater: Principal,
    pub stars: u8, // 1..=5
    pub text: Option<String>,
    pub created_at: u64,
    pub updated_at: u64,
}
impl_storable!(Rating);

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct CourseRatingSummary {
    pub token_id: u64,
    pub rating_sum: u64,
    pub count: u32,
    pub avg_x10: u32, // avg*10, integer convenience (O2: no floats on the wire)
    pub my_stars: Option<u8>,
}

thread_local! {
    static COURSE_RATINGS: RefCell<StableBTreeMap<RatingKey, Rating, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableBTreeMap::init(mm.borrow().get(MemoryId::new(81)))));
}

#[ic_cdk::update(guard = "require_authenticated")]
async fn rate_course(token_id: u64, stars: u8, text: Option<String>) -> Result<(), String> {
    require_arcade_game_enabled(ARCADE_GAME_MINIGOLF)?;
    let rater = get_caller();
    if course_caller_tier(rater) < 2 {
        return Err("TIER_TOO_LOW".to_string());
    }
    if !(1..=5).contains(&stars) {
        return Err("BAD_STARS".to_string());
    }
    let text = match text {
        Some(t) => {
            let t = t.trim();
            if t.is_empty() {
                None
            } else if t.chars().count() > MAX_RATING_TEXT_CHARS {
                return Err("TEXT_TOO_LONG".to_string());
            } else {
                Some(t.to_string())
            }
        }
        None => None,
    };

    let listing = COURSE_LISTINGS
        .with(|m| m.borrow().get(&token_id))
        .ok_or_else(|| "NO_COURSE".to_string())?;
    // No self-rating: immutable creator OR the live owner.
    if Some(rater) == listing.creator {
        return Err("CANNOT_RATE_OWN_COURSE".to_string());
    }
    let owner = course_nft_owner_of(token_id).await?;
    if owner == Some(rater) {
        return Err("CANNOT_RATE_OWN_COURSE".to_string());
    }
    // Completion gate (PB-306 A2).
    if !has_completed_round(rater, token_id) {
        return Err("MUST_COMPLETE_ROUND".to_string());
    }

    let key = RatingKey { token_id, rater };
    let now = current_time();
    let existing = COURSE_RATINGS.with(|m| m.borrow().get(&key));
    let (created_at, old_stars) = match &existing {
        Some(r) => (r.created_at, Some(r.stars)),
        None => (now, None),
    };
    COURSE_RATINGS.with(|m| {
        m.borrow_mut().insert(
            key,
            Rating {
                token_id,
                rater,
                stars,
                text,
                created_at,
                updated_at: now,
            },
        );
    });
    // Maintain the running aggregate on the listing (B2).
    COURSE_LISTINGS.with(|m| {
        let mut map = m.borrow_mut();
        if let Some(mut row) = map.get(&token_id) {
            match old_stars {
                Some(old) => {
                    row.rating_sum = row.rating_sum + stars as u64 - old as u64;
                }
                None => {
                    row.rating_sum = row.rating_sum.saturating_add(stars as u64);
                    row.rating_count = row.rating_count.saturating_add(1);
                }
            }
            map.insert(token_id, row);
        }
    });
    Ok(())
}

#[ic_cdk::query]
fn get_course_rating_summary(token_id: u64) -> CourseRatingSummary {
    let caller = get_caller();
    let (rating_sum, count) = COURSE_LISTINGS
        .with(|m| m.borrow().get(&token_id).map(|l| (l.rating_sum, l.rating_count)))
        .unwrap_or((0, 0));
    let avg_x10 = if count > 0 {
        u32::try_from(rating_sum * 10 / count as u64).unwrap_or(50)
    } else {
        0
    };
    let my_stars = if caller == Principal::anonymous() {
        None
    } else {
        COURSE_RATINGS.with(|m| m.borrow().get(&RatingKey { token_id, rater: caller }).map(|r| r.stars))
    };
    CourseRatingSummary {
        token_id,
        rating_sum,
        count,
        avg_x10,
        my_stars,
    }
}

#[ic_cdk::query]
fn list_course_reviews(token_id: u64, offset: u64, limit: u64) -> Vec<Rating> {
    let limit = limit.min(MAX_REVIEW_PAGE);
    if limit == 0 {
        return vec![];
    }
    // Range over exactly this course's rows (C2 key sorts token_id-first).
    let lo = RatingKey { token_id, rater: Principal::from_slice(&[]) };
    let hi = RatingKey { token_id: token_id.saturating_add(1), rater: Principal::from_slice(&[]) };
    let mut rows: Vec<Rating> = COURSE_RATINGS.with(|m| {
        m.borrow()
            .range(lo..hi)
            .map(|e| e.value())
            .filter(|r| r.token_id == token_id)
            .collect()
    });
    // Most-recent-first.
    rows.sort_by(|a, b| b.updated_at.cmp(&a.updated_at));
    rows.into_iter().skip(offset as usize).take(limit as usize).collect()
}

#[ic_cdk::update(guard = "require_admin")]
fn admin_remove_rating(token_id: u64, rater: Principal) -> Result<(), String> {
    let key = RatingKey { token_id, rater };
    let removed = COURSE_RATINGS.with(|m| m.borrow_mut().remove(&key));
    if let Some(r) = removed {
        COURSE_LISTINGS.with(|m| {
            let mut map = m.borrow_mut();
            if let Some(mut row) = map.get(&token_id) {
                row.rating_sum = row.rating_sum.saturating_sub(r.stars as u64);
                row.rating_count = row.rating_count.saturating_sub(1);
                map.insert(token_id, row);
            }
        });
        Ok(())
    } else {
        Err("NO_RATING".to_string())
    }
}

// ════════════════════════════════════════════════════════════════════════════
// 20.D Local-dev visualisation helpers (require_local_dev) — PB-312.
// ════════════════════════════════════════════════════════════════════════════
//
// No production behaviour: every endpoint is `require_authenticated` +
// `require_local_dev` (which also refuses a mainnet-ledger-wired config), and
// reuses real code paths so visualised state matches production. The only thing
// skipped is the money (burns/approves/bids). NOT gated on the arcade flag (you
// seed state before flipping it).

/// Deterministic, reproducible mock principal for seeded owners/buyers. Never an
/// admin, never the caller. (29-byte body keeps it a valid opaque principal.)
fn mock_principal(n: u8) -> Principal {
    Principal::from_slice(&[0xDE, 0xAD, 0xBE, 0xEF, n])
}

/// Local-dev: mint the 3 built-in mock courses (full playable 9-hole
/// build-instructions blobs). Tops up by name, so re-running only mints
/// what's missing. `count` is capped at the 3 available mock courses.
#[ic_cdk::update]
async fn dev_seed_courses(count: u32) -> Result<u32, String> {
    require_authenticated()?;
    require_local_dev()?;
    let caller = get_caller();
    let now = current_time();
    let mut minted = 0u32;
    for (i, blob) in MOCK_COURSE_BLOBS.iter().enumerate() {
        if minted >= count {
            break;
        }
        let course_data = blob.as_bytes().to_vec();
        let name = decode_course_name(&course_data).unwrap_or_else(|| format!("Mock Course {}", i + 1));
        let already = COURSE_LISTINGS
            .with(|m| m.borrow().iter().any(|e| e.value().name == name));
        if already {
            continue; // top-up: this mock course is already on the marketplace
        }
        let par_total = decode_course_meta(&course_data);
        // Vary owner/price/plays so every card state is visible: #1 owned by the
        // caller (Manage/Burn), #2 caller-owned + for sale, #3 someone else's +
        // for sale (Buy).
        let to = if i == 2 { mock_principal(1) } else { caller };
        let for_sale = i > 0;
        let price_e8s = if for_sale {
            MIN_SALE_PRICE_E8S + (i as u64) * 150_000_000
        } else {
            0
        };
        let token_id = course_nft_mint(CourseMintArgs {
            to,
            name: name.clone(),
            creator: caller, // creator = caller so owner-vs-creator lines are visible
            course_data: course_data.clone(),
            par_total: par_total as u16,
            mint_fee_e8s: MINT_FEE_E8S,
        })
        .await?;
        register_course_fps(&course_data, token_id);
        let play_count = (i as u64) * 41;
        if play_count > 0 {
            course_nft_increment_play(token_id).await; // cosmetic provenance bump
        }
        COURSE_LISTINGS.with(|m| {
            m.borrow_mut().insert(
                token_id,
                CourseListing {
                    token_id,
                    listed: true,
                    price_e8s,
                    name,
                    owner: Some(to),
                    creator: Some(caller),
                    play_count,
                    tickets_distributed: play_count / 2,
                    par_total,
                    created_at: now,
                    mint_fee_e8s: MINT_FEE_E8S,
                    for_sale,
                    rating_sum: 0,
                    rating_count: 0,
                    hidden: false,
                },
            );
        });
        minted += 1;
    }
    Ok(minted)
}

/// Local-dev: force a course's for-sale state (same fields list/delist set).
#[ic_cdk::update]
fn dev_set_course_sale(token_id: u64, price_e8s: Option<u64>) -> Result<(), String> {
    require_authenticated()?;
    require_local_dev()?;
    COURSE_LISTINGS.with(|m| {
        let mut map = m.borrow_mut();
        let mut row = map.get(&token_id).ok_or_else(|| "NO_COURSE".to_string())?;
        match price_e8s {
            Some(p) => {
                row.for_sale = true;
                row.price_e8s = p;
            }
            None => {
                row.for_sale = false;
                row.price_e8s = 0;
            }
        }
        map.insert(token_id, row);
        Ok(())
    })
}

async fn dev_simulate_sale_inner(token_id: u64, buyer: Principal) -> Result<(), String> {
    let owner = course_nft_owner_of(token_id)
        .await?
        .ok_or_else(|| "TOKEN_NOT_FOUND".to_string())?;
    course_nft_custodial_transfer(owner, buyer, token_id).await?; // real path
    // Reconcile the cached owner via the real refresh path.
    COURSE_LISTINGS.with(|m| {
        let mut map = m.borrow_mut();
        if let Some(mut row) = map.get(&token_id) {
            row.owner = Some(buyer);
            map.insert(token_id, row);
        }
    });
    Ok(())
}

/// Local-dev: move a token to a mock/other owner (visualise "owned by someone").
#[ic_cdk::update]
async fn dev_simulate_sale(token_id: u64, buyer: Principal) -> Result<(), String> {
    require_authenticated()?;
    require_local_dev()?;
    dev_simulate_sale_inner(token_id, buyer).await
}

/// Local-dev: give the token to the caller (visualise "owned by me").
#[ic_cdk::update]
async fn dev_give_course(token_id: u64) -> Result<(), String> {
    require_authenticated()?;
    require_local_dev()?;
    let me = get_caller();
    dev_simulate_sale_inner(token_id, me).await
}

/// Local-dev: set a course's play_count (and cosmetic tickets_distributed).
#[ic_cdk::update]
async fn dev_set_play_count(token_id: u64, n: u64) -> Result<(), String> {
    require_authenticated()?;
    require_local_dev()?;
    let current = COURSE_LISTINGS
        .with(|m| m.borrow().get(&token_id).map(|l| l.play_count))
        .ok_or_else(|| "NO_COURSE".to_string())?;
    let delta = n.saturating_sub(current);
    for _ in 0..delta.min(1_000) {
        course_nft_increment_play(token_id).await; // authoritative count bump
    }
    COURSE_LISTINGS.with(|m| {
        let mut map = m.borrow_mut();
        if let Some(mut row) = map.get(&token_id) {
            row.play_count = n;
            row.tickets_distributed = n / 2;
            map.insert(token_id, row);
        }
    });
    Ok(())
}

/// Local-dev: add a course to the caller's favourites (real add path; capped/dedup).
#[ic_cdk::update]
fn dev_grant_favorite(token_id: u64) -> Result<(), String> {
    require_authenticated()?;
    require_local_dev()?;
    favorite_add(get_caller(), token_id).map(|_| ())
}

/// Local-dev: wipe all course listings, ratings, sales, and favourites
/// referencing removed tokens, so the marketplace shows its empty state.
/// Returns how many listings were removed.
#[ic_cdk::update]
async fn dev_clear_courses() -> Result<u64, String> {
    require_authenticated()?;
    require_local_dev()?;
    let token_ids: Vec<u64> = COURSE_LISTINGS.with(|m| m.borrow().iter().map(|e| *e.key()).collect());
    let removed = token_ids.len() as u64;
    // Clear listings.
    COURSE_LISTINGS.with(|m| {
        let mut map = m.borrow_mut();
        for id in &token_ids {
            map.remove(id);
        }
    });
    // Clear sale journals for removed tokens.
    COURSE_SALES.with(|m| {
        let mut map = m.borrow_mut();
        for id in &token_ids {
            map.remove(id);
        }
    });
    // Clear ratings for removed tokens (range per token).
    for id in &token_ids {
        let lo = RatingKey { token_id: *id, rater: Principal::from_slice(&[]) };
        let hi = RatingKey { token_id: id.saturating_add(1), rater: Principal::from_slice(&[]) };
        let keys: Vec<RatingKey> =
            COURSE_RATINGS.with(|m| m.borrow().range(lo..hi).map(|e| e.key().clone()).collect());
        COURSE_RATINGS.with(|m| {
            let mut map = m.borrow_mut();
            for k in keys {
                map.remove(&k);
            }
        });
    }
    // Drop favourites pointing at removed tokens (keep other ids).
    let removed_set: std::collections::HashSet<u64> = token_ids.iter().copied().collect();
    FAVORITE_COURSES.with(|m| {
        let principals: Vec<Principal> = m.borrow().iter().map(|e| *e.key()).collect();
        let mut map = m.borrow_mut();
        for who in principals {
            if let Some(mut list) = map.get(&who) {
                list.ids.retain(|id| !removed_set.contains(id));
                if list.ids.is_empty() {
                    map.remove(&who);
                } else {
                    map.insert(who, list);
                }
            }
        }
    });
    Ok(removed)
}

// ==========================================
// 21. Cycles Faucet — REMOVED 2026-07-06 (owner). PB-400 treasury-ICP→cycles
// grants; never enabled on mainnet (flag `cycles_faucet` retired). MemoryIds
// used by its registration/usage maps are ORPHANED — never reuse (see §3).
// ==========================================

/// USD (e8s) → ICP (e8s) at the cached XRC rate. Mirrors
/// `expected_icp_for_token`'s maths. Returns 0 if no rate is cached.
/// (Kept when the Cycles Faucet was removed — X-Farm tier pricing uses it.)
fn usd_e8s_to_icp_e8s(usd_e8s: u64) -> u64 {
    let icp_rate = cached_usd_rate_e8s(ExplorerToken::ICP); // USD e8s per 1 ICP
    if icp_rate == 0 {
        return 0;
    }
    u64::try_from(usd_e8s as u128 * 100_000_000u128 / icp_rate as u128).unwrap_or(u64::MAX)
}

// ====================================================================
// X-Farm — autonomous per-user Farmer canisters that burn ICP→cycles to run
// Gemini (Cloud-Run proxy) drafting daily pro-ICP tweets the user posts on X.
// Spec: okf/ideas/x-farm/{README,01,02,03,05}.md. Ship dark behind FLAG_X_FARM
// (default OFF). LOCAL deploys only — mainnet gated per-deploy by the owner.
//
// Reuse (do NOT re-clone — okf/notes/duplication-review-2026-06-19.md): the money path
// is settle_burn_split's CMC leg (call_cmc_topup_transfer + notify_cmc_topup,
// journaled burn_block_index, CMC_REFUNDED→drop block, PB-148 class); the 10%
// treasury leg is call_ledger_transfer to TREASURY_SUBACCOUNT; the escrow
// subaccount is the derive_*_subaccount family; USD→ICP is the cached XRC via
// explorer_usd_rate_e8s / usd_e8s_to_icp_e8s. Net-new: a factory that calls the
// management canister's create_canister/install_code (none exist in the repo
// yet) + a 2nd canister wasm (src/xfarm_farmer/) the factory installs.
// ====================================================================

/// CMC canister id (duplication-review B7 — first canonical definition; the
/// ~10 other call sites still inline the literal and can migrate later).
const CMC_ID: &str = "rkp4c-7iaaa-aaaaa-aaaca-cai";
fn cmc_principal() -> Principal {
    Principal::from_text(CMC_ID).unwrap()
}

// ── Tunables ─────────────────────────────────────────────────────────
const XFARM_MAX_PERSONA: usize = 300;
const XFARM_QUOTE_TTL_NANOS: u64 = 15 * 60 * 1_000_000_000;
// Attached to create_canister: 500B is the creation FEE (deducted on create); the
// remainder is the new Farmer's initial balance, which must cover install_code until
// the 90% CMC top-up funds the 7-day budget. 1.5T → ~1T left after the fee.
const XFARM_CREATION_CYCLES: u128 = 1_500_000_000_000;
const XFARM_DURATION_DAYS: u64 = 7;                   // default/min depletion window (D2)
// Per-day pricing (owner-chosen lifespan): $0.50/day, 7..30 days. Mirrors the
// Explorer per-day model (EXPLORER_PRICE_PER_DAY_USD_E8S). Tier = drafts/day only;
// price is days × per-day (tier no longer affects price).
// Per-day USD price is PER TIER (FarmerTier.price_usd_e8s, USD e8s/day). The full
// 30-day lifespan gets a 10% discount.
const XFARM_30DAY_DISCOUNT_PCT: u128 = 10;
const XFARM_MIN_DAYS: u32 = 7;
const XFARM_MAX_DAYS: u32 = 30;
const XFARM_MAX_TIERS: usize = 10;
const XFARM_MAX_DRAFTS_PER_DAY: u32 = 15;
const XFARM_DRAFT_RETENTION_DAYS: u64 = 30;
const XFARM_SWEEP_BATCH: usize = 25;
const DAY_NS: u64 = 86_400 * 1_000_000_000;

// ── Types ────────────────────────────────────────────────────────────
#[derive(CandidType, Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
pub enum FarmerStatus { Active, Depleted, Disabled, Failed }

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct FarmerTier {
    pub id: u32,
    pub name: String,
    pub drafts_per_day: u32,
    pub duration_days: u32,
    /// USD reference price (D1); XRC-quoted to ICP at payment time.
    pub price_usd_e8s: u64,
    /// D9 premium — tier gets 1 Nano-Banana image/day via the proxy.
    pub includes_image: bool,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct XFarmProxy {
    pub url: String,
    pub bearer: String,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct XFarmConfig {
    pub tiers: Vec<FarmerTier>,
    pub proxy: XFarmProxy,
    pub max_active_farmers: usize,
}

impl Default for XFarmConfig {
    fn default() -> Self {
        XFarmConfig {
            tiers: vec![
                // price_usd_e8s = USD/DAY per tier. Final cost = days × rate, with a 10%
                // discount at the full 30-day lifespan. duration_days field unused
                // (lifespan is per-farmer, 7..30). Image "Harvest" tier removed (proxy
                // serves no images yet — Phase-2). Admin can override via admin_set_xfarm_tiers.
                FarmerTier { id: 1, name: "Sprout".into(),  drafts_per_day: 5,  duration_days: 7, price_usd_e8s: 100_000_000, includes_image: false }, // $1.00/day
                FarmerTier { id: 2, name: "Grow".into(),    drafts_per_day: 10, duration_days: 7, price_usd_e8s: 150_000_000, includes_image: false }, // $1.50/day
                FarmerTier { id: 3, name: "Bloom".into(),   drafts_per_day: 15, duration_days: 7, price_usd_e8s: 200_000_000, includes_image: false }, // $2.00/day
            ],
            proxy: XFarmProxy { url: String::new(), bearer: String::new() },
            max_active_farmers: 0, // 0 = unlimited (no per-user cap; optional global brake only)
        }
    }
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct Farmer {
    pub id: u64,
    pub owner: Principal,
    /// None under the dev-seed mock path; Some for a real per-user canister.
    pub canister_id: Option<Principal>,
    pub tier_id: u32,
    pub persona: String,
    pub created_at: u64,
    /// Display only — the cycle balance is the real 7-day timer (D2).
    pub expected_depleted_at: u64,
    /// ICP e8s directed to cycles (the 90% leg, net of the CMC leg fee). A
    /// record of what was burned; the Farmer's own cycle balance is authoritative.
    pub budget_cycles: u64,
    /// Reported by the Farmer via report_depleted (R9: surfaced in the dashboard).
    pub burned_cycles: u64,
    pub last_generation_at: u64,
    pub last_burn_tick_at: u64,
    pub status: FarmerStatus,
    #[serde(default)]
    pub treasury_block: Option<u64>,
    /// Idempotency for the 90% CMC leg (PB-148 class); reset to None on CMC_REFUNDED.
    #[serde(default)]
    pub burn_block_index: Option<u64>,
    #[serde(default)]
    pub install_done: bool,
    #[serde(default)]
    pub cmc_notified: bool,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct XFarmQuote {
    pub tier_id: u32,
    pub days: u32,         // owner-chosen lifespan (7..30); price = days × $0.50
    pub price_e8s: u64,    // ICP at the cached XRC rate for (days × per-day USD)
    pub fee_e8s: u64,     // 2 × ICP fee (two outbound escrow legs: treasury + CMC)
    pub usd_e8s: u64,      // USD reference total (days × tier USD/day, less any 30-day discount)
    pub rate_usd_e8s: u64, // cached ICP/USD rate used
    pub created_at: u64,
    pub expires_at: u64,
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct XFarmInfo {
    pub enabled: bool,
    pub tiers: Vec<FarmerTier>,
    pub proxy_set: bool,
    pub wasm_uploaded: bool,
    pub max_active_farmers: usize,
    pub active_count: usize,
}

#[derive(CandidType, Deserialize, Clone, Debug)]
pub struct XFarmDraft {
    pub id: u64,
    pub text: String,
    pub created_at: u64,
    pub cited_url: Option<String>,
    pub image_url: Option<String>,
}

/// Init args the factory passes to install_code on the Farmer wasm.
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct FarmerInitArgs {
    pub farmer_id: u64,
    pub owner: Principal,
    /// The backend (factory) canister — the Farmer calls it back to report
    /// depletion so the sweep can reap it. Sole controller of the Farmer.
    pub backend_canister_id: Principal,
    pub tier_id: u32,
    pub persona: String,
    pub drafts_per_day: u32,
    pub duration_days: u32,
    pub budget_cycles: u64,
    pub proxy_url: String,
    pub proxy_bearer: String,
}

// ── Management-canister arg structs (net-new; inline like CanisterIdRecord) ──
#[derive(CandidType, Serialize, Clone)]
struct XFarmCanisterSettings {
    controllers: Option<Vec<Principal>>,
    compute_allocation: Option<u64>,
    memory_allocation: Option<u64>,
    freezing_threshold: Option<u64>,
}
#[derive(CandidType, Serialize)]
struct CreateCanisterArgs {
    settings: Option<XFarmCanisterSettings>,
}
#[derive(CandidType, Deserialize)]
struct CreateCanisterResult {
    canister_id: Principal,
}
#[derive(CandidType, Serialize, Clone, Copy)]
enum XFarmInstallMode { install, reinstall, upgrade }
#[derive(CandidType, Serialize)]
struct InstallCodeArgs {
    mode: XFarmInstallMode,
    canister_id: Principal,
    wasm_module: Vec<u8>,
    arg: Vec<u8>,
}

// ── Stable storage (MemoryIds 54–56; 57/58 held in reserve) ──────────
thread_local! {
    static XFARM_FARMERS: RefCell<StableBTreeMap<u64, Farmer, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableBTreeMap::init(mm.borrow().get(MemoryId::new(54)))));
    static XFARM_NEXT_ID: RefCell<StableCell<u64, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableCell::init(mm.borrow().get(MemoryId::new(55)), 1u64)));
    static XFARM_CONFIG: RefCell<StableCell<XFarmConfig, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableCell::init(mm.borrow().get(MemoryId::new(56)), XFarmConfig::default())));

    // Heap-only (lost on upgrade; admin re-uploads): the Farmer wasm bytes + audit hash.
    static XFARM_WASM: RefCell<Option<Vec<u8>>> = const { RefCell::new(None) };
    static XFARM_WASM_HASH: RefCell<Option<[u8; 32]>> = const { RefCell::new(None) };
    // Heap-only 15-min locked quotes per caller (mirrors EXPLORER_QUOTES but ephemeral).
    static XFARM_QUOTES: RefCell<std::collections::HashMap<Principal, XFarmQuote>> =
        RefCell::new(std::collections::HashMap::new());
    // Heap-only dev-seed drafts so the local UI works with no Farmer canister.
    static XFARM_MOCK_DRAFTS: RefCell<std::collections::HashMap<u64, Vec<XFarmDraft>>> =
        RefCell::new(std::collections::HashMap::new());
}

impl_storable!(Farmer);
impl_storable!(XFarmConfig);

// ── Guards + accessors ───────────────────────────────────────────────
fn require_x_farm_enabled() -> Result<(), String> {
    if !feature_visible(FLAG_X_FARM, get_caller()) {
        return Err("FEATURE_DISABLED".to_string());
    }
    Ok(())
}

fn xfarm_config() -> XFarmConfig {
    XFARM_CONFIG.with(|c| c.borrow().get().clone())
}
fn put_xfarm_config(cfg: XFarmConfig) {
    XFARM_CONFIG.with(|c| c.borrow_mut().set(cfg));
}
fn xfarm_put_farmer(f: &Farmer) {
    XFARM_FARMERS.with(|m| m.borrow_mut().insert(f.id, f.clone()));
}
fn next_farmer_id() -> u64 {
    XFARM_NEXT_ID.with(|c| {
        let v = *c.borrow().get();
        c.borrow_mut().set(v + 1);
        v
    })
}
fn xfarm_farmers_by_owner(owner: &Principal) -> Vec<Farmer> {
    XFARM_FARMERS.with(|m| {
        m.borrow().iter().filter(|e| e.value().owner == *owner).map(|e| e.value().clone()).collect()
    })
}
fn xfarm_active_count() -> usize {
    XFARM_FARMERS.with(|m| {
        m.borrow().iter().filter(|e| e.value().status == FarmerStatus::Active).count()
    })
}
fn derive_xfarm_subaccount(user: &Principal) -> [u8; 32] {
    use sha2::Digest;
    let mut hasher = sha2::Sha256::new();
    hasher.update(b"proof_of_burn_xfarm_v1");
    hasher.update(user.as_slice());
    let result = hasher.finalize();
    let mut sub = [0u8; 32];
    sub.copy_from_slice(&result);
    sub
}

// ── Factory primitives (net-new management-canister calls) ───────────
#[cfg(target_arch = "wasm32")]
async fn xfarm_create_canister(creation_cycles: u128) -> Result<Principal, String> {
    // Factory = sole controller (R5: factory owns the lifecycle of every Farmer).
    let args = CreateCanisterArgs {
        settings: Some(XFarmCanisterSettings {
            controllers: Some(vec![get_canister_id()]),
            compute_allocation: None,
            memory_allocation: None,
            freezing_threshold: Some(0),
        }),
    };
    // Cycles are attached to the CALL (msg payment), not an arg field — the mgmt
    // canister deducts the 500B creation fee from them and credits the rest to the
    // new canister. Passing them in the struct (the old bug) sent 0 → reject.
    let res: Result<(CreateCanisterResult,), _> = ic_cdk::api::call::call_with_payment128(
        Principal::management_canister(), "create_canister", (args,), creation_cycles,
    ).await;
    res.map(|(r,)| r.canister_id)
        .map_err(|(c, m)| format!("CREATE_CANISTER_FAILED ({:?}): {}", c, m))
}
#[cfg(not(target_arch = "wasm32"))]
async fn xfarm_create_canister(_creation_cycles: u128) -> Result<Principal, String> {
    // Host mock: a stable, non-anonymous stand-in principal for unit tests
    // (a self-authenticating id over a fixed pubkey). Real create_canister only
    // runs on wasm; tests use dev_seed_farmer (canister_id None) instead.
    Ok(Principal::self_authenticating(&[1u8; 29]))
}

#[cfg(target_arch = "wasm32")]
async fn xfarm_install_code(canister_id: Principal, wasm: Vec<u8>, arg: Vec<u8>) -> Result<(), String> {
    let args = InstallCodeArgs { mode: XFarmInstallMode::install, canister_id, wasm_module: wasm, arg };
    let res: Result<(), _> = ic_cdk::call(Principal::management_canister(), "install_code", (args,)).await;
    res.map_err(|(c, m)| format!("INSTALL_CODE_FAILED ({:?}): {}", c, m))
}
#[cfg(not(target_arch = "wasm32"))]
async fn xfarm_install_code(_canister_id: Principal, _wasm: Vec<u8>, _arg: Vec<u8>) -> Result<(), String> {
    Ok(())
}

// Upgrade an EXISTING Farmer canister's code (preserves stable state via post_upgrade).
// Used to roll out a Farmer-wasm fix to already-created Farmers. Empty arg: the
// Farmer's post_upgrade takes no args.
#[cfg(target_arch = "wasm32")]
async fn xfarm_upgrade_code(canister_id: Principal, wasm: Vec<u8>) -> Result<(), String> {
    let args = InstallCodeArgs {
        mode: XFarmInstallMode::upgrade, canister_id, wasm_module: wasm,
        arg: candid::encode_args(()).unwrap_or_default(),
    };
    let res: Result<(), _> = ic_cdk::call(Principal::management_canister(), "install_code", (args,)).await;
    res.map_err(|(c, m)| format!("UPGRADE_CODE_FAILED ({:?}): {}", c, m))
}
#[cfg(not(target_arch = "wasm32"))]
async fn xfarm_upgrade_code(_canister_id: Principal, _wasm: Vec<u8>) -> Result<(), String> { Ok(()) }

#[cfg(target_arch = "wasm32")]
async fn xfarm_stop_canister(cid: Principal) -> Result<(), String> {
    ic_cdk::call(Principal::management_canister(), "stop_canister", (CanisterIdRecord { canister_id: cid },))
        .await.map_err(|(c, m)| format!("STOP_FAILED ({:?}): {}", c, m))
}
#[cfg(not(target_arch = "wasm32"))]
async fn xfarm_stop_canister(_cid: Principal) -> Result<(), String> { Ok(()) }

#[cfg(target_arch = "wasm32")]
async fn xfarm_delete_canister(cid: Principal) -> Result<(), String> {
    ic_cdk::call(Principal::management_canister(), "delete_canister", (CanisterIdRecord { canister_id: cid },))
        .await.map_err(|(c, m)| format!("DELETE_FAILED ({:?}): {}", c, m))
}
#[cfg(not(target_arch = "wasm32"))]
async fn xfarm_delete_canister(_cid: Principal) -> Result<(), String> { Ok(()) }

// Tell an EXISTING Farmer canister to bump its cycle budget + duration and re-arm
// the burn timer (called by renew_farmer after the money legs). The Farmer's
// `extend` returns Result<(), String>; the inter-canister call itself may also
// reject, so both layers are unwrapped.
#[cfg(target_arch = "wasm32")]
async fn xfarm_extend_farmer(cid: Principal, add_budget: u64, add_days: u32) -> Result<(), String> {
    let res: Result<(Result<(), String>,), _> = ic_cdk::call(cid, "extend", (add_budget, add_days)).await;
    match res {
        Ok((Ok(()),)) => Ok(()),
        Ok((Err(e),)) => Err(format!("EXTEND_FAILED: {}", e)),
        Err((c, m)) => Err(format!("EXTEND_CALL ({:?}): {}", c, m)),
    }
}
// Host mock: no-op Ok (the Farmer canister only runs on wasm). A test-fail seam
// lets unit tests simulate an extend failure to exercise the renew error path.
#[cfg(not(target_arch = "wasm32"))]
async fn xfarm_extend_farmer(_cid: Principal, _add_budget: u64, _add_days: u32) -> Result<(), String> {
    if let Some(e) = TEST_XFARM_EXTEND_FAIL.with(|cell| cell.borrow().clone()) {
        return Err(e);
    }
    Ok(())
}

// ── Public query/update API ─────────────────────────────────────────

#[ic_cdk::query]
fn get_xfarm_tiers() -> Vec<FarmerTier> {
    xfarm_config().tiers
}

#[ic_cdk::query]
fn get_xfarm_info() -> XFarmInfo {
    let cfg = xfarm_config();
    XFarmInfo {
        enabled: feature_visible(FLAG_X_FARM, get_caller()),
        tiers: cfg.tiers,
        proxy_set: !cfg.proxy.url.is_empty(),
        wasm_uploaded: XFARM_WASM.with(|w| w.borrow().is_some()),
        max_active_farmers: cfg.max_active_farmers,
        active_count: xfarm_active_count(),
    }
}

#[ic_cdk::query]
fn get_xfarm_deposit_address() -> LedgerAccount {
    let caller = get_caller();
    LedgerAccount { owner: get_canister_id(), subaccount: Some(derive_xfarm_subaccount(&caller)) }
}

#[ic_cdk::query]
fn list_my_farmers() -> Vec<Farmer> {
    xfarm_farmers_by_owner(&get_caller())
}

/// USD tier price → ICP at the cached XRC rate; lock the quote for the caller
/// for 15 minutes (mirrors get_explorer_quote). An update (not a query) because
/// the mainnet path may refresh the rate via the XRC.
#[ic_cdk::update]
async fn get_xfarm_quote(tier_id: u32, days: u32) -> Result<XFarmQuote, String> {
    require_authenticated()?;
    require_x_farm_enabled()?;
    let caller = get_caller();
    let cfg = xfarm_config();
    // Tier sets both drafts/day AND the per-day price (price_usd_e8s = USD/day).
    let tier = cfg.tiers.iter().find(|t| t.id == tier_id)
        .ok_or_else(|| "TIER_NOT_FOUND".to_string())?;
    if days < XFARM_MIN_DAYS || days > XFARM_MAX_DAYS { return Err("BAD_DAYS".to_string()); }
    let backend_cfg = CONFIG.with(|c| c.borrow().get().clone());
    let rate = explorer_usd_rate_e8s(ExplorerToken::ICP, &backend_cfg).await?; // USD e8s per 1 ICP
    if rate == 0 { return Err("RATE_UNAVAILABLE".to_string()); }
    // days × per-tier USD/day, with a 10% discount at the full 30-day lifespan.
    let mut usd_total = days as u128 * tier.price_usd_e8s as u128;
    if days >= XFARM_MAX_DAYS {
        usd_total = usd_total * (100 - XFARM_30DAY_DISCOUNT_PCT) / 100;
    }
    let price = u64::try_from(usd_total * 100_000_000u128 / rate as u128)
        .map_err(|_| "PRICE_OVERFLOW".to_string())?;
    if price == 0 { return Err("PRICE_TOO_LOW".to_string()); }
    let now = current_time();
    let q = XFarmQuote {
        tier_id, days, price_e8s: price, fee_e8s: ICP_FEE_E8S * 2,
        usd_e8s: u64::try_from(usd_total).unwrap_or(u64::MAX), rate_usd_e8s: rate,
        created_at: now, expires_at: now + XFARM_QUOTE_TTL_NANOS,
    };
    XFARM_QUOTES.with(|qq| qq.borrow_mut().insert(caller, q.clone()));
    Ok(q)
}

/// Create a Farmer: escrow → 10% treasury → create+install the Farmer canister →
/// 90% burn-to-cycles funding it (CMC topup, journaled). Reuses settle_burn_split's
/// CMC leg + submit_dapp's escrow ordering. Per R5 the order is create→install→top-up;
/// a partial failure leaves a persisted Farmer the sweep can resume or clean up.
#[ic_cdk::update]
async fn create_farmer(tier_id: u32, persona: String, days: u32) -> Result<Farmer, String> {
    require_authenticated()?;
    require_x_farm_enabled()?;
    let caller = get_caller();
    let _guard = CallerGuard::new(caller)?;

    // Run the whole create flow; on ANY failure auto-refund the escrow deposit so a
    // failed create never strands the owner's ICP (e.g. WASM_NOT_UPLOADED). The
    // frontend deposits BEFORE calling, so the deposit is in escrow on entry. Pre-money
    // failures (the common case) refund in full; a post-treasury failure finds the
    // escrow already drained → refund no-ops, leaving the half-Farmer to the sweep.
    let result: Result<Farmer, String> = async move {
    let cfg = xfarm_config();
    let tier = cfg.tiers.iter().find(|t| t.id == tier_id).cloned()
        .ok_or_else(|| "TIER_NOT_FOUND".to_string())?;
    if days < XFARM_MIN_DAYS || days > XFARM_MAX_DAYS { return Err("BAD_DAYS".to_string()); }
    let persona = persona.trim().to_string();
    if persona.is_empty() || persona.chars().count() > XFARM_MAX_PERSONA {
        return Err(format!("BAD_PERSONA: 1..{} chars", XFARM_MAX_PERSONA));
    }
    // Unlimited Farmers per owner (more farms = more ICP burned, on-theme). The
    // only limiter is an optional global brake: 0 = off / unlimited.
    if cfg.max_active_farmers > 0 && xfarm_active_count() >= cfg.max_active_farmers {
        return Err("MAX_FARMERS_REACHED".to_string());
    }
    // Fail fast: the factory cannot install the Farmer without its wasm uploaded.
    // Checked after the cheap input validations but before any money moves, so a
    // missing upload can't strand a half-created Farmer (escrow paid / canister
    // created / install_done=false) the sweep never reaps and that blocks the
    // owner from retrying with FARMER_EXISTS.
    if XFARM_WASM.with(|w| w.borrow().is_none()) {
        return Err("WASM_NOT_UPLOADED".to_string());
    }

    // Locked quote (price locked 15 min, like EXPLORER_QUOTES).
    let quote = XFARM_QUOTES.with(|q| q.borrow().get(&caller).cloned())
        .ok_or_else(|| "NO_QUOTE".to_string())?;
    if quote.tier_id != tier_id || quote.days != days { return Err("QUOTE_MISMATCH".to_string()); }
    if current_time() > quote.expires_at { return Err("QUOTE_EXPIRED".to_string()); }

    let ledger_id = CONFIG.with(|c| c.borrow().get().ledger_canister_id);
    let fee = ICP_FEE_E8S;
    let sub = derive_xfarm_subaccount(&caller);
    let escrow = LedgerAccount { owner: get_canister_id(), subaccount: Some(sub) };
    let balance = call_ledger_balance(ledger_id, escrow.clone()).await
        .map_err(|e| format!("ESCROW_BALANCE: {}", e))?;
    // Two outbound escrow legs (treasury + CMC) ⇒ escrow must hold price + 2 fees.
    if balance < quote.price_e8s.saturating_add(quote.fee_e8s) {
        return Err("INSUFFICIENT_DEPOSIT".to_string());
    }

    // Allocate + persist the Farmer first so a retry sweep can resume.
    let id = next_farmer_id();
    let now = current_time();
    let treasury_amt = quote.price_e8s / 10; // 10% → treasury
    let burn_amt = quote.price_e8s.saturating_sub(treasury_amt); // 90% → cycles
    let mut farmer = Farmer {
        id, owner: caller, canister_id: None, tier_id, persona: persona.clone(),
        created_at: now,
        expected_depleted_at: now + (days as u64) * DAY_NS,
        budget_cycles: 0, burned_cycles: 0,
        last_generation_at: 0, last_burn_tick_at: 0,
        status: FarmerStatus::Active,
        treasury_block: None, burn_block_index: None, install_done: false, cmc_notified: false,
    };
    xfarm_put_farmer(&farmer);

    // Order: create + install the Farmer canister FIRST (paid from the backend's own
    // cycles), and only AFTER it exists move the owner's ICP. So a create/install
    // failure strands NO user ICP — it just removes the persisted Farmer and returns
    // an error with the deposit untouched in escrow ("ICP not returned" fix + R5).

    // Factory: create the Farmer canister (sole controller = this backend, R5).
    if farmer.canister_id.is_none() {
        let cid = match xfarm_create_canister(XFARM_CREATION_CYCLES).await {
            Ok(cid) => cid,
            Err(e) => { XFARM_FARMERS.with(|m| m.borrow_mut().remove(&id)); return Err(e); }
        };
        farmer.canister_id = Some(cid);
        xfarm_put_farmer(&farmer);
    }
    let farmer_cid = farmer.canister_id.unwrap();

    // Install the Farmer wasm (net-new 2nd canister).
    if !farmer.install_done {
        let wasm = XFARM_WASM.with(|w| w.borrow().clone())
            .ok_or_else(|| "WASM_NOT_UPLOADED".to_string())?;
        let init = FarmerInitArgs {
            farmer_id: id, owner: caller, backend_canister_id: get_canister_id(),
            tier_id, persona: persona.clone(),
            drafts_per_day: tier.drafts_per_day, duration_days: days,
            budget_cycles: burn_amt.saturating_sub(fee), // 90% net of the CMC leg fee
            proxy_url: cfg.proxy.url.clone(), proxy_bearer: cfg.proxy.bearer.clone(),
        };
        let arg = candid::encode_args((init,)).map_err(|e| format!("ENCODE_INIT: {}", e))?;
        // R5: if install fails, delete the orphan canister so it can't accumulate.
        if let Err(e) = xfarm_install_code(farmer_cid, wasm, arg).await {
            let _ = xfarm_delete_canister(farmer_cid).await;
            XFARM_FARMERS.with(|m| m.borrow_mut().remove(&id));
            return Err(e);
        }
        farmer.install_done = true;
        xfarm_put_farmer(&farmer);
    }

    // 10% → treasury (only now that the canister exists; idempotent via treasury_block).
    if farmer.treasury_block.is_none() {
        let treasury_dest = LedgerAccount { owner: get_canister_id(), subaccount: Some(TREASURY_SUBACCOUNT) };
        let b = call_ledger_transfer(ledger_id, Some(sub), treasury_dest, treasury_amt, Some(fee))
            .await.map_err(|e| format!("TREASURY_XFER: {}", e))?;
        farmer.treasury_block = Some(b);
        xfarm_put_farmer(&farmer);
    }

    // 90% → burn to cycles funding the Farmer (CMC topup to the Farmer canister;
    // idempotent via burn_block_index + notify — PB-148 class, mirrors settle_burn_split).
    if farmer.burn_block_index.is_none() {
        let b = call_cmc_topup_transfer(ledger_id, Some(sub), farmer_cid, burn_amt, fee)
            .await.map_err(|e| format!("BACKEND_CMC_XFER: {}", e))?;
        farmer.burn_block_index = Some(b);
        farmer.budget_cycles = burn_amt.saturating_sub(fee);
        xfarm_put_farmer(&farmer);
    }
    if let Err(e) = notify_cmc_topup(cmc_principal(), farmer_cid, farmer.burn_block_index.unwrap(), false).await {
        if e.starts_with("CMC_REFUNDED") {
            farmer.burn_block_index = None; // drop the block so the sweep re-transfers
            xfarm_put_farmer(&farmer);
        }
        return Err(format!("BACKEND_CMC_NOTIFY: {}", e));
    }
    farmer.cmc_notified = true;
    xfarm_put_farmer(&farmer);

    XFARM_QUOTES.with(|q| q.borrow_mut().remove(&caller));
    staking_audit("xfarm_create", caller, quote.price_e8s, id);
    Ok(farmer)
    }.await;

    if result.is_err() {
        if let Ok(amt) = xfarm_refund_escrow(caller).await {
            if amt > 0 {
                canister_print(&format!("xfarm: refunded {} e8s to {} after failed create", amt, caller.to_text()));
            }
        }
    }
    result
}

/// Refund a caller's x-farm escrow deposit (balance − fee) back to their main account.
/// Recovers funds when create_farmer aborts after the frontend has already deposited
/// (it deposits before calling). Returns 0 when there's nothing above the fee.
async fn xfarm_refund_escrow(caller: Principal) -> Result<u64, String> {
    let ledger_id = CONFIG.with(|c| c.borrow().get().ledger_canister_id);
    let fee = ICP_FEE_E8S;
    let sub = derive_xfarm_subaccount(&caller);
    let escrow = LedgerAccount { owner: get_canister_id(), subaccount: Some(sub) };
    let bal = call_ledger_balance(ledger_id, escrow).await
        .map_err(|e| format!("REFUND_BALANCE: {}", e))?;
    if bal <= fee { return Ok(0); }
    let amt = bal - fee;
    let dest = LedgerAccount { owner: caller, subaccount: None };
    call_ledger_transfer(ledger_id, Some(sub), dest, amt, Some(fee)).await
        .map_err(|e| format!("REFUND_XFER: {}", e))?;
    Ok(amt)
}

/// Self-service: refund my own stranded x-farm escrow deposit.
#[ic_cdk::update]
async fn refund_xfarm_escrow() -> Result<u64, String> {
    require_authenticated()?;
    let caller = get_caller();
    let _guard = CallerGuard::new(caller)?;
    xfarm_refund_escrow(caller).await
}

/// Admin recovery: refund a specific user's stranded x-farm escrow deposit.
#[ic_cdk::update(guard = "require_admin")]
async fn admin_refund_xfarm_escrow(user: Principal) -> Result<u64, String> {
    xfarm_refund_escrow(user).await
}

/// RENEW: pay again to extend an existing (Active) Farmer's lifespan. Reuses the
/// create money path — 10% → treasury, 90% → CMC topup to the EXISTING Farmer
/// canister — then calls the Farmer's `extend(add_budget_cycles, add_days)` to bump
/// the budget + duration and re-arm the burn timer. The owner gets a fresh quote for
/// the Farmer's tier first (frontend calls get_xfarm_quote). A depleted/swept Farmer
/// (no canister) can't be renewed → create a new one.
///
/// C2 trapped-fund fix (2026-06-20): the CMC leg now journals `burn_block_index` +
/// clears `cmc_notified` BEFORE the notify call (mirrors `create_farmer`), so a
/// transient notify failure no longer strands the 90% ICP at the CMC — `xfarm_sweep`
/// re-notifies the journaled block and recovers it as cycles. `CMC_REFUNDED` drops
/// the block (the CMC sent the ICP back to the escrow) and the auto-refund wrapper
/// returns it. Like `create_farmer`, ANY failure auto-refunds the escrow: pre-money
/// failures refund the full deposit; post-money failures find the escrow drained →
/// refund no-ops (the CMC leg is journaled, so the sweep recovers those funds).
///
/// NOTE: the money legs here are NOT guarded the way create's are — the Farmer's
/// `treasury_block` / `burn_block_index` / `cmc_notified` fields are reused from
/// create and can't cleanly distinguish "this renew's block" from "create's block"
/// without per-renew struct fields. So a renew always re-runs the treasury + CMC
/// transfers (overwriting the historical create blocks). This matches the pre-fix
/// behavior; the only change is the journaling that lets the sweep recover a notify
/// failure. The retry-after-extend-failure double-charge this implies is a known
/// limitation documented in okf/notes/escrow-fix-review-2026-06-20.md (the proper fix is
/// a per-renew epoch field; deferred — extend failures are rare, the Farmer canister
/// is controller-owned and the call is local).
#[ic_cdk::update]
async fn renew_farmer(farmer_id: u64, days: u32) -> Result<Farmer, String> {
    require_authenticated()?;
    require_x_farm_enabled()?;
    let caller = get_caller();
    let _guard = CallerGuard::new(caller)?;

    let result: Result<Farmer, String> = async move {
    let mut farmer = XFARM_FARMERS.with(|m| m.borrow().get(&farmer_id))
        .ok_or_else(|| "FARMER_NOT_FOUND".to_string())?;
    if farmer.owner != caller { return Err("NOT_OWNER".to_string()); }
    if farmer.status != FarmerStatus::Active { return Err("CANNOT_RENEW".to_string()); }
    if days < XFARM_MIN_DAYS || days > XFARM_MAX_DAYS { return Err("BAD_DAYS".to_string()); }
    let farmer_cid = farmer.canister_id.ok_or_else(|| "NO_CANISTER".to_string())?;

    let cfg = xfarm_config();
    // Tier must still exist (selects drafts/day); price is days-based.
    let _tier = cfg.tiers.iter().find(|t| t.id == farmer.tier_id)
        .ok_or_else(|| "TIER_NOT_FOUND".to_string())?;

    // Fresh locked quote for the Farmer's tier + chosen extension days.
    let quote = XFARM_QUOTES.with(|q| q.borrow().get(&caller).cloned())
        .ok_or_else(|| "NO_QUOTE".to_string())?;
    if quote.tier_id != farmer.tier_id || quote.days != days { return Err("QUOTE_MISMATCH".to_string()); }
    if current_time() > quote.expires_at { return Err("QUOTE_EXPIRED".to_string()); }

    let ledger_id = CONFIG.with(|c| c.borrow().get().ledger_canister_id);
    let fee = ICP_FEE_E8S;
    let sub = derive_xfarm_subaccount(&caller);
    let escrow = LedgerAccount { owner: get_canister_id(), subaccount: Some(sub) };
    let balance = call_ledger_balance(ledger_id, escrow.clone()).await
        .map_err(|e| format!("ESCROW_BALANCE: {}", e))?;
    if balance < quote.price_e8s.saturating_add(quote.fee_e8s) {
        return Err("INSUFFICIENT_DEPOSIT".to_string());
    }

    let treasury_amt = quote.price_e8s / 10;            // 10% → treasury
    let burn_amt = quote.price_e8s.saturating_sub(treasury_amt); // 90% → cycles
    let add_budget = burn_amt.saturating_sub(fee);

    // 10% → treasury (overwrites the historical create block — see NOTE above).
    let treasury_dest = LedgerAccount { owner: get_canister_id(), subaccount: Some(TREASURY_SUBACCOUNT) };
    let tb = call_ledger_transfer(ledger_id, Some(sub), treasury_dest, treasury_amt, Some(fee))
        .await.map_err(|e| format!("TREASURY_XFER: {}", e))?;
    farmer.treasury_block = Some(tb);
    xfarm_put_farmer(&farmer);

    // 90% → CMC topup to the EXISTING Farmer canister. Journal the block + clear
    // cmc_notified BEFORE notify (the C2 fix) so a notify failure is recoverable by
    // `xfarm_sweep` (which re-notifies any Active farmer with a block + !cmc_notified).
    let block = call_cmc_topup_transfer(ledger_id, Some(sub), farmer_cid, burn_amt, fee)
        .await.map_err(|e| format!("RENEW_CMC_XFER: {}", e))?;
    farmer.burn_block_index = Some(block);
    farmer.cmc_notified = false;
    xfarm_put_farmer(&farmer);
    if let Err(e) = notify_cmc_topup(cmc_principal(), farmer_cid, block, false).await {
        if e.starts_with("CMC_REFUNDED") {
            // The CMC refused the block and sent the ICP back to the escrow subaccount;
            // drop the block so the sweep doesn't re-notify a refunded one, and let the
            // auto-refund wrapper below return it to the owner.
            farmer.burn_block_index = None;
            xfarm_put_farmer(&farmer);
        }
        return Err(format!("RENEW_CMC_NOTIFY: {}", e));
    }
    farmer.cmc_notified = true;
    xfarm_put_farmer(&farmer);

    // Tell the Farmer to extend its budget + duration + re-arm the burn timer.
    xfarm_extend_farmer(farmer_cid, add_budget, days).await?;

    farmer.budget_cycles = farmer.budget_cycles.saturating_add(add_budget);
    farmer.expected_depleted_at = farmer.expected_depleted_at
        .saturating_add((days as u64) * DAY_NS);
    farmer.status = FarmerStatus::Active;
    xfarm_put_farmer(&farmer);

    XFARM_QUOTES.with(|q| q.borrow_mut().remove(&caller));
    staking_audit("xfarm_renew", caller, quote.price_e8s, farmer_id);
    Ok(farmer)
    }.await;

    // On ANY failure auto-refund whatever's left in the escrow (mirrors create_farmer).
    // Pre-treasury failures refund the full deposit; post-treasury/post-CMC failures
    // find the escrow drained → refund no-ops (the CMC leg is journaled, so the sweep
    // recovers those funds as cycles rather than stranding them at the CMC).
    if result.is_err() {
        if let Ok(amt) = xfarm_refund_escrow(caller).await {
            if amt > 0 {
                canister_print(&format!(
                    "xfarm: refunded {} e8s to {} after failed renew", amt, caller.to_text()));
            }
        }
    }
    result
}

/// Called by a Farmer canister when its cycle balance hits the stop-floor (D2).
/// Only the Farmer's own canister may report. Sets Depleted so the sweep reaps it.
#[ic_cdk::update]
fn report_depleted(farmer_id: u64, burned_cycles: u64) -> Result<(), String> {
    let caller = get_caller();
    let farmer = XFARM_FARMERS.with(|m| m.borrow().get(&farmer_id))
        .ok_or_else(|| "FARMER_NOT_FOUND".to_string())?;
    if farmer.canister_id != Some(caller) {
        return Err("NOT_FARMER_CANISTER".to_string());
    }
    XFARM_FARMERS.with(|m| {
        let mut map = m.borrow_mut();
        if let Some(mut f) = map.get(&farmer_id) {
            f.burned_cycles = burned_cycles;
            f.status = FarmerStatus::Depleted;
            map.insert(farmer_id, f);
        }
    });
    Ok(())
}

/// On-demand generation: the owner viewing a Farmer triggers (throttled to max
/// 1/day inside the Farmer) a fresh generation, then returns its retained drafts.
/// Dev-seed Farmers (no canister) just return the seeded mock drafts so the UI works.
#[ic_cdk::update]
async fn get_farmer_drafts(farmer_id: u64, since: u64) -> Result<Vec<XFarmDraft>, String> {
    require_authenticated()?;
    let caller = get_caller();
    let farmer = XFARM_FARMERS.with(|m| m.borrow().get(&farmer_id))
        .ok_or_else(|| "FARMER_NOT_FOUND".to_string())?;
    if farmer.owner != caller { return Err("NOT_OWNER".to_string()); }
    match farmer.canister_id {
        None => Ok(XFARM_MOCK_DRAFTS.with(|d| d.borrow().get(&farmer.id).cloned()).unwrap_or_default()
            .into_iter().filter(|x| x.created_at >= since).collect()),
        Some(cid) => {
            // request_generation triggers the throttled (1/day) on-demand outcall in
            // the Farmer and returns its retained drafts (Result<vec Draft, text>).
            let res: Result<(Result<Vec<XFarmDraft>, String>,), _> =
                ic_cdk::call(cid, "request_generation", (farmer_id,)).await;
            match res {
                Ok((Ok(drafts),)) => Ok(drafts.into_iter().filter(|x| x.created_at >= since).collect()),
                Ok((Err(e),)) => Err(format!("GENERATION_FAILED: {}", e)),
                Err((c, m)) => Err(format!("DRAFTS_FAILED ({:?}): {}", c, m)),
            }
        }
    }
}

/// Read-only companion to `get_farmer_drafts`: returns the Farmer's currently
/// STORED drafts WITHOUT triggering generation (no Gemini outcall, no throttle
/// consumed). The UI calls this first to paint cached drafts instantly, then calls
/// `get_farmer_drafts` in the background to (maybe) refresh — so a slow or failed
/// generation never blanks the list the owner already has.
#[ic_cdk::update]
async fn get_farmer_drafts_cached(farmer_id: u64, since: u64) -> Result<Vec<XFarmDraft>, String> {
    require_authenticated()?;
    let caller = get_caller();
    let farmer = XFARM_FARMERS.with(|m| m.borrow().get(&farmer_id))
        .ok_or_else(|| "FARMER_NOT_FOUND".to_string())?;
    if farmer.owner != caller { return Err("NOT_OWNER".to_string()); }
    match farmer.canister_id {
        None => Ok(XFARM_MOCK_DRAFTS.with(|d| d.borrow().get(&farmer.id).cloned()).unwrap_or_default()
            .into_iter().filter(|x| x.created_at >= since).collect()),
        Some(cid) => {
            // get_drafts(since) is a pure read on the Farmer — no outcall, no throttle.
            let res: Result<(Result<Vec<XFarmDraft>, String>,), _> =
                ic_cdk::call(cid, "get_drafts", (since,)).await;
            match res {
                Ok((Ok(drafts),)) => Ok(drafts),
                Ok((Err(e),)) => Err(format!("DRAFTS_REJECTED: {}", e)),
                Err((c, m)) => Err(format!("DRAFTS_FAILED ({:?}): {}", c, m)),
            }
        }
    }
}

/// The owner's live Farmer status: cycles remaining, days of budget left, next
/// generation. Proxies to the Farmer canister for the live cycle balance.
#[ic_cdk::update]
async fn get_farmer_status(farmer_id: u64) -> Result<(Farmer, u64, u64), String> {
    require_authenticated()?;
    let caller = get_caller();
    let farmer = XFARM_FARMERS.with(|m| m.borrow().get(&farmer_id))
        .ok_or_else(|| "FARMER_NOT_FOUND".to_string())?;
    if farmer.owner != caller { return Err("NOT_OWNER".to_string()); }
    let (cycles_remaining, next_gen) = match farmer.canister_id {
        // next_gen = next UTC midnight after the last generation (when the
        // 1-per-UTC-day throttle resets) — matches the Farmer's get_status; 0 = ready.
        None => (
            farmer.budget_cycles.saturating_sub(farmer.burned_cycles),
            if farmer.last_generation_at == 0 { 0 } else { (farmer.last_generation_at / DAY_NS + 1) * DAY_NS },
        ),
        Some(cid) => {
            // get_status(id) -> Result<(cycles_remaining, next_generation_at), String>.
            // The Farmer returns a candid `variant { Ok; Err }`, so decode the Result —
            // NOT a bare tuple (that mismatch made every real-canister status call fail,
            // hiding the next-round countdown + days-left on mainnet).
            let res: Result<(Result<(u64, u64), String>,), _> =
                ic_cdk::call(cid, "get_status", (farmer.id,)).await;
            match res {
                Ok((Ok((cr, ng)),)) => (cr, ng),
                Ok((Err(e),)) => return Err(format!("STATUS_REJECTED: {}", e)),
                Err((c, m)) => return Err(format!("STATUS_FAILED ({:?}): {}", c, m)),
            }
        }
    };
    Ok((farmer, cycles_remaining, next_gen))
}

// ── Sweep (added to setup_timers; bounded per pass like sweep_play_sessions) ──
async fn xfarm_sweep() {
    if !feature_active(FLAG_X_FARM) { return; }
    // (a) reap Depleted Farmers (stop+delete the canister; nothing to reclaim —
    //     cycles are ~0 by design, D2/finding #7), (b) re-notify pending CMC legs.
    let mut to_clean: Vec<(u64, Principal)> = Vec::new();
    let mut to_renotify: Vec<(u64, Principal, u64)> = Vec::new();
    XFARM_FARMERS.with(|m| {
        for entry in m.borrow().iter() {
            let f = entry.value();
            if f.status == FarmerStatus::Depleted {
                if let Some(cid) = f.canister_id {
                    to_clean.push((f.id, cid));
                    if to_clean.len() >= XFARM_SWEEP_BATCH { break; }
                }
            } else if f.status == FarmerStatus::Active && f.burn_block_index.is_some() && !f.cmc_notified {
                to_renotify.push((f.id, f.canister_id.unwrap(), f.burn_block_index.unwrap()));
            }
        }
    });
    for (id, cid) in to_clean {
        let _ = xfarm_stop_canister(cid).await;
        if let Err(e) = xfarm_delete_canister(cid).await {
            canister_print(&format!("xfarm sweep: delete farmer {} failed: {}", id, e));
            continue;
        }
        XFARM_FARMERS.with(|m| m.borrow_mut().remove(&id));
    }
    for (id, cid, block) in to_renotify {
        match notify_cmc_topup(cmc_principal(), cid, block, false).await {
            Ok(_) => XFARM_FARMERS.with(|m| {
                let mut map = m.borrow_mut();
                if let Some(mut f) = map.get(&id) { f.cmc_notified = true; map.insert(id, f); }
            }),
            Err(e) => canister_print(&format!("xfarm sweep: renotify farmer {} failed: {}", id, e)),
        }
    }
}

// ── Admin ───────────────────────────────────────────────────────────
#[ic_cdk::update(guard = "require_admin")]
fn admin_set_xfarm_proxy(url: String, bearer: String) -> Result<(), String> {
    let url = url.trim().to_string();
    if url.is_empty() { return Err("INVALID_URL".to_string()); }
    let mut cfg = xfarm_config();
    cfg.proxy = XFarmProxy { url, bearer: bearer.trim().to_string() };
    put_xfarm_config(cfg);
    Ok(())
}

#[ic_cdk::update(guard = "require_admin")]
fn admin_set_xfarm_tiers(tiers: Vec<FarmerTier>) -> Result<(), String> {
    if tiers.is_empty() || tiers.len() > XFARM_MAX_TIERS { return Err("BAD_TIERS".to_string()); }
    let mut seen = std::collections::HashSet::new();
    for t in &tiers {
        if t.drafts_per_day == 0 || t.drafts_per_day > XFARM_MAX_DRAFTS_PER_DAY {
            return Err("BAD_DRAFTS_PER_DAY".to_string());
        }
        if t.duration_days == 0 { return Err("BAD_DURATION".to_string()); }
        if !seen.insert(t.id) { return Err("DUP_TIER_ID".to_string()); }
    }
    let mut cfg = xfarm_config();
    cfg.tiers = tiers;
    put_xfarm_config(cfg);
    Ok(())
}

/// Upload the Farmer wasm the factory installs (heap-cached; re-upload after an
/// upgrade). Records the sha256 audit hash. Rotatable by re-calling.
#[ic_cdk::update(guard = "require_admin")]
fn admin_set_xfarm_wasm(wasm: Vec<u8>) -> Result<(), String> {
    if wasm.is_empty() { return Err("EMPTY_WASM".to_string()); }
    use sha2::Digest;
    let mut h = sha2::Sha256::new();
    h.update(&wasm);
    let mut hash = [0u8; 32];
    hash.copy_from_slice(&h.finalize());
    XFARM_WASM_HASH.with(|c| *c.borrow_mut() = Some(hash));
    XFARM_WASM.with(|w| *w.borrow_mut() = Some(wasm));
    Ok(())
}

/// Admin: upgrade every existing Farmer canister to the currently-uploaded wasm
/// (preserves each Farmer's stable state via post_upgrade). Rolls out a Farmer-wasm
/// fix to already-created Farmers. Returns the count upgraded; bounded by live Farmers.
#[ic_cdk::update(guard = "require_admin")]
async fn admin_reinstall_all_farmers() -> Result<u64, String> {
    let wasm = XFARM_WASM.with(|w| w.borrow().clone()).ok_or_else(|| "WASM_NOT_UPLOADED".to_string())?;
    let targets: Vec<(u64, Principal)> = XFARM_FARMERS.with(|m| {
        m.borrow().iter().filter_map(|e| e.value().canister_id.map(|c| (e.value().id, c))).collect()
    });
    let mut upgraded = 0u64;
    for (id, cid) in targets {
        match xfarm_upgrade_code(cid, wasm.clone()).await {
            Ok(()) => upgraded += 1,
            Err(e) => canister_print(&format!("xfarm reinstall: farmer {} ({}) failed: {}", id, cid.to_text(), e)),
        }
    }
    Ok(upgraded)
}

#[ic_cdk::update(guard = "require_admin")]
fn admin_set_xfarm_config(max_active_farmers: usize) -> Result<(), String> {
    // 0 = unlimited (no per-user cap; optional global brake only).
    let mut cfg = xfarm_config();
    cfg.max_active_farmers = max_active_farmers;
    put_xfarm_config(cfg);
    Ok(())
}

#[ic_cdk::update(guard = "require_admin")]
async fn admin_disable_farmer(id: u64) -> Result<(), String> {
    let farmer = XFARM_FARMERS.with(|m| m.borrow().get(&id))
        .ok_or_else(|| "FARMER_NOT_FOUND".to_string())?;
    if let Some(cid) = farmer.canister_id {
        let _ = xfarm_stop_canister(cid).await;
    }
    XFARM_FARMERS.with(|m| {
        let mut map = m.borrow_mut();
        if let Some(mut f) = map.get(&id) { f.status = FarmerStatus::Disabled; map.insert(id, f); }
    });
    Ok(())
}

// ── Dev seeds (require_local_dev; offline UI states with no real canister/burn) ──
#[ic_cdk::update(guard = "require_local_dev")]
fn dev_seed_farmer(tier_id: u32, persona: String) -> Result<Farmer, String> {
    let caller = get_caller();
    let cfg = xfarm_config();
    let tier = cfg.tiers.iter().find(|t| t.id == tier_id).cloned()
        .ok_or_else(|| "TIER_NOT_FOUND".to_string())?;
    // Local: usd_e8s_to_icp_e8s returns 0 if no admin-set rate; floor at 1 ICP.
    let price = usd_e8s_to_icp_e8s(tier.price_usd_e8s).max(100_000_000);
    let id = next_farmer_id();
    let now = current_time();
    let farmer = Farmer {
        id, owner: caller, canister_id: None, tier_id, persona: persona.trim().to_string(),
        created_at: now, expected_depleted_at: now + XFARM_DURATION_DAYS * DAY_NS,
        budget_cycles: price * 9 / 10, burned_cycles: price / 20,
        last_generation_at: now, last_burn_tick_at: now,
        status: FarmerStatus::Active,
        treasury_block: None, burn_block_index: None, install_done: true, cmc_notified: true,
    };
    xfarm_put_farmer(&farmer);
    Ok(farmer)
}

#[ic_cdk::update(guard = "require_local_dev")]
fn dev_seed_drafts(farmer_id: u64, n: u32) -> Result<(), String> {
    let farmer = XFARM_FARMERS.with(|m| m.borrow().get(&farmer_id))
        .ok_or_else(|| "FARMER_NOT_FOUND".to_string())?;
    if farmer.owner != get_caller() { return Err("NOT_OWNER".to_string()); }
    let now = current_time();
    let drafts: Vec<XFarmDraft> = (0..n).map(|i| XFarmDraft {
        id: i as u64, created_at: now,
        text: format!("Draft #{} — ICP just processed its Nth tx; the AI-agent-economy thesis holds.", i + 1),
        cited_url: Some("https://dashboard.internetcomputer.org/".to_string()),
        image_url: None,
    }).collect();
    XFARM_MOCK_DRAFTS.with(|d| d.borrow_mut().insert(farmer_id, drafts));
    Ok(())
}

#[ic_cdk::update(guard = "require_local_dev")]
fn dev_clear_farmers() -> Result<(), String> {
    let ids: Vec<u64> = XFARM_FARMERS.with(|m| m.borrow().iter().map(|e| *e.key()).collect());
    XFARM_FARMERS.with(|m| { let mut map = m.borrow_mut(); for id in ids { map.remove(&id); } });
    XFARM_MOCK_DRAFTS.with(|d| d.borrow_mut().clear());
    Ok(())
}


// ==========================================
// 21. Stake Vouchers (okf/ideas/stake-vouchers)
// ==========================================
//
// Staked positions wrap into transferable ICRC-7 voucher NFTs on the
// dedicated voucher_nft canister (backend = sole minter/burner/transfer
// authority — the VOUCHERS registry here is the ownership source of truth
// and the NFT mirrors it). Three exits: sell on the ICP-only marketplace,
// instant house buyback at a 15% discount (pay 85% → burn NFT → delete
// registry row → immediately split + dissolve, principal redeems to the
// buyback fund), or unwrap back to a plain stake and classic-unstake later.
// Promo-class vouchers (claim campaigns) earn 1 ticket/day for 60 days and
// can NEVER redeem principal — money paths hard-reject them.
//
// Owner-locked rules (2026-07-10): 15% discount; buyback pays from the
// dedicated [10u8;32] fund subaccount and REFUSES when underfunded; every
// fee (marketplace fee + realized buyback spread) splits 1/3 treasury /
// 1/3 buyback fund / 1/3 voucher-canister cycles burn; promo cap 5,000,
// drip 500/day, expiry 60 days from claim, 1 ticket/day, soulbound.

/// The house buyback fund — a dedicated ICP subaccount seeded by the owner.
/// Buybacks pay out of it; dissolved buyback principal redeems back into it.
const BUYBACK_SUBACCOUNT: [u8; 32] = [10u8; 32];
/// Buyback price: owner receives amount × (10_000 − 1_500) / 10_000 = 85%.
const BUYBACK_DISCOUNT_BPS: u64 = 1_500;
/// Marketplace fee default (admin-tunable via admin_set_voucher_config).
const VOUCHER_FEE_BPS_DEFAULT: u16 = 250;
/// Minimum wrap (matches the first-stake minimum; admin-tunable).
const VOUCHER_MIN_WRAP_E8S_DEFAULT: u64 = ONE_ICP_E8S;
/// Minimum listing ask — keeps fee legs meaningful.
const VOUCHER_MIN_LIST_E8S: u64 = 10_000_000; // 0.1 ICP
/// Promo campaign (owner-locked): global cap, daily drip, expiry, rate.
const PROMO_CAP: u32 = 5_000;
const PROMO_DAILY_DRIP: u32 = 500;
const PROMO_EXPIRY_NS: u64 = 60 * 86_400 * 1_000_000_000; // 60 days
const PROMO_TICKETS_PER_DAY: u64 = 1;
/// Per-sale escrow seed: `derive_subaccount(&buyer, VOUCHER_SALE_TAG ^ id)`.
/// Distinct from SALE_ESCROW_TAG (u64::MAX − 307) and every other seed.
const VOUCHER_SALE_TAG: u64 = u64::MAX - 411;

#[derive(CandidType, Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
pub enum VoucherClass {
    Backed,
    Promo,
    /// Wraps an ICPSwap LP custody position (owner 2026-07-11). NON-SELLABLE:
    /// no marketplace, no buyback, no transfer, no redeem — LP is instantly
    /// reclaimable via unstake_lp_position, so a market has nothing to solve.
    /// Earns NO voucher-math tickets (the LP grant path pays 40/day/$).
    LpBacked,
}

/// Registry row — the authoritative claim record (NFT mirrors it).
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct VoucherRecord {
    pub id: u64,
    pub class: VoucherClass,
    /// StakeTier::idx(); Promo rows carry 0 (unused).
    pub tier: u8,
    /// Backed: staked-ICP claim (e8s). Promo: 0.
    pub amount_e8s: u64,
    pub owner: Principal,
    pub minted_at: u64,
    /// Promo only: stops earning after this instant (claim + 60 days).
    pub expires_at: Option<u64>,
    /// Live marketplace ask (ICP e8s); None = not listed.
    pub listed_price_e8s: Option<u64>,
    /// UTC day of the last instant purchase-grant for THIS voucher — buying
    /// grants its daily tickets immediately, once per voucher per day (kills
    /// same-day wash-trade farming).
    #[serde(default)]
    pub last_purchase_grant_day: u64,
}

/// Marketplace sale saga journal — persisted between legs so an interrupted
/// buy resumes without repeating a block-indexed transfer.
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct VoucherSale {
    pub voucher_id: u64,
    pub buyer: Principal,
    pub seller: Principal,
    pub price_e8s: u64,
    pub fee_e8s: u64,
    pub started_at: u64,
    pub seller_block: Option<u64>,
    pub fee_treasury_block: Option<u64>,
    pub fee_fund_block: Option<u64>,
    pub fee_cmc_block: Option<u64>,
    pub cmc_notified: bool,
    pub transferred: bool,
}

/// Buyback saga journal — pay → burn NFT → registry delete → split+dissolve;
/// the 15% spread routes when the dissolved principal lands in the fund.
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct BuybackJob {
    pub voucher_id: u64,
    pub owner: Principal,
    pub tier: u8,
    pub amount_e8s: u64,
    pub pay_e8s: u64,
    pub created_at: u64,
    pub pay_block: Option<u64>,
    pub nft_burned: bool,
    pub pending_unstake_id: Option<u64>,
    /// Spread fee legs (routed after the disburse lands in the fund).
    pub spread_treasury_block: Option<u64>,
    pub spread_cmc_block: Option<u64>,
    pub spread_cmc_notified: bool,
    pub spread_routed: bool,
}

/// Promo campaign singleton (MemoryId 132).
#[derive(CandidType, Serialize, Deserialize, Clone, Debug, Default)]
pub struct PromoCampaign {
    pub open: bool,
    pub claimed: u32,
    /// UTC day of `claims_today` (drip window).
    pub day: u64,
    pub claims_today: u32,
}

/// Admin-tunable knobs (MemoryId 133).
#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct VoucherConfig {
    pub market_fee_bps: u16,
    pub min_wrap_e8s: u64,
}

impl Default for VoucherConfig {
    fn default() -> Self {
        VoucherConfig { market_fee_bps: VOUCHER_FEE_BPS_DEFAULT, min_wrap_e8s: VOUCHER_MIN_WRAP_E8S_DEFAULT }
    }
}

impl_storable!(VoucherRecord);
impl_storable!(VoucherSale);
impl_storable!(BuybackJob);
impl_storable!(PromoCampaign);
impl_storable!(VoucherConfig);

thread_local! {
    // 128 — voucher registry (id → record; the ownership source of truth)
    static VOUCHERS: RefCell<StableBTreeMap<u64, VoucherRecord, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableBTreeMap::init(mm.borrow().get(MemoryId::new(128)))));
    // 129 — next voucher id (ids start at 1; never reused, burns retire them)
    static NEXT_VOUCHER_ID: RefCell<StableCell<u64, Memory>> = MEMORY_MANAGER.with(|mm| {
        RefCell::new(StableCell::init(mm.borrow().get(MemoryId::new(129)), 1u64))
    });
    // 130 — marketplace sale journals (voucher id → saga)
    static VOUCHER_SALES: RefCell<StableBTreeMap<u64, VoucherSale, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableBTreeMap::init(mm.borrow().get(MemoryId::new(130)))));
    // 131 — buyback saga journals (voucher id → job; kept until spread routed)
    static BUYBACK_JOBS: RefCell<StableBTreeMap<u64, BuybackJob, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableBTreeMap::init(mm.borrow().get(MemoryId::new(131)))));
    // 132 — promo campaign singleton
    static PROMO_CAMPAIGN: RefCell<StableCell<PromoCampaign, Memory>> = MEMORY_MANAGER.with(|mm| {
        RefCell::new(StableCell::init(mm.borrow().get(MemoryId::new(132)), PromoCampaign::default()))
    });
    // 133 — voucher config (fee bps / min wrap)
    static VOUCHER_CONFIG: RefCell<StableCell<VoucherConfig, Memory>> = MEMORY_MANAGER.with(|mm| {
        RefCell::new(StableCell::init(mm.borrow().get(MemoryId::new(133)), VoucherConfig::default()))
    });
    // 134 — promo claimed set (principal → 1; one voucher per principal)
    static PROMO_CLAIMED: RefCell<StableBTreeMap<Principal, u8, Memory>> =
        MEMORY_MANAGER.with(|mm| RefCell::new(StableBTreeMap::init(mm.borrow().get(MemoryId::new(134)))));
}

fn voucher_config() -> VoucherConfig {
    VOUCHER_CONFIG.with(|c| c.borrow().get().clone())
}

fn promo_campaign() -> PromoCampaign {
    PROMO_CAMPAIGN.with(|c| c.borrow().get().clone())
}

fn set_promo_campaign(c2: PromoCampaign) {
    PROMO_CAMPAIGN.with(|c| { c.borrow_mut().set(c2); });
}

fn voucher_nft_cid() -> Result<Principal, String> {
    CONFIG
        .with(|c| c.borrow().get().voucher_nft_canister)
        .ok_or_else(|| "VOUCHER_NFT_NOT_CONFIGURED".to_string())
}

/// Backed voucher e8s a user holds in one tier (their wrapped stake).
/// One voucher's daily ticket rate: base × tier multiplier × whole ICP
/// (sub-1-ICP floors to one base unit) — the same math the daily grant uses.
fn voucher_daily_rate(v: &VoucherRecord) -> u64 {
    let base = CONFIG.with(|c| c.borrow().get().lottery_tickets_per_day);
    let tier = tier_from_idx(v.tier);
    let whole_icp = (v.amount_e8s / ONE_ICP_E8S).max(1);
    base.saturating_mul(tier.weight_multiplier()).saturating_mul(whole_icp)
}

fn voucher_backed_e8s(user: Principal, tier: StakeTier) -> u64 {
    VOUCHERS.with(|m| {
        m.borrow()
            .iter()
            .filter(|e| {
                let v = e.value();
                // Owner rule (2026-07-10): a voucher LISTED FOR SALE is not
                // lottery-eligible — its ticket stream pauses until delisted.
                v.class == VoucherClass::Backed && v.owner == user && v.tier == tier.idx()
                    && v.listed_price_e8s.is_none()
            })
            .map(|e| e.value().amount_e8s)
            .sum()
    })
}

/// Promo tickets/day for a user: 1 per unexpired promo voucher they hold.
fn promo_daily_tickets(user: Principal) -> u64 {
    let now = current_time();
    VOUCHERS.with(|m| {
        m.borrow()
            .iter()
            .filter(|e| {
                let v = e.value();
                v.class == VoucherClass::Promo
                    && v.owner == user
                    && v.expires_at.map(|x| now < x).unwrap_or(false)
            })
            .count() as u64
    }) * PROMO_TICKETS_PER_DAY
}

/// Stake + booster + backed-voucher + promo tickets/day — the ONE number both
/// grant paths and the lottery info must agree on (a mismatch would let the
/// lower path stamp `last_claim_day` and under-grant the higher one).
fn total_daily_tickets(user: Principal) -> u64 {
    user_daily_tickets(user).saturating_add(promo_daily_tickets(user))
}

// ── voucher_nft inter-canister seams (mock pair for native tests) ──────────

#[cfg(target_arch = "wasm32")]
async fn voucher_nft_mint(
    token_id: u64,
    to: Principal,
    class: VoucherClass,
    tier: u8,
    amount_e8s: u64,
    expires_at: Option<u64>,
) -> Result<(), String> {
    #[derive(CandidType)]
    struct MintArgs {
        token_id: u64,
        to: Principal,
        class: VoucherClass,
        tier: u8,
        amount_e8s: u64,
        expires_at: Option<u64>,
    }
    let cid = voucher_nft_cid()?;
    let args = MintArgs { token_id, to, class, tier, amount_e8s, expires_at };
    let res: Result<(Result<u64, String>,), _> = ic_cdk::call(cid, "mint", (args,)).await;
    match res {
        Ok((Ok(_),)) => Ok(()),
        Ok((Err(e),)) => Err(format!("VOUCHER_MINT_ERR: {}", e)),
        Err((c, m)) => Err(format!("VOUCHER_MINT_REJECTED ({:?}): {}", c, m)),
    }
}

#[cfg(target_arch = "wasm32")]
async fn voucher_nft_transfer(from: Principal, to: Principal, token_id: u64) -> Result<(), String> {
    let cid = voucher_nft_cid()?;
    let res: Result<(Result<(), String>,), _> =
        ic_cdk::call(cid, "custodial_transfer", (from, to, token_id)).await;
    match res {
        Ok((Ok(()),)) => Ok(()),
        Ok((Err(e),)) => Err(format!("VOUCHER_TRANSFER_ERR: {}", e)),
        Err((c, m)) => Err(format!("VOUCHER_TRANSFER_REJECTED ({:?}): {}", c, m)),
    }
}

#[cfg(target_arch = "wasm32")]
async fn voucher_nft_burn(token_id: u64) -> Result<(), String> {
    let cid = voucher_nft_cid()?;
    let res: Result<(Result<(), String>,), _> = ic_cdk::call(cid, "burn", (token_id,)).await;
    match res {
        Ok((Ok(()),)) => Ok(()),
        Ok((Err(e),)) => Err(format!("VOUCHER_BURN_ERR: {}", e)),
        Err((c, m)) => Err(format!("VOUCHER_BURN_REJECTED ({:?}): {}", c, m)),
    }
}

#[cfg(not(target_arch = "wasm32"))]
thread_local! {
    /// token_id → owner mirror for native tests.
    static TEST_MOCK_VOUCHER_OWNER: RefCell<std::collections::HashMap<u64, Principal>> =
        RefCell::new(std::collections::HashMap::new());
    static TEST_MOCK_VOUCHER_MINT_FAIL: RefCell<bool> = const { RefCell::new(false) };
    static TEST_MOCK_VOUCHER_TRANSFER_FAIL: RefCell<bool> = const { RefCell::new(false) };
    static TEST_MOCK_VOUCHER_BURN_FAIL: RefCell<bool> = const { RefCell::new(false) };
}

#[cfg(not(target_arch = "wasm32"))]
async fn voucher_nft_mint(
    token_id: u64,
    to: Principal,
    _class: VoucherClass,
    _tier: u8,
    _amount_e8s: u64,
    _expires_at: Option<u64>,
) -> Result<(), String> {
    if TEST_MOCK_VOUCHER_MINT_FAIL.with(|c| *c.borrow()) {
        return Err("VOUCHER_MINT_REJECTED (mock failure)".to_string());
    }
    TEST_MOCK_VOUCHER_OWNER.with(|m| { m.borrow_mut().insert(token_id, to); });
    Ok(())
}

#[cfg(not(target_arch = "wasm32"))]
async fn voucher_nft_transfer(from: Principal, to: Principal, token_id: u64) -> Result<(), String> {
    if TEST_MOCK_VOUCHER_TRANSFER_FAIL.with(|c| *c.borrow()) {
        return Err("VOUCHER_TRANSFER_REJECTED (mock failure)".to_string());
    }
    let live = TEST_MOCK_VOUCHER_OWNER.with(|m| m.borrow().get(&token_id).copied());
    if live != Some(from) {
        return Err("VOUCHER_TRANSFER_ERR: from != owner".to_string());
    }
    TEST_MOCK_VOUCHER_OWNER.with(|m| { m.borrow_mut().insert(token_id, to); });
    Ok(())
}

#[cfg(not(target_arch = "wasm32"))]
async fn voucher_nft_burn(token_id: u64) -> Result<(), String> {
    if TEST_MOCK_VOUCHER_BURN_FAIL.with(|c| *c.borrow()) {
        return Err("VOUCHER_BURN_REJECTED (mock failure)".to_string());
    }
    TEST_MOCK_VOUCHER_OWNER.with(|m| { m.borrow_mut().remove(&token_id); });
    Ok(())
}

// ── Candid views ────────────────────────────────────────────────────────────

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct VoucherView {
    pub id: u64,
    pub class: VoucherClass,
    pub tier: StakeTier,
    pub amount_e8s: u64,
    pub owner: Principal,
    pub minted_at: u64,
    pub expires_at: Option<u64>,
    pub listed_price_e8s: Option<u64>,
}

fn tier_from_idx(idx: u8) -> StakeTier {
    match idx {
        0 => StakeTier::SixMonths,
        1 => StakeTier::OneYear,
        _ => StakeTier::TwoYears,
    }
}

fn voucher_view(v: &VoucherRecord) -> VoucherView {
    VoucherView {
        id: v.id,
        class: v.class,
        tier: tier_from_idx(v.tier),
        amount_e8s: v.amount_e8s,
        owner: v.owner,
        minted_at: v.minted_at,
        expires_at: v.expires_at,
        listed_price_e8s: v.listed_price_e8s,
    }
}

#[derive(CandidType, Serialize, Deserialize, Clone, Debug)]
pub struct VoucherMarketInfo {
    pub enabled: bool,
    pub min_wrap_e8s: u64,
    pub market_fee_bps: u16,
    pub buyback_discount_bps: u16,
    pub buyback_fund_e8s: u64,
    pub my_vouchers: Vec<VoucherView>,
    pub listings: Vec<VoucherView>,
    pub promo_open: bool,
    pub promo_remaining: u32,
    pub promo_claims_today: u32,
}

/// Cached buyback-fund balance (heap; refreshed by the sweep + every fund
/// mutation) so `get_voucher_market` stays a QUERY.
thread_local! {
    static CACHED_BUYBACK_FUND_E8S: RefCell<u64> = const { RefCell::new(0) };
}

async fn refresh_buyback_fund_cache() -> u64 {
    let config = CONFIG.with(|c| c.borrow().get().clone());
    let acct = LedgerAccount { owner: get_canister_id(), subaccount: Some(BUYBACK_SUBACCOUNT) };
    match call_ledger_balance(config.ledger_canister_id, acct).await {
        Ok(b) => {
            CACHED_BUYBACK_FUND_E8S.with(|c| *c.borrow_mut() = b);
            b
        }
        Err(_) => CACHED_BUYBACK_FUND_E8S.with(|c| *c.borrow()),
    }
}

#[ic_cdk::query]
fn get_voucher_market() -> VoucherMarketInfo {
    let caller = get_caller();
    let campaign = promo_campaign();
    let today = current_time() / 1_000_000_000 / SECS_PER_DAY;
    let claims_today = if campaign.day == today { campaign.claims_today } else { 0 };
    VoucherMarketInfo {
        enabled: feature_visible(FLAG_STAKE_VOUCHERS, caller),
        min_wrap_e8s: voucher_config().min_wrap_e8s,
        market_fee_bps: voucher_config().market_fee_bps,
        buyback_discount_bps: BUYBACK_DISCOUNT_BPS as u16,
        buyback_fund_e8s: CACHED_BUYBACK_FUND_E8S.with(|c| *c.borrow()),
        my_vouchers: VOUCHERS.with(|m| {
            m.borrow()
                .iter()
                .filter(|e| e.value().owner == caller)
                .map(|e| voucher_view(&e.value()))
                .collect()
        }),
        listings: VOUCHERS.with(|m| {
            m.borrow()
                .iter()
                .filter(|e| e.value().listed_price_e8s.is_some())
                .map(|e| voucher_view(&e.value()))
                .collect()
        }),
        promo_open: campaign.open,
        promo_remaining: PROMO_CAP.saturating_sub(campaign.claimed),
        promo_claims_today: claims_today,
    }
}

// ── Wrap / unwrap ───────────────────────────────────────────────────────────

/// Wrap `amount_e8s` of the caller's `tier` stake into a Backed voucher NFT.
/// The STAKES row is debited (the ICP itself stays in the pooled neuron; the
/// registry row now carries the claim). Whole-ICP amounts only, so a later
/// buyback's neuron split stays valid. EA/Booster stakes are NOT wrappable
/// (separate map, permanent by design).
#[ic_cdk::update]
/// Auto-issue a voucher for a freshly landed stake (owner 2026-07-10: no
/// manual wrap — staking IS receiving the NFT). Converts the WHOLE-ICP part
/// of the caller's plain stake row into a Backed voucher; any sub-ICP
/// remainder stays a plain row. Best-effort: if the NFT canister is not
/// configured or the mint fails, the plain stake stands untouched (mainnet-
/// safe until voucher_nft is wired).
async fn auto_issue_voucher(user: Principal, tier: StakeTier) -> Option<u64> {
    if !feature_enabled(FLAG_STAKE_VOUCHERS) || voucher_nft_cid().is_err() {
        return None;
    }
    let key = stake_key(tier, user);
    let stake = STAKES.with(|m| m.borrow().get(&key))?;
    let cfg = voucher_config();
    let whole = (stake.amount_e8s / ONE_ICP_E8S) * ONE_ICP_E8S;
    if whole < cfg.min_wrap_e8s {
        return None;
    }
    let now = current_time();
    let id = NEXT_VOUCHER_ID.with(|c| {
        let id = *c.borrow().get();
        c.borrow_mut().set(id + 1);
        id
    });
    // Same debit-then-mint-then-revert dance as the manual path.
    let stake_backup = Some(stake.clone());
    let mut debited = stake.clone();
    debited.amount_e8s -= whole;
    debited.last_action_at = now;
    if debited.amount_e8s == 0 {
        STAKES.with(|m| { m.borrow_mut().remove(&key); });
    } else {
        STAKES.with(|m| { m.borrow_mut().insert(key.clone(), debited); });
    }
    if let Err(e) = voucher_nft_mint(id, user, VoucherClass::Backed, tier.idx(), whole, None).await {
        canister_print(&format!("auto_issue_voucher: mint failed, stake stays plain: {}", e));
        if let Some(orig) = stake_backup {
            STAKES.with(|m| { m.borrow_mut().insert(key, orig); });
        }
        return None;
    }
    VOUCHERS.with(|m| {
        m.borrow_mut().insert(id, VoucherRecord {
            id,
            class: VoucherClass::Backed,
            tier: tier.idx(),
            amount_e8s: whole,
            owner: user,
            minted_at: now,
            expires_at: None,
            listed_price_e8s: None,
            last_purchase_grant_day: 0,
        });
    });
    staking_audit("voucher_auto_issue", user, whole, id);
    Some(id)
}

/// Local-dev: populate the marketplace with N mock listed vouchers owned by
/// synthetic principals so the grid is visualizable. NOT pool-backed — local
/// nets only (hard is_local guard), admin-gated.
#[ic_cdk::update]
async fn dev_seed_mock_vouchers(n: u32) -> Result<u32, String> {
    require_admin()?;
    let config = CONFIG.with(|c| c.borrow().get().clone());
    if !config.is_local {
        return Err("LOCAL_ONLY".to_string());
    }
    let now = current_time();
    let mut made = 0u32;
    for i in 0..n.min(24) {
        let id = NEXT_VOUCHER_ID.with(|c| {
            let id = *c.borrow().get();
            c.borrow_mut().set(id + 1);
            id
        });
        // Synthetic self-auth-shaped owners (derived, stable per index).
        let mut bytes = [0u8; 10];
        bytes[0..8].copy_from_slice(&(9_100_000u64 + i as u64).to_be_bytes());
        bytes[9] = 0x02;
        let owner = Principal::from_slice(&bytes);
        let tier_idx = (i % 3) as u8;
        let amount = ONE_ICP_E8S * [2u64, 5, 10, 25, 3, 7][i as usize % 6];
        // Asks scatter around principal: some discounted, some premium.
        let ask = amount * [88u64, 95, 100, 104, 92, 110][i as usize % 6] / 100;
        if voucher_nft_mint(id, owner, VoucherClass::Backed, tier_idx, amount, None).await.is_err() {
            continue;
        }
        VOUCHERS.with(|m| {
            m.borrow_mut().insert(id, VoucherRecord {
                id, class: VoucherClass::Backed, tier: tier_idx, amount_e8s: amount,
                owner, minted_at: now, expires_at: None, listed_price_e8s: Some(ask), last_purchase_grant_day: 0,
            });
        });
        made += 1;
    }
    Ok(made)
}

/// Transfer a voucher to any principal (the wallet's withdraw/deposit rail —
/// send to your Plug/OISY principal, or back again from there). Owner-only,
/// Backed + unlisted only; the recipient's ticket stream starts at the next
/// daily grant. Never flag-gated (custody exit).
#[ic_cdk::update]
async fn transfer_voucher(id: u64, to: Principal) -> Result<(), String> {
    require_authenticated()?;
    let caller = get_caller();
    let _guard = CallerGuard::new(caller)?;
    if to == Principal::anonymous() || to == get_canister_id() {
        return Err("INVALID_PRINCIPAL".to_string());
    }
    let v = VOUCHERS.with(|m| m.borrow().get(&id)).ok_or("NOT_YOUR_VOUCHER")?;
    if v.owner != caller {
        return Err("NOT_YOUR_VOUCHER".to_string());
    }
    if matches!(v.class, VoucherClass::Promo) {
        return Err("PROMO_NOT_ALLOWED".to_string());
    }
    if matches!(v.class, VoucherClass::LpBacked) {
        return Err("LP_NOT_ALLOWED".to_string());
    }
    if v.listed_price_e8s.is_some() {
        return Err("VOUCHER_LISTED".to_string());
    }
    voucher_nft_transfer(caller, to, id).await?;
    VOUCHERS.with(|m| {
        let mut reg = m.borrow_mut();
        if let Some(mut rec) = reg.get(&id) {
            rec.owner = to;
            reg.insert(id, rec);
        }
    });
    staking_audit("voucher_transfer", caller, v.amount_e8s, id);
    Ok(())
}

/// Redeem = the voucher-native classic unstake (owner 2026-07-10 modal:
/// "wait for dissolve" choice). Burns the voucher, restores the claim to a
/// plain stake row, and immediately starts the standard unstake — the FULL
/// amount pays the owner after the tier's dissolve. Never flag-gated (exit).
#[ic_cdk::update]
async fn redeem_stake_voucher(id: u64) -> Result<u64, String> {
    require_authenticated()?;
    let caller = get_caller();
    let v = VOUCHERS.with(|m| m.borrow().get(&id)).ok_or("NOT_YOUR_VOUCHER")?;
    if v.owner != caller {
        return Err("NOT_YOUR_VOUCHER".to_string());
    }
    if matches!(v.class, VoucherClass::Promo) {
        return Err("PROMO_NOT_ALLOWED".to_string());
    }
    if matches!(v.class, VoucherClass::LpBacked) {
        return Err("LP_NOT_ALLOWED".to_string());
    }
    if v.listed_price_e8s.is_some() {
        return Err("VOUCHER_LISTED".to_string());
    }
    let tier = tier_from_idx(v.tier);
    let amount = v.amount_e8s;
    // Leg 1: voucher → plain row (burn NFT; restore STAKES). Same-caller
    // call into the unwrap endpoint fn keeps registry/NFT in lockstep.
    unwrap_stake_voucher(id).await?;
    // Leg 2: the classic unstake (split + dissolve, pays the owner 100%).
    // If this leg fails (pool constraints), the claim safely REMAINS a plain
    // stake row — the user can retry or restake; nothing is lost.
    unstake(amount, tier).await.map_err(|e| format!("UNSTAKE_AFTER_REDEEM: {}", e))
}

#[ic_cdk::update]
async fn wrap_stake_voucher(amount_e8s: u64, tier: StakeTier) -> Result<u64, String> {
    require_authenticated()?;
    if !feature_visible(FLAG_STAKE_VOUCHERS, get_caller()) {
        return Err("FEATURE_DISABLED".to_string());
    }
    let caller = get_caller();
    let _guard = CallerGuard::new(caller)?;
    let cfg = voucher_config();
    if amount_e8s < cfg.min_wrap_e8s {
        return Err("BELOW_MINIMUM".to_string());
    }
    if amount_e8s % ONE_ICP_E8S != 0 {
        return Err("WHOLE_ICP_ONLY".to_string());
    }
    let key = stake_key(tier, caller);
    let mut stake = STAKES.with(|m| m.borrow().get(&key)).ok_or("NO_STAKE")?;
    if amount_e8s > stake.amount_e8s {
        return Err("INSUFFICIENT_STAKE".to_string());
    }

    let now = current_time();
    let id = NEXT_VOUCHER_ID.with(|c| {
        let id = *c.borrow().get();
        c.borrow_mut().set(id + 1);
        id
    });

    // Debit first, mint second — revert the debit if the NFT mint fails
    // (single await; no journal needed).
    stake.amount_e8s -= amount_e8s;
    stake.last_action_at = now;
    let stake_backup = STAKES.with(|m| m.borrow().get(&key));
    if stake.amount_e8s == 0 {
        STAKES.with(|m| { m.borrow_mut().remove(&key); });
    } else {
        STAKES.with(|m| { m.borrow_mut().insert(key.clone(), stake.clone()); });
    }

    if let Err(e) = voucher_nft_mint(id, caller, VoucherClass::Backed, tier.idx(), amount_e8s, None).await {
        // Revert: restore the exact pre-debit row.
        if let Some(orig) = stake_backup {
            STAKES.with(|m| { m.borrow_mut().insert(key, orig); });
        }
        return Err(e);
    }

    VOUCHERS.with(|m| {
        m.borrow_mut().insert(id, VoucherRecord {
            id,
            class: VoucherClass::Backed,
            tier: tier.idx(),
            amount_e8s,
            owner: caller,
            minted_at: now,
            expires_at: None,
            listed_price_e8s: None,
            last_purchase_grant_day: 0,
        });
    });
    staking_audit("voucher_wrap", caller, amount_e8s, id);
    Ok(id)
}

/// Unwrap a Backed voucher back into a plain stake row (burns the NFT).
/// Deliberately NOT flag-gated: it is an exit.
#[ic_cdk::update]
async fn unwrap_stake_voucher(voucher_id: u64) -> Result<(), String> {
    require_authenticated()?;
    let caller = get_caller();
    let _guard = CallerGuard::new(caller)?;
    let v = VOUCHERS.with(|m| m.borrow().get(&voucher_id)).ok_or("VOUCHER_NOT_FOUND")?;
    if v.owner != caller {
        return Err("NOT_YOUR_VOUCHER".to_string());
    }
    if matches!(v.class, VoucherClass::LpBacked) {
        return Err("LP_NOT_ALLOWED".to_string());
    }
    if v.class != VoucherClass::Backed {
        return Err("PROMO_NOT_REDEEMABLE".to_string());
    }
    if v.listed_price_e8s.is_some() {
        return Err("LISTED: cancel the listing first".to_string());
    }
    if VOUCHER_SALES.with(|m| m.borrow().contains_key(&voucher_id)) {
        return Err("SALE_IN_PROGRESS".to_string());
    }
    if BUYBACK_JOBS.with(|m| m.borrow().contains_key(&voucher_id)) {
        return Err("BUYBACK_IN_PROGRESS".to_string());
    }

    voucher_nft_burn(voucher_id).await?;

    let now = current_time();
    let tier = tier_from_idx(v.tier);
    let key = stake_key(tier, caller);
    let mut stake = STAKES.with(|m| m.borrow().get(&key)).unwrap_or(UserStake {
        amount_e8s: 0,
        staked_at: v.minted_at,
        last_action_at: now,
    });
    stake.amount_e8s = stake.amount_e8s.saturating_add(v.amount_e8s);
    stake.last_action_at = now;
    STAKES.with(|m| { m.borrow_mut().insert(key, stake); });
    VOUCHERS.with(|m| { m.borrow_mut().remove(&voucher_id); });
    staking_audit("voucher_unwrap", caller, v.amount_e8s, voucher_id);
    Ok(())
}

// ── Marketplace (ICP asks only) ─────────────────────────────────────────────

#[ic_cdk::update]
fn list_voucher(voucher_id: u64, price_e8s: u64) -> Result<(), String> {
    require_authenticated()?;
    if !feature_visible(FLAG_STAKE_VOUCHERS, get_caller()) {
        return Err("FEATURE_DISABLED".to_string());
    }
    let caller = get_caller();
    let mut v = VOUCHERS.with(|m| m.borrow().get(&voucher_id)).ok_or("VOUCHER_NOT_FOUND")?;
    if v.owner != caller {
        return Err("NOT_YOUR_VOUCHER".to_string());
    }
    if matches!(v.class, VoucherClass::LpBacked) {
        return Err("LP_NOT_ALLOWED".to_string());
    }
    if v.class != VoucherClass::Backed {
        return Err("PROMO_NOT_LISTABLE".to_string());
    }
    if price_e8s < VOUCHER_MIN_LIST_E8S {
        return Err("PRICE_TOO_LOW".to_string());
    }
    if VOUCHER_SALES.with(|m| m.borrow().contains_key(&voucher_id)) {
        return Err("SALE_IN_PROGRESS".to_string());
    }
    if BUYBACK_JOBS.with(|m| m.borrow().contains_key(&voucher_id)) {
        return Err("BUYBACK_IN_PROGRESS".to_string());
    }
    v.listed_price_e8s = Some(price_e8s);
    VOUCHERS.with(|m| { m.borrow_mut().insert(voucher_id, v); });
    Ok(())
}

/// Cancel a listing. NOT flag-gated (withdrawing an offer is an exit).
#[ic_cdk::update]
fn cancel_voucher_listing(voucher_id: u64) -> Result<(), String> {
    require_authenticated()?;
    let caller = get_caller();
    let mut v = VOUCHERS.with(|m| m.borrow().get(&voucher_id)).ok_or("VOUCHER_NOT_FOUND")?;
    if v.owner != caller {
        return Err("NOT_YOUR_VOUCHER".to_string());
    }
    if VOUCHER_SALES.with(|m| m.borrow().contains_key(&voucher_id)) {
        return Err("SALE_IN_PROGRESS".to_string());
    }
    if v.listed_price_e8s.is_none() {
        return Err("NOT_LISTED".to_string());
    }
    v.listed_price_e8s = None;
    VOUCHERS.with(|m| { m.borrow_mut().insert(voucher_id, v); });
    Ok(())
}

/// The buyer-specific escrow account for a listing: fund it with
/// ask + 4 × 0.0001 ICP (the settlement legs' ledger fees), then call
/// `buy_voucher`. Leftovers are reclaimable via `reclaim_escrow(StakeVoucher)`.
#[ic_cdk::query]
fn get_voucher_sale_account(voucher_id: u64) -> LedgerAccount {
    LedgerAccount {
        owner: get_canister_id(),
        subaccount: Some(derive_subaccount(&get_caller(), VOUCHER_SALE_TAG ^ voucher_id)),
    }
}

/// Settle a voucher purchase from the caller's funded escrow. Journaled saga:
/// seller leg → fee legs (1/3 treasury · 1/3 buyback fund · 1/3 voucher-nft
/// cycles burn) → ownership move (registry + NFT). Resume-safe per leg.
#[ic_cdk::update]
async fn buy_voucher(voucher_id: u64) -> Result<(), String> {
    require_authenticated()?;
    if !feature_visible(FLAG_STAKE_VOUCHERS, get_caller()) {
        return Err("FEATURE_DISABLED".to_string());
    }
    let buyer = get_caller();
    let _guard = CallerGuard::new(buyer)?;

    let mut sale = match VOUCHER_SALES.with(|m| m.borrow().get(&voucher_id)) {
        Some(existing) if existing.buyer == buyer => existing,
        Some(_) => return Err("SALE_IN_PROGRESS".to_string()),
        None => {
            let v = VOUCHERS.with(|m| m.borrow().get(&voucher_id)).ok_or("VOUCHER_NOT_FOUND")?;
            let price_e8s = v.listed_price_e8s.ok_or("NOT_LISTED")?;
            if v.owner == buyer {
                return Err("CANNOT_BUY_OWN_VOUCHER".to_string());
            }
            if v.class != VoucherClass::Backed {
                return Err("PROMO_NOT_LISTABLE".to_string());
            }
            let fee_e8s = price_e8s.saturating_mul(voucher_config().market_fee_bps as u64) / 10_000;
            VoucherSale {
                voucher_id,
                buyer,
                seller: v.owner,
                price_e8s,
                fee_e8s,
                started_at: current_time(),
                seller_block: None,
                fee_treasury_block: None,
                fee_fund_block: None,
                fee_cmc_block: None,
                cmc_notified: false,
                transferred: false,
            }
        }
    };
    VOUCHER_SALES.with(|m| { m.borrow_mut().insert(voucher_id, sale.clone()); });

    let result = run_voucher_sale_saga(&mut sale).await;
    VOUCHER_SALES.with(|m| { m.borrow_mut().insert(voucher_id, sale.clone()); });
    result?;

    // Success: move the registry row, clear the listing + journal.
    VOUCHERS.with(|m| {
        let mut map = m.borrow_mut();
        if let Some(mut v) = map.get(&voucher_id) {
            v.owner = sale.buyer;
            v.listed_price_e8s = None;
            map.insert(voucher_id, v);
        }
    });
    VOUCHER_SALES.with(|m| { m.borrow_mut().remove(&voucher_id); });
    // Owner rule (2026-07-10): buying a voucher rewards the buyer with THAT
    // voucher's daily tickets immediately, entering the upcoming draw — once
    // per voucher per UTC day, so a wash-traded voucher can't be farmed.
    let today = current_time() / 1_000_000_000 / SECS_PER_DAY;
    let granted = VOUCHERS.with(|m| {
        let mut reg = m.borrow_mut();
        match reg.get(&voucher_id) {
            Some(mut rec) if rec.class == VoucherClass::Backed && rec.last_purchase_grant_day < today => {
                rec.last_purchase_grant_day = today;
                let rate = voucher_daily_rate(&rec);
                reg.insert(voucher_id, rec);
                rate
            }
            _ => 0,
        }
    });
    if granted > 0 {
        grant_lottery_tickets(sale.buyer, granted, "voucher_purchase");
    }

    staking_audit("voucher_sale", sale.buyer, sale.price_e8s, voucher_id);
    Ok(())
}

async fn run_voucher_sale_saga(sale: &mut VoucherSale) -> Result<(), String> {
    let config = CONFIG.with(|c| c.borrow().get().clone());
    let ledger = config.ledger_canister_id;
    let escrow_sub = derive_subaccount(&sale.buyer, VOUCHER_SALE_TAG ^ sale.voucher_id);
    let self_id = get_canister_id();

    // Escrow must cover price + the settlement legs' ledger fees up front.
    if sale.seller_block.is_none() {
        let escrow = LedgerAccount { owner: self_id, subaccount: Some(escrow_sub) };
        let balance = call_ledger_balance(ledger, escrow).await?;
        let required = sale.price_e8s + 4 * ICP_FEE_E8S;
        if balance < required {
            // Nothing moved yet — drop the journal so the listing stays open.
            VOUCHER_SALES.with(|m| { m.borrow_mut().remove(&sale.voucher_id); });
            return Err("ESCROW_NOT_FUNDED".to_string());
        }
    }

    // Fee thirds — cycles + fund thirds are fee/3; treasury absorbs remainder.
    let fund_amt = sale.fee_e8s / 3;
    let cmc_amt = sale.fee_e8s / 3;
    let treasury_amt = sale.fee_e8s - fund_amt - cmc_amt;

    // 1. Seller gets ask − fee.
    if sale.seller_block.is_none() {
        let dest = LedgerAccount { owner: sale.seller, subaccount: None };
        let amount = sale.price_e8s - sale.fee_e8s;
        let b = call_ledger_transfer(ledger, Some(escrow_sub), dest, amount, Some(ICP_FEE_E8S))
            .await
            .map_err(|e| format!("SELLER_XFER: {}", e))?;
        sale.seller_block = Some(b);
    }

    // 2. Fee → treasury third.
    if sale.fee_treasury_block.is_none() {
        if treasury_amt > ICP_FEE_E8S {
            let dest = LedgerAccount { owner: self_id, subaccount: Some(TREASURY_SUBACCOUNT) };
            let b = call_ledger_transfer(ledger, Some(escrow_sub), dest, treasury_amt, Some(ICP_FEE_E8S))
                .await
                .map_err(|e| format!("FEE_TREASURY_XFER: {}", e))?;
            sale.fee_treasury_block = Some(b);
        } else {
            sale.fee_treasury_block = Some(0); // dust — skipped
        }
    }

    // 3. Fee → buyback-fund third.
    if sale.fee_fund_block.is_none() {
        if fund_amt > ICP_FEE_E8S {
            let dest = LedgerAccount { owner: self_id, subaccount: Some(BUYBACK_SUBACCOUNT) };
            let b = call_ledger_transfer(ledger, Some(escrow_sub), dest, fund_amt, Some(ICP_FEE_E8S))
                .await
                .map_err(|e| format!("FEE_FUND_XFER: {}", e))?;
            sale.fee_fund_block = Some(b);
        } else {
            sale.fee_fund_block = Some(0);
        }
    }

    // 4. Fee → voucher-canister cycles burn third (CMC top-up).
    if sale.fee_cmc_block.is_none() {
        if cmc_amt > ICP_FEE_E8S {
            if let Ok(target) = voucher_nft_cid() {
                let b = call_cmc_topup_transfer(ledger, Some(escrow_sub), target, cmc_amt, ICP_FEE_E8S)
                    .await
                    .map_err(|e| format!("FEE_CMC_XFER: {}", e))?;
                sale.fee_cmc_block = Some(b);
            } else {
                // No voucher canister wired (local edge) — fold into treasury.
                let dest = LedgerAccount { owner: self_id, subaccount: Some(TREASURY_SUBACCOUNT) };
                let b = call_ledger_transfer(ledger, Some(escrow_sub), dest, cmc_amt, Some(ICP_FEE_E8S))
                    .await
                    .map_err(|e| format!("FEE_CMC_FOLD_XFER: {}", e))?;
                sale.fee_cmc_block = Some(b);
                sale.cmc_notified = true;
            }
        } else {
            sale.fee_cmc_block = Some(0);
            sale.cmc_notified = true;
        }
    }
    if !sale.cmc_notified {
        let cmc = Principal::from_text("rkp4c-7iaaa-aaaaa-aaaca-cai").unwrap();
        if let Ok(target) = voucher_nft_cid() {
            notify_cmc_topup(cmc, target, sale.fee_cmc_block.unwrap(), true)
                .await
                .map_err(|e| format!("FEE_CMC_NOTIFY: {}", e))?;
        }
        sale.cmc_notified = true;
    }

    // 5. NFT mirror move (registry moves after the saga returns Ok).
    if !sale.transferred {
        voucher_nft_transfer(sale.seller, sale.buyer, sale.voucher_id).await?;
        sale.transferred = true;
    }
    Ok(())
}

// ── House buyback (15% discount; pay → burn → dissolve) ────────────────────

/// Instant exit: the CURRENT owner is paid 85% of the claim from the buyback
/// fund; the NFT burns, the registry row dies, and the underlying stake
/// splits + dissolves with its principal targeted back at the fund. NOT
/// flag-gated (it is an exit). Refuses when the fund can't cover the payout.
#[ic_cdk::update]
async fn buyback_voucher(voucher_id: u64) -> Result<u64, String> {
    require_authenticated()?;
    let caller = get_caller();
    let _guard = CallerGuard::new(caller)?;
    let _lock = StakingLock::new()?;

    // Resume an interrupted job for this voucher (any caller may nudge it,
    // but the payout leg is bound to the journaled owner).
    if let Some(job) = BUYBACK_JOBS.with(|m| m.borrow().get(&voucher_id)) {
        // Only the interrupted SAGA legs (burn / split) are caller-resumable;
        // a completed job waiting on its dissolve belongs to the sweep.
        if job.pending_unstake_id.is_none() || !job.nft_burned {
            let mut job = job;
            advance_buyback_job(&mut job).await?;
            return Ok(job.pay_e8s);
        }
        return Err("BUYBACK_IN_PROGRESS".to_string());
    }

    let v = VOUCHERS.with(|m| m.borrow().get(&voucher_id)).ok_or("VOUCHER_NOT_FOUND")?;
    if v.owner != caller {
        return Err("NOT_YOUR_VOUCHER".to_string());
    }
    if matches!(v.class, VoucherClass::LpBacked) {
        return Err("LP_NOT_ALLOWED".to_string());
    }
    if v.class != VoucherClass::Backed {
        return Err("PROMO_NOT_REDEEMABLE".to_string());
    }
    if v.listed_price_e8s.is_some() {
        return Err("LISTED: cancel the listing first".to_string());
    }
    if VOUCHER_SALES.with(|m| m.borrow().contains_key(&voucher_id)) {
        return Err("SALE_IN_PROGRESS".to_string());
    }

    let config = CONFIG.with(|cell| cell.borrow().get().clone());
    let tier = tier_from_idx(v.tier);

    // Pool guards — mirror unstake() so nothing moves if the split can't run.
    let pool = tier_pool(tier);
    if pool.neuron_id.is_none() || pool.bootstrap != StakingBootstrap::Ready {
        return Err("POOL_NOT_READY".to_string());
    }
    if pool.pending_refresh_e8s > 0 {
        return Err("REFRESH_PENDING".to_string());
    }
    if pool.total_staked_e8s.saturating_sub(v.amount_e8s) < ONE_ICP_E8S {
        return Err("POOL_FLOOR".to_string());
    }
    require_treasury_can_front(&config).await?;

    // The balance gate (owner-locked): fund must cover 85% + the pay leg fee.
    let pay_e8s = v.amount_e8s.saturating_mul(10_000 - BUYBACK_DISCOUNT_BPS) / 10_000;
    let fund = refresh_buyback_fund_cache().await;
    if fund < pay_e8s + ICP_FEE_E8S {
        return Err("BUYBACK_UNAVAILABLE".to_string());
    }

    let mut job = BuybackJob {
        voucher_id,
        owner: caller,
        tier: v.tier,
        amount_e8s: v.amount_e8s,
        pay_e8s,
        created_at: current_time(),
        pay_block: None,
        nft_burned: false,
        pending_unstake_id: None,
        spread_treasury_block: None,
        spread_cmc_block: None,
        spread_cmc_notified: false,
        spread_routed: false,
    };
    BUYBACK_JOBS.with(|m| { m.borrow_mut().insert(voucher_id, job.clone()); });
    advance_buyback_job(&mut job).await?;
    Ok(pay_e8s)
}

/// Drive a buyback job through its legs (each idempotent + journaled):
/// pay owner 85% → delete registry row → burn NFT → split + start dissolve.
/// The spread routes later, when the dissolve pays the fund (see
/// route_buyback_spreads).
async fn advance_buyback_job(job: &mut BuybackJob) -> Result<(), String> {
    let config = CONFIG.with(|cell| cell.borrow().get().clone());
    let ledger = config.ledger_canister_id;

    // 1. Pay the owner 85% from the fund.
    if job.pay_block.is_none() {
        let dest = LedgerAccount { owner: job.owner, subaccount: None };
        let b = call_ledger_transfer(ledger, Some(BUYBACK_SUBACCOUNT), dest, job.pay_e8s, Some(ICP_FEE_E8S))
            .await
            .map_err(|e| format!("BUYBACK_PAY_XFER: {}", e))?;
        job.pay_block = Some(b);
        // The claim is consumed the instant the owner is paid.
        VOUCHERS.with(|m| { m.borrow_mut().remove(&job.voucher_id); });
        BUYBACK_JOBS.with(|m| { m.borrow_mut().insert(job.voucher_id, job.clone()); });
        staking_audit("voucher_buyback_paid", job.owner, job.pay_e8s, job.voucher_id);
        let _ = refresh_buyback_fund_cache().await;
    }

    // 2. Burn the NFT (retryable).
    if !job.nft_burned {
        voucher_nft_burn(job.voucher_id).await?;
        job.nft_burned = true;
        BUYBACK_JOBS.with(|m| { m.borrow_mut().insert(job.voucher_id, job.clone()); });
    }

    // 3. Split + start dissolving, principal targeted at the fund.
    if job.pending_unstake_id.is_none() {
        let tier = tier_from_idx(job.tier);
        let mut pool = tier_pool(tier);
        let neuron_id = pool.neuron_id.ok_or("POOL_NOT_READY")?;
        fund_pool_neuron_from_treasury(&config, &mut pool, tier, ICP_FEE_E8S).await?;
        let split_neuron_id = gov_split(neuron_id, job.amount_e8s.saturating_add(ICP_FEE_E8S))
            .await
            .map_err(|e| format!("BUYBACK_SPLIT_FAILED: {}", e))?;
        let now = current_time();
        pool.total_staked_e8s = pool.total_staked_e8s.saturating_sub(job.amount_e8s);
        set_tier_pool(tier, pool);

        let id = NEXT_UNSTAKE_ID.with(|c| {
            let id = *c.borrow().get();
            c.borrow_mut().set(id + 1);
            id
        });
        let delay_ns = tier.dissolve_delay_secs().saturating_mul(1_000_000_000);
        let mut pending = PendingUnstake {
            id,
            // The house's own unstake: `user` is the canister principal and
            // the payout targets the buyback fund subaccount.
            user: get_canister_id(),
            tier,
            amount_e8s: job.amount_e8s,
            split_neuron_id,
            status: UnstakeStatus::SplitDone,
            created_at: now,
            dissolve_eta: now.saturating_add(delay_ns),
            disburse_block: None,
            fee_refund_block: None,
            merged_into: None,
            child_e8s: Some(job.amount_e8s),
            payout_subaccount: Some(BUYBACK_SUBACCOUNT),
            settled_at: None,
        };
        if gov_start_dissolving(split_neuron_id).await.is_ok() {
            pending.status = UnstakeStatus::Dissolving;
        }
        PENDING_UNSTAKES.with(|m| { m.borrow_mut().insert(id, pending); });
        job.pending_unstake_id = Some(id);
        BUYBACK_JOBS.with(|m| { m.borrow_mut().insert(job.voucher_id, job.clone()); });
        staking_audit("voucher_buyback_split", job.owner, job.amount_e8s, job.voucher_id);
    }
    Ok(())
}

/// Realize the 15% spread of every buyback whose dissolve has PAID OUT to the
/// fund: 1/3 → treasury, 1/3 stays in the fund, 1/3 → voucher-canister cycles
/// burn. Idempotent per job (block-indexed legs); called from the disburse
/// path and the sweep.
async fn route_buyback_spreads() {
    let config = CONFIG.with(|c| c.borrow().get().clone());
    let ledger = config.ledger_canister_id;
    let self_id = get_canister_id();
    let jobs: Vec<BuybackJob> = BUYBACK_JOBS.with(|m| {
        m.borrow().iter().map(|e| e.value()).filter(|j| !j.spread_routed).collect()
    });
    for mut job in jobs {
        let Some(pid) = job.pending_unstake_id else { continue };
        let disbursed = PENDING_UNSTAKES
            .with(|m| m.borrow().get(&pid))
            .map(|p| p.status == UnstakeStatus::Disbursed)
            .unwrap_or(false);
        if !disbursed {
            continue;
        }
        let spread = job.amount_e8s.saturating_mul(BUYBACK_DISCOUNT_BPS) / 10_000;
        let fund_amt = spread / 3; // stays in the fund — no transfer
        let cmc_amt = spread / 3;
        let treasury_amt = spread - fund_amt - cmc_amt;

        if job.spread_treasury_block.is_none() {
            if treasury_amt > ICP_FEE_E8S {
                let dest = LedgerAccount { owner: self_id, subaccount: Some(TREASURY_SUBACCOUNT) };
                match call_ledger_transfer(ledger, Some(BUYBACK_SUBACCOUNT), dest, treasury_amt, Some(ICP_FEE_E8S)).await {
                    Ok(b) => job.spread_treasury_block = Some(b),
                    Err(e) => {
                        canister_print(&format!("buyback spread treasury leg failed (retry next sweep): {}", e));
                        BUYBACK_JOBS.with(|m| { m.borrow_mut().insert(job.voucher_id, job.clone()); });
                        continue;
                    }
                }
            } else {
                job.spread_treasury_block = Some(0);
            }
        }
        if job.spread_cmc_block.is_none() {
            if cmc_amt > ICP_FEE_E8S {
                if let Ok(target) = voucher_nft_cid() {
                    match call_cmc_topup_transfer(ledger, Some(BUYBACK_SUBACCOUNT), target, cmc_amt, ICP_FEE_E8S).await {
                        Ok(b) => job.spread_cmc_block = Some(b),
                        Err(e) => {
                            canister_print(&format!("buyback spread cmc leg failed (retry next sweep): {}", e));
                            BUYBACK_JOBS.with(|m| { m.borrow_mut().insert(job.voucher_id, job.clone()); });
                            continue;
                        }
                    }
                } else {
                    job.spread_cmc_block = Some(0);
                    job.spread_cmc_notified = true;
                }
            } else {
                job.spread_cmc_block = Some(0);
                job.spread_cmc_notified = true;
            }
        }
        if !job.spread_cmc_notified {
            let cmc = Principal::from_text("rkp4c-7iaaa-aaaaa-aaaca-cai").unwrap();
            if let Ok(target) = voucher_nft_cid() {
                if let Err(e) = notify_cmc_topup(cmc, target, job.spread_cmc_block.unwrap(), true).await {
                    canister_print(&format!("buyback spread cmc notify failed (retry next sweep): {}", e));
                    BUYBACK_JOBS.with(|m| { m.borrow_mut().insert(job.voucher_id, job.clone()); });
                    continue;
                }
            }
            job.spread_cmc_notified = true;
        }
        job.spread_routed = true;
        BUYBACK_JOBS.with(|m| { m.borrow_mut().insert(job.voucher_id, job.clone()); });
        staking_audit("voucher_buyback_spread", job.owner, spread, job.voucher_id);
        let _ = refresh_buyback_fund_cache().await;
    }
}

/// Sweep leg: resume interrupted buyback jobs (paid-but-not-split etc.).
async fn resume_voucher_buybacks() {
    let stuck: Vec<BuybackJob> = BUYBACK_JOBS.with(|m| {
        m.borrow()
            .iter()
            .map(|e| e.value())
            .filter(|j| j.pending_unstake_id.is_none() || !j.nft_burned)
            .collect()
    });
    for mut job in stuck {
        if let Err(e) = advance_buyback_job(&mut job).await {
            canister_print(&format!("buyback resume {} pending: {}", job.voucher_id, e));
        }
    }
    route_buyback_spreads().await;
}

// ── Promo claim campaign ────────────────────────────────────────────────────

/// A self-authenticating (user) principal: 29 bytes, last byte 0x02. Rejects
/// anonymous (0x04), canister/opaque ids and malformed principals — promo
/// vouchers mint only to wallets a human can actually control.
fn is_self_authenticating(p: &Principal) -> bool {
    let b = p.as_slice();
    b.len() == 29 && b[28] == 0x02
}

/// Claim a promo voucher. `target = None` mints to the (authenticated)
/// caller; `Some(p)` is the PASTE PATH — anonymously callable so Plug/OISY
/// holders can receive without ever signing in (earning is server-side and
/// jackpots pay automatically). One per principal; global cap; daily drip.
#[ic_cdk::update]
async fn claim_promo_voucher(target: Option<Principal>) -> Result<u64, String> {
    if !feature_enabled(FLAG_STAKE_VOUCHERS) {
        return Err("FEATURE_DISABLED".to_string());
    }
    let recipient = match target {
        Some(p) => {
            if !is_self_authenticating(&p) {
                return Err("INVALID_PRINCIPAL".to_string());
            }
            p
        }
        None => {
            require_authenticated()?;
            get_caller()
        }
    };
    if is_admin_principal(recipient) {
        return Err("ADMINS_EXCLUDED".to_string());
    }
    if PROMO_CLAIMED.with(|m| m.borrow().contains_key(&recipient)) {
        return Err("ALREADY_CLAIMED".to_string());
    }
    let mut campaign = promo_campaign();
    if !campaign.open {
        return Err("CAMPAIGN_CLOSED".to_string());
    }
    if campaign.claimed >= PROMO_CAP {
        return Err("CAMPAIGN_EXHAUSTED".to_string());
    }
    let now = current_time();
    let today = now / 1_000_000_000 / SECS_PER_DAY;
    if campaign.day != today {
        campaign.day = today;
        campaign.claims_today = 0;
    }
    if campaign.claims_today >= PROMO_DAILY_DRIP {
        return Err("DAILY_LIMIT".to_string());
    }

    let id = NEXT_VOUCHER_ID.with(|c| {
        let id = *c.borrow().get();
        c.borrow_mut().set(id + 1);
        id
    });
    let expires_at = now.saturating_add(PROMO_EXPIRY_NS);
    voucher_nft_mint(id, recipient, VoucherClass::Promo, 0, 0, Some(expires_at)).await?;

    VOUCHERS.with(|m| {
        m.borrow_mut().insert(id, VoucherRecord {
            id,
            class: VoucherClass::Promo,
            tier: 0,
            amount_e8s: 0,
            owner: recipient,
            minted_at: now,
            expires_at: Some(expires_at),
            listed_price_e8s: None,
            last_purchase_grant_day: 0,
        });
    });
    campaign.claimed += 1;
    campaign.claims_today += 1;
    set_promo_campaign(campaign);
    PROMO_CLAIMED.with(|m| { m.borrow_mut().insert(recipient, 1); });
    staking_audit("promo_voucher_claim", recipient, 0, id);
    Ok(id)
}

// ── Admin ───────────────────────────────────────────────────────────────────

/// Admin: fund the buyback wallet from the TREASURY (the natural source —
/// no external wallet dance). Plain internal ledger transfer [1;32] → [10;32].
#[ic_cdk::update]
async fn admin_fund_buyback_from_treasury(amount_e8s: u64) -> Result<(), String> {
    require_admin()?;
    if amount_e8s <= ICP_FEE_E8S {
        return Err("AMOUNT_TOO_SMALL".to_string());
    }
    let config = CONFIG.with(|c| c.borrow().get().clone());
    let dest = LedgerAccount { owner: get_canister_id(), subaccount: Some(BUYBACK_SUBACCOUNT) };
    call_ledger_transfer(config.ledger_canister_id, Some(TREASURY_SUBACCOUNT), dest, amount_e8s - ICP_FEE_E8S, Some(ICP_FEE_E8S))
        .await
        .map_err(|e| format!("TREASURY_TRANSFER_FAILED: {}", e))?;
    let _ = refresh_buyback_fund_cache().await;
    staking_audit("buyback_fund_from_treasury", get_caller(), amount_e8s, 0);
    Ok(())
}

#[ic_cdk::update]
async fn admin_withdraw_buyback(to: Principal, amount_e8s: u64) -> Result<(), String> {
    require_admin()?;
    let config = CONFIG.with(|c| c.borrow().get().clone());
    let dest = LedgerAccount { owner: to, subaccount: None };
    call_ledger_transfer(config.ledger_canister_id, Some(BUYBACK_SUBACCOUNT), dest, amount_e8s, Some(ICP_FEE_E8S))
        .await
        .map_err(|e| format!("BUYBACK_WITHDRAW: {}", e))?;
    let _ = refresh_buyback_fund_cache().await;
    Ok(())
}

#[ic_cdk::update]
fn admin_set_voucher_config(fee_bps: Option<u16>, min_wrap_e8s: Option<u64>) -> Result<(), String> {
    require_admin()?;
    let mut cfg = voucher_config();
    if let Some(bps) = fee_bps {
        if bps > 2_000 {
            return Err("FEE_TOO_HIGH".to_string()); // 20% ceiling
        }
        cfg.market_fee_bps = bps;
    }
    if let Some(min) = min_wrap_e8s {
        cfg.min_wrap_e8s = min;
    }
    VOUCHER_CONFIG.with(|c| { c.borrow_mut().set(cfg); });
    Ok(())
}

#[ic_cdk::update]
fn admin_set_promo_campaign(open: bool) -> Result<(), String> {
    require_admin()?;
    let mut campaign = promo_campaign();
    campaign.open = open;
    set_promo_campaign(campaign);
    Ok(())
}

#[ic_cdk::update]
fn admin_set_voucher_nft_canister(canister: Principal) -> Result<(), String> {
    require_admin()?;
    let mut config = CONFIG.with(|c| c.borrow().get().clone());
    config.voucher_nft_canister = Some(canister);
    CONFIG.with(|c| { c.borrow_mut().set(config); });
    Ok(())
}

/// Sweep guard: keep the voucher_nft canister fueled (course_nft precedent).
async fn voucher_nft_cycle_guard() {
    let Ok(cid) = voucher_nft_cid() else { return };
    if canister_cycle_balance() < CYCLE_TOPUP_TARGET {
        return;
    }
    let Ok(cycles) = canister_status_cycles(cid).await else {
        return;
    };
    if cycles >= COURSE_NFT_CYCLE_FLOOR {
        return;
    }
    match deposit_cycles_to(cid, COURSE_NFT_TOPUP_AMOUNT).await {
        Ok(()) => canister_print(&format!(
            "voucher_nft_cycle_guard: forwarded {} cycles (balance was {})",
            COURSE_NFT_TOPUP_AMOUNT, cycles
        )),
        Err(e) => canister_print(&format!("voucher_nft_cycle_guard: deposit failed: {}", e)),
    }
}


