    #[test]
    fn test_moderation_eligibility_threshold_and_min_count() {
        // avg 1.0 (sum 5, count 5) → below 2.0 AND >= 5 ratings → eligible.
        assert!(course_eligible_for_moderation(5, 5));
        // avg 1.0 but only 2 ratings → too few to flag.
        assert!(!course_eligible_for_moderation(2, 2));
        // avg exactly 2.0 (sum 20, count 10) → NOT strictly below threshold.
        assert!(!course_eligible_for_moderation(20, 10));
        // avg 1.9 (sum 19, count 10) → eligible.
        assert!(course_eligible_for_moderation(19, 10));
        // High avg with many ratings → never eligible.
        assert!(!course_eligible_for_moderation(45, 10)); // avg 4.5
        // Zero ratings → not eligible (and no divide-by-zero).
        assert!(!course_eligible_for_moderation(0, 0));
    }

    #[test]
    fn test_admin_list_moderation_candidates_surfaces_only_eligible() {
        sale_test_setup();
        make_admin(alice());
        set_mock_caller(alice());
        // token 1: low avg (1.0), enough ratings → eligible.
        seed_listing(1, bob(), 27, 0, true);
        // token 2: low avg but only 2 ratings → NOT eligible.
        seed_listing(2, bob(), 27, 0, true);
        // token 3: plenty of ratings, high avg → NOT eligible.
        seed_listing(3, bob(), 27, 0, true);
        COURSE_LISTINGS.with(|m| {
            let mut map = m.borrow_mut();
            let mut r1 = map.get(&1).unwrap();
            r1.rating_sum = 5;
            r1.rating_count = 5; // avg 1.0
            map.insert(1, r1);
            let mut r2 = map.get(&2).unwrap();
            r2.rating_sum = 2;
            r2.rating_count = 2; // avg 1.0 but too few
            map.insert(2, r2);
            let mut r3 = map.get(&3).unwrap();
            r3.rating_sum = 40;
            r3.rating_count = 10; // avg 4.0
            map.insert(3, r3);
        });

        let rows = admin_list_moderation_candidates(50);
        let ids: Vec<u64> = rows.iter().map(|r| r.token_id).collect();
        assert_eq!(ids, vec![1], "only the eligible course is surfaced");
        let row = &rows[0];
        assert_eq!(row.owner, Some(bob()));
        assert_eq!(row.avg_x10, 10);
        assert_eq!(row.rating_count, 5);
        assert!(!row.hidden);

        // limit 0 returns nothing.
        assert!(admin_list_moderation_candidates(0).is_empty());
    }

    // ── SEEN_USERS registry ("every principal that has ever logged in") ──────

    fn clear_seen_users() {
        SEEN_USERS.with(|m| {
            let keys: Vec<Principal> = m.borrow().iter().map(|e| *e.key()).collect();
            let mut map = m.borrow_mut();
            for k in keys { map.remove(&k); }
        });
    }

    #[test]
    fn test_note_seen_inserts_first_seen() {
        clear_seen_users();
        set_mock_time(Some(1_700_000_000_000_000_000));
        let alice = Principal::from_slice(&[1; 29]);
        note_seen(alice);
        let s = SEEN_USERS.with(|m| m.borrow().get(&alice).expect("inserted"));
        assert_eq!(s.first_seen_ns, 1_700_000_000_000_000_000);
        assert_eq!(s.last_seen_ns, 1_700_000_000_000_000_000);
    }

    #[test]
    fn test_note_seen_skips_anonymous() {
        clear_seen_users();
        note_seen(Principal::anonymous());
        assert!(SEEN_USERS.with(|m| m.borrow().is_empty()));
    }

    #[test]
    fn test_note_seen_rate_limits_last_seen() {
        clear_seen_users();
        let base = 1_700_000_000_000_000_000u64;
        let alice = Principal::from_slice(&[1; 29]);
        // First sighting.
        set_mock_time(Some(base));
        note_seen(alice);
        // 30 min later — within SEEN_REFRESH_NS (1h): no write, last_seen unchanged.
        set_mock_time(Some(base + 30 * 60 * 1_000_000_000));
        note_seen(alice);
        let mid = SEEN_USERS.with(|m| m.borrow().get(&alice).unwrap());
        assert_eq!(mid.first_seen_ns, base, "first_seen never changes");
        assert_eq!(mid.last_seen_ns, base, "last_seen must not refresh within 1h");
        // 61 min after the first sighting — past the window: last_seen updates,
        // first_seen stays.
        set_mock_time(Some(base + 61 * 60 * 1_000_000_000));
        note_seen(alice);
        let after = SEEN_USERS.with(|m| m.borrow().get(&alice).unwrap());
        assert_eq!(after.first_seen_ns, base);
        assert_eq!(after.last_seen_ns, base + 61 * 60 * 1_000_000_000);
    }

    #[test]
    fn test_seen_users_appear_in_admin_union() {
        clear_seen_users();
        // A principal that ONLY triggered note_seen (no feature-map entry) must
        // still appear in the admin union so the balance view includes it.
        let lone = Principal::from_slice(&[7; 29]);
        note_seen(lone);
        let union = admin_collect_user_principals();
        assert!(union.contains(&lone), "logged-in-only principal must be in the union");
        assert!(!union.contains(&Principal::anonymous()));
    }

    #[test]
    fn test_whoami_rejects_anonymous_and_records_signed_in() {
        clear_seen_users();
        set_mock_time(Some(1_700_000_000_000_000_000));
        // Anonymous is rejected by require_authenticated().
        set_mock_caller(Principal::anonymous());
        assert!(whoami().is_err());

        // A signed-in caller is recorded and gets back its first/last seen.
        let alice = Principal::from_slice(&[1; 29]);
        set_mock_caller(alice);
        let reply = whoami().expect("signed-in whoami ok");
        assert_eq!(reply.principal, alice);
        assert_eq!(reply.first_seen_ns, 1_700_000_000_000_000_000);
        assert_eq!(reply.last_seen_ns, 1_700_000_000_000_000_000);
        assert!(SEEN_USERS.with(|m| m.borrow().contains_key(&alice)));
    }

    #[test]
    fn test_admin_list_seen_users_sorted_by_last_seen_desc() {
        clear_seen_users();
        let base = 1_700_000_000_000_000_000u64;
        let a = Principal::from_slice(&[1; 29]);
        let b = Principal::from_slice(&[2; 29]);
        let c = Principal::from_slice(&[3; 29]);
        // Insert at increasing times; the only way to set an arbitrary last_seen
        // past the 1h window is to advance the clock past it each time.
        set_mock_time(Some(base));
        note_seen(a);
        set_mock_time(Some(base + 2 * 60 * 60 * 1_000_000_000)); // +2h
        note_seen(b);
        set_mock_time(Some(base + 4 * 60 * 60 * 1_000_000_000)); // +4h
        note_seen(c);
        let rows = admin_list_seen_users();
        let order: Vec<Principal> = rows.iter().map(|(p, _)| *p).collect();
        assert_eq!(order, vec![c, b, a], "most recent login first");
        set_mock_time(None);
    }

    // ── Happy path: ordering + split (accounting ledger) ─────────────────────

    #[tokio::test]
    async fn test_buy_happy_path_splits_and_ownership() {
        sale_test_setup();
        let price = 100_000_000u64;
        seed_for_sale(1, alice(), carol(), price); // seller alice, creator carol
        set_mock_caller(bob());

        // Fund the buyer + the treasury (to front the per-leg fees) in the
        // accounting ledger.
        acct_reset();
        acct_set(bob(), None, price + 10 * ICP_FEE_E8S);
        acct_set(get_canister_id(), Some(TREASURY_SUBACCOUNT), 10 * ICP_FEE_E8S);

        buy_course_nft(1).await.unwrap();

        // Ownership moved to the buyer; listing updated, off-sale.
        assert_eq!(course_nft_owner_of(1).await.unwrap(), Some(bob()));
        let card = get_course(1).unwrap();
        assert_eq!(card.owner, Some(bob()));
        assert!(!card.for_sale);
        assert_eq!(card.price_e8s, 0);
        // Journal cleared on success.
        assert!(COURSE_SALES.with(|m| m.borrow().get(&1)).is_none());

        // Split landed: seller 75%, creator 10%, treasury >= 5%.
        let s = compute_sale_split(price, false);
        assert_eq!(acct_get(alice(), None), s.seller_amt);
        assert_eq!(acct_get(carol(), None), s.royalty_amt);
        // Treasury net: started with 10 fees, fronted per-leg fees, received its
        // 5% leg. Assert it received at least its share (fees net out via escrow).
        let treasury = acct_get(get_canister_id(), Some(TREASURY_SUBACCOUNT));
        assert!(treasury >= s.treasury_amt, "treasury got its leg: {treasury}");
        // Escrow drained to ~0.
        let escrow_sub = sale_escrow_subaccount(&bob(), 1);
        assert_eq!(acct_get(get_canister_id(), Some(escrow_sub)), 0, "escrow drained");
        acct_disable();
    }

