    #[test]
    fn test_luckproof_generation_matches_reference_ranges() {
        let gambles = luckproof_generate(luckproof_day_seed(19_900), LUCKPROOF_DAILY_DECISIONS);
        assert_eq!(gambles.len(), LUCKPROOF_DAILY_DECISIONS);
        let mut plus = 0;
        let mut minus = 0;
        for g in &gambles {
            assert!((3..=95).contains(&g.odds_pct));
            assert!((20..=100).contains(&g.risk));
            // River-call realism: the pot always pays at least the call —
            // reward/risk stays within [1.6, 5.0] (integer rounding slack).
            assert!(
                g.reward as u64 * 10 >= g.risk as u64 * 16,
                "reward ${} on ${} risk is worse than any real pot offers", g.reward, g.risk
            );
            assert!(
                g.reward as u64 <= g.risk as u64 * 5 + 1,
                "reward ${} on ${} risk is beyond a quarter-pot bet's offer", g.reward, g.risk
            );
            if luckproof_edge_bp(g) > 0 { plus += 1 } else { minus += 1 }
        }
        // The reference generator swings both ways — a fair day has both
        // (thresholds ≈ 20% of the 50-decision daily).
        assert!(plus > 10 && minus > 10, "balanced mix of +EV ({plus}) and -EV ({minus})");
        // Same day → same deal for everyone; different day differs.
        assert_eq!(
            format!("{:?}", luckproof_generate(luckproof_day_seed(19_900), 10)),
            format!("{:?}", &gambles[..10]),
        );
        assert_ne!(
            format!("{:?}", luckproof_generate(luckproof_day_seed(19_901), 10)),
            format!("{:?}", luckproof_generate(luckproof_day_seed(19_900), 10)),
        );
    }

    #[test]
    fn test_luckproof_edge_is_sklansky_ev() {
        // 60% to win $100 profit risking $50: EV = 0.6·100 − 0.4·50 = +$40.
        let g = LuckProofGamble { odds_pct: 60, risk: 50, reward: 100 };
        assert_eq!(luckproof_edge_bp(&g), 400_000);
        // 20% to win $100 risking $80: EV = 20 − 64 = −$44.
        let g2 = LuckProofGamble { odds_pct: 20, risk: 80, reward: 100 };
        assert_eq!(luckproof_edge_bp(&g2), -440_000);
    }

    #[test]
    fn test_luckproof_daily_is_stakers_only_once_per_day() {
        enable_luckproof();
        set_mock_time(Some(1_700_000_000_000_000_000));
        // Unstaked → rejected.
        set_mock_caller(alice());
        assert_eq!(start_luckproof_daily().unwrap_err(), "NOT_STAKED");
        // Staked → in.
        seed_stake(StakeTier::SixMonths, alice(), 100_000_000);
        let run = start_luckproof_daily().unwrap();
        assert_eq!(run.gambles.len(), LUCKPROOF_DAILY_DECISIONS);
        // Starting again the same day (even with the run in flight) → rejected.
        assert_eq!(start_luckproof_daily().unwrap_err(), "ALREADY_PLAYED_TODAY");
        // Complete, then still rejected today…
        let perfect: Vec<bool> = run.gambles.iter().map(|g| luckproof_edge_bp(g) > 0).collect();
        complete_luckproof_daily(run.run_id, perfect, 120_000).unwrap();
        assert_eq!(start_luckproof_daily().unwrap_err(), "ALREADY_PLAYED_TODAY");
        // …but the next UTC day re-opens.
        set_mock_time(Some(1_700_000_000_000_000_000 + 86_400 * 1_000_000_000));
        assert!(start_luckproof_daily().is_ok());
        STAKES.with(|m| { m.borrow_mut().remove(&stake_key(StakeTier::SixMonths, alice())); });
        clear_luckproof();
    }

    #[test]
    fn test_luckproof_daily_scoring_and_board_order() {
        enable_luckproof();
        set_mock_time(Some(1_700_000_000_000_000_000));
        for u in [alice(), bob()] {
            seed_stake(StakeTier::SixMonths, u, 100_000_000);
        }

        // Alice takes every +EV gamble (the optimum for EV ranking).
        set_mock_caller(alice());
        let run_a = start_luckproof_daily().unwrap();
        let optimal: Vec<bool> = run_a.gambles.iter().map(|g| luckproof_edge_bp(g) > 0).collect();
        let expected_ev: i64 = run_a.gambles.iter().map(|g| luckproof_edge_bp(g).max(0)).sum();
        let res_a = complete_luckproof_daily(run_a.run_id, optimal.clone(), 300_000).unwrap();
        assert_eq!(res_a.ev_bp, expected_ev);
        assert_eq!(res_a.correct as usize, LUCKPROOF_DAILY_DECISIONS);
        assert_eq!(res_a.rank, 1);

        // Guards.
        assert_eq!(complete_luckproof_daily(run_a.run_id, optimal.clone(), 300_000).unwrap_err(), "RUN_NOT_FOUND"); // run consumed at completion
        set_mock_caller(bob());
        assert_eq!(complete_luckproof_daily(run_a.run_id, optimal.clone(), 300_000).unwrap_err(), "RUN_NOT_FOUND");

        // Bob faces the SAME deal (fair daily), declines everything → EV 0.
        let run_b = start_luckproof_daily().unwrap();
        assert_eq!(
            format!("{:?}", run_b.gambles), format!("{:?}", run_a.gambles),
            "everyone plays the same daily deal"
        );
        assert_eq!(complete_luckproof_daily(run_b.run_id, vec![true], 300_000).unwrap_err(), "INVALID_DECISION_COUNT");
        assert_eq!(complete_luckproof_daily(run_b.run_id, vec![false; LUCKPROOF_DAILY_DECISIONS], 10).unwrap_err(), "INVALID_TIME");
        let res_b = complete_luckproof_daily(run_b.run_id, vec![false; LUCKPROOF_DAILY_DECISIONS], 200_000).unwrap();
        assert_eq!(res_b.ev_bp, 0);
        assert_eq!(res_b.bankroll_delta, 0, "declining everything has zero variance");
        assert_eq!(res_b.rank, 2, "EV ranks above accuracy/time");

        let board = get_luckproof_daily_board(None);
        assert_eq!(board.len(), 2);
        assert_eq!(board[0].player, alice());
        assert_eq!(board[0].ev_bp, expected_ev);
        assert_eq!(board[1].player, bob());

        // Status reflects eligibility + the consumed attempt.
        set_mock_caller(alice());
        let st = get_luckproof_daily_status();
        assert!(st.eligible && st.played);
        assert_eq!(st.my_entry.unwrap().ev_bp, expected_ev);

        for u in [alice(), bob()] {
            STAKES.with(|m| { m.borrow_mut().remove(&stake_key(StakeTier::SixMonths, u)); });
        }
        clear_luckproof();
    }

    #[test]
    fn test_luckproof_replay_is_verifiable_and_same_deal() {
        enable_luckproof();
        set_mock_time(Some(1_700_000_000_000_000_000));
        seed_stake(StakeTier::SixMonths, alice(), 100_000_000);
        set_mock_caller(alice());
        let run = start_luckproof_daily().unwrap();
        let decisions: Vec<bool> = run.gambles.iter().map(|g| luckproof_edge_bp(g) > 0).collect();
        let res = complete_luckproof_daily(run.run_id, decisions.clone(), 200_000).unwrap();

        // Replays are gated on competing: bob (no entry today) sees nothing…
        set_mock_caller(bob());
        assert!(
            get_luckproof_daily_replay(run.day, alice()).is_none(),
            "must compete before studying others' decisions"
        );
        // …but alice can always study her own run…
        set_mock_caller(alice());
        assert!(get_luckproof_daily_replay(run.day, alice()).is_some());
        // …and once bob competes, alice's replay opens up to him.
        seed_stake(StakeTier::SixMonths, bob(), 100_000_000);
        set_mock_caller(bob());
        let rb = start_luckproof_daily().unwrap();
        complete_luckproof_daily(rb.run_id, vec![false; LUCKPROOF_DAILY_DECISIONS], 200_000).unwrap();
        let replay = get_luckproof_daily_replay(run.day, alice()).unwrap();
        assert_eq!(replay.decisions, decisions);
        assert_eq!(replay.ev_bp, res.ev_bp);
        assert_eq!(replay.outcomes, res.outcomes, "outcomes recompute from the seed");
        // Fairness proof: the replay's deal is EXACTLY the deal the player got.
        assert_eq!(format!("{:?}", replay.gambles), format!("{:?}", run.gambles));
        // The start response's rolls match the recomputed outcomes for takes.
        for ((g, &roll), (&take, &won)) in run.gambles.iter().zip(&run.rolls).zip(decisions.iter().zip(&replay.outcomes)) {
            assert_eq!(won, take && roll < g.odds_pct as u16 * 100);
        }
        // Asking about a player with no entry → None (carol never played).
        assert!(get_luckproof_daily_replay(run.day, carol()).is_none());
        for u in [alice(), bob()] {
            STAKES.with(|m| { m.borrow_mut().remove(&stake_key(StakeTier::SixMonths, u)); });
        }
        clear_luckproof();
    }

    #[test]
    fn test_luckproof_daily_winner_gets_tickets_equal_to_player_count() {
        enable_luckproof();
        enable_lottery();
        let t0 = 1_700_000_000_000_000_000u64;
        set_mock_time(Some(t0));
        for u in [alice(), bob()] {
            seed_stake(StakeTier::SixMonths, u, 100_000_000);
        }
        // Arm the settlement pointer at "yesterday" (first-activation path).
        luckproof_daily_award();

        // Two players play today; alice takes every +EV hand, bob folds all.
        set_mock_caller(alice());
        let ra = start_luckproof_daily().unwrap();
        let opt: Vec<bool> = ra.gambles.iter().map(|g| luckproof_edge_bp(g) > 0).collect();
        complete_luckproof_daily(ra.run_id, opt, 200_000).unwrap();
        set_mock_caller(bob());
        let rb = start_luckproof_daily().unwrap();
        complete_luckproof_daily(rb.run_id, vec![false; LUCKPROOF_DAILY_DECISIONS], 200_000).unwrap();

        // Same day: no award yet.
        let before = LOTTERY_TICKETS.with(|m| m.borrow().get(&alice()).map(|e| e.count).unwrap_or(0));
        luckproof_daily_award();
        assert_eq!(
            LOTTERY_TICKETS.with(|m| m.borrow().get(&alice()).map(|e| e.count).unwrap_or(0)),
            before,
            "no award until the day rolls over"
        );

        // Day rolls over → TWO winner slots, each paying tickets = player
        // count (2): the EV champion (alice, rank #1) and the cash champion.
        // Bob folded everything → cash exactly 0; alice's cash is whatever
        // her rolls dealt, so derive the expected cash champion.
        let alice_cash = LUCKPROOF_DAILY
            .with(|m| m.borrow().get(&LuckProofDayKey { day: epoch_day(t0), player: alice() }))
            .unwrap()
            .cash;
        let cash_champ = if alice_cash >= 0 { alice() } else { bob() };
        set_mock_time(Some(t0 + 86_400 * 1_000_000_000));
        luckproof_daily_award();
        let alice_expect = 2 + if cash_champ == alice() { 2 } else { 0 };
        let bob_expect = if cash_champ == bob() { 2 } else { 0 };
        assert_eq!(
            LOTTERY_TICKETS.with(|m| m.borrow().get(&alice()).map(|e| e.count).unwrap_or(0)),
            before + alice_expect,
            "EV champion takes player-count tickets (+cash slot if she swept both)"
        );
        assert_eq!(
            LOTTERY_TICKETS.with(|m| m.borrow().get(&bob()).map(|e| e.count).unwrap_or(0)),
            bob_expect,
            "cash champion takes player-count tickets"
        );
        // Idempotent: a second sweep pass never double-pays either slot.
        luckproof_daily_award();
        assert_eq!(
            LOTTERY_TICKETS.with(|m| m.borrow().get(&alice()).map(|e| e.count).unwrap_or(0)),
            before + alice_expect
        );
        assert_eq!(
            LOTTERY_TICKETS.with(|m| m.borrow().get(&bob()).map(|e| e.count).unwrap_or(0)),
            bob_expect
        );

        for u in [alice(), bob()] {
            STAKES.with(|m| { m.borrow_mut().remove(&stake_key(StakeTier::SixMonths, u)); });
        }
        LUCKPROOF_SETTLED_DAY.with(|c| { let _ = c.borrow_mut().set(0); });
        clear_luckproof();
    }

    #[test]
    fn test_luckproof_bankroll_reflects_per_player_rolls() {
        enable_luckproof();
        set_mock_time(Some(1_700_000_000_000_000_000));
        seed_stake(StakeTier::SixMonths, alice(), 100_000_000);
        set_mock_caller(alice());
        let run = start_luckproof_daily().unwrap();
        let stored = LUCKPROOF_RUNS.with(|m| m.borrow().get(&run.run_id)).unwrap();
        let take_all = vec![true; LUCKPROOF_DAILY_DECISIONS];
        let mut expected: i64 = 0;
        for (g, &roll) in stored.gambles.iter().zip(&stored.rolls) {
            expected += if roll < g.odds_pct as u16 * 100 { g.reward as i64 } else { -(g.risk as i64) };
        }
        let res = complete_luckproof_daily(run.run_id, take_all, 200_000).unwrap();
        assert_eq!(res.bankroll_delta, expected);
        // Taking everything also earns the sum of ALL edges (good and bad).
        let all_ev: i64 = stored.gambles.iter().map(luckproof_edge_bp).sum();
        assert_eq!(res.ev_bp, all_ev);
        STAKES.with(|m| { m.borrow_mut().remove(&stake_key(StakeTier::SixMonths, alice())); });
        clear_luckproof();
    }

